package app.serpwidgets.snakemeasurer.model

import kotlinx.serialization.Serializable

/**
 * Serializable point for storage (Offset is not serializable)
 */
@Serializable
data class SerializablePoint(
    val x: Float,
    val y: Float,
    val type: PointType
)

/**
 * Sync status for cloud synchronization
 */
@Serializable
enum class SyncStatus {
    /** Not yet synced to server */
    NOT_SYNCED,
    /** Currently syncing */
    SYNCING,
    /** Successfully synced */
    SYNCED,
    /** Sync failed, will retry */
    FAILED,
    /** Local changes pending sync */
    PENDING_UPLOAD,
    /** Deleted locally, pending server deletion */
    PENDING_DELETE
}

/**
 * Represents a single saved measurement record with full data for editing
 */
@Serializable
data class MeasurementRecord(
    val id: String,
    val timestamp: Long, // Unix timestamp in milliseconds (created at)
    val snakeLengthCm: Float, // Always stored in cm for consistency
    val unit: MeasurementUnit, // Unit that was selected when measurement was taken
    val referenceLengthCm: Float, // Reference length in cm
    val snakePointCount: Int, // Number of points used for the measurement

    // Images - stored separately for efficiency
    val originalImageBase64: String? = null, // Original photo (full resolution for editing)
    val resultImageBase64: String? = null, // Image with measurement lines drawn
    val thumbnailBase64: String? = null, // Small thumbnail for fast display in history list

    // Legacy field - kept for backwards compatibility with old records
    @Deprecated("Use originalImageBase64 instead")
    val imageBase64: String? = null,

    // Full data for editing
    val referencePoints: List<SerializablePoint> = emptyList(),
    val snakePoints: List<SerializablePoint> = emptyList(),

    // Sync metadata
    val syncStatus: SyncStatus = SyncStatus.NOT_SYNCED,
    val syncedAt: Long? = null, // Timestamp of last successful sync
    val serverId: String? = null, // Server-side ID (null if not synced)
    val updatedAt: Long = timestamp // Last modification timestamp
) {
    /**
     * Get the best available image for display (migration support)
     */
    fun getDisplayImage(): String? {
        return originalImageBase64 ?: imageBase64
    }

    /**
     * Get thumbnail or fall back to original (migration support)
     */
    fun getThumbnailOrFallback(): String? {
        return thumbnailBase64 ?: originalImageBase64 ?: imageBase64
    }

    /**
     * Check if this record needs to be synced
     */
    fun needsSync(): Boolean {
        return syncStatus in listOf(
            SyncStatus.NOT_SYNCED,
            SyncStatus.PENDING_UPLOAD,
            SyncStatus.FAILED
        )
    }

    /**
     * Create a copy marked for sync
     */
    fun markForSync(currentTime: Long): MeasurementRecord {
        return copy(
            syncStatus = SyncStatus.PENDING_UPLOAD,
            updatedAt = currentTime
        )
    }

    /**
     * Create a copy marked as synced
     */
    fun markAsSynced(serverId: String, syncTime: Long): MeasurementRecord {
        return copy(
            syncStatus = SyncStatus.SYNCED,
            syncedAt = syncTime,
            serverId = serverId
        )
    }
}

/**
 * Container for measurement history
 * Maintains only the last 10 measurements
 */
@Serializable
data class MeasurementHistory(
    val records: List<MeasurementRecord> = emptyList()
) {
    companion object {
        const val MAX_RECORDS = 10
    }

    /**
     * Add a new record, keeping only the specified max number of measurements
     * @param record The record to add
     * @param maxRecords Maximum number of records to keep (default: MAX_RECORDS)
     */
    fun addRecord(record: MeasurementRecord, maxRecords: Int = MAX_RECORDS): MeasurementHistory {
        val updatedRecords = (records + record)
            .sortedByDescending { it.timestamp }
            .take(maxRecords)
        return copy(records = updatedRecords)
    }

    /**
     * Remove a record by ID
     */
    fun removeRecord(id: String): MeasurementHistory {
        return copy(records = records.filter { it.id != id })
    }

    /**
     * Get records sorted by timestamp (newest first)
     */
    fun getSortedRecords(): List<MeasurementRecord> {
        return records.sortedByDescending { it.timestamp }
    }
}
