package app.serpwidgets.snakemeasurer.model

import kotlinx.serialization.Serializable

/**
 * Tracks tutorial state and which help hints the user has seen.
 */
@Serializable
data class HelpState(
    // Tutorial completed or skipped
    val tutorialCompleted: Boolean = false,

    // Tutorial is currently active
    val tutorialActive: Boolean = false,

    // Current step in tutorial (null if not active)
    val currentStep: TutorialStep = TutorialStep.WELCOME
)

/**
 * Steps in the interactive tutorial.
 * Each step highlights a specific UI element and waits for user action.
 */
enum class TutorialStep {
    /** Welcome screen - offer to start tutorial */
    WELCOME,

    /** Spotlight on upload button - wait for image load */
    UPLOAD_PHOTO,

    /** Spotlight on canvas - wait for 2 reference points */
    PLACE_REFERENCE_POINTS,

    /** Spotlight on Size Input Modal - wait for size input */
    SET_REFERENCE_SIZE,

    /** Tip: highlight Set Size button, explain you can always change it */
    SIZE_BUTTON_TIP,

    /** Spotlight on Snake mode button - wait for mode switch */
    SWITCH_TO_SNAKE,

    /** Spotlight on canvas - wait for snake points (min 2) */
    PLACE_SNAKE_POINTS,

    /** Tip: long press to select point, drag to move */
    DRAG_POINTS_TIP,

    /** Tip: undo button to remove last point */
    UNDO_TIP,

    /** Spotlight on Save button - save when ready */
    SAVE_RESULT,

    /** Tip: view history after saving */
    HISTORY_TIP,

    /** Tutorial completed */
    COMPLETED
}
