package app.serpwidgets.snakemeasurer.util

import kotlinx.coroutines.await
import app.serpwidgets.snakemeasurer.model.AuthProvider
import app.serpwidgets.snakemeasurer.model.AuthResult
import app.serpwidgets.snakemeasurer.model.AuthUser
import kotlin.js.Promise

/**
 * Web Firebase Auth implementation using Firebase JS SDK.
 * Waits for Firebase to be loaded (deferred loading from index.html).
 */
actual object AuthService {
    private val authStateListeners = mutableListOf<(AuthUser?) -> Unit>()
    private var initialized = false

    actual fun initialize() {
        if (initialized) return
        initialized = true

        // Wait for Firebase to be ready (loaded asynchronously)
        js("""
            function doInit() {
                if (window.firebase && window.firebase.auth) {
                    window.firebaseAuth = window.firebase.auth();
                    window.firebaseAuth.onAuthStateChanged(function(user) {
                        window.currentFirebaseUser = user;
                    });
                } else {
                    setTimeout(doInit, 100);
                }
            }
            if (window._firebaseReadyPromise) {
                window._firebaseReadyPromise.then(doInit);
            } else {
                doInit();
            }
        """)
    }

    actual fun getCurrentUser(): AuthUser? {
        return try {
            val user = js("window.currentFirebaseUser")
            if (user != null && user != undefined) {
                parseFirebaseUser(user)
            } else {
                null
            }
        } catch (e: Exception) {
            null
        }
    }

    actual suspend fun signInWithGoogle(): AuthResult {
        return try {
            ensureFirebaseAuth()
            val result = signInWithGoogleJS().await()
            val user = parseFirebaseUser(result)
            if (user != null) {
                notifyListeners(user)
                AuthResult.Success(user)
            } else {
                AuthResult.Error("Failed to get user")
            }
        } catch (e: Exception) {
            val message = e.message ?: "Google sign in failed"
            if (message.contains("popup-closed") || message.contains("cancelled")) {
                AuthResult.Cancelled
            } else {
                AuthResult.Error(message)
            }
        }
    }

    actual suspend fun signInWithApple(): AuthResult {
        return try {
            ensureFirebaseAuth()
            val result = signInWithAppleJS().await()
            val user = parseFirebaseUser(result)
            if (user != null) {
                notifyListeners(user)
                AuthResult.Success(user)
            } else {
                AuthResult.Error("Failed to get user")
            }
        } catch (e: Exception) {
            val message = e.message ?: "Apple sign in failed"
            if (message.contains("popup-closed") || message.contains("cancelled")) {
                AuthResult.Cancelled
            } else {
                AuthResult.Error(message)
            }
        }
    }

    actual suspend fun signInWithFacebook(): AuthResult {
        return try {
            ensureFirebaseAuth()
            val result = signInWithFacebookJS().await()
            val user = parseFirebaseUser(result)
            if (user != null) {
                notifyListeners(user)
                AuthResult.Success(user)
            } else {
                AuthResult.Error("Failed to get user")
            }
        } catch (e: Exception) {
            val message = e.message ?: "Facebook sign in failed"
            if (message.contains("popup-closed") || message.contains("cancelled")) {
                AuthResult.Cancelled
            } else {
                AuthResult.Error(message)
            }
        }
    }

    actual suspend fun signInWithEmail(email: String, password: String): AuthResult {
        return try {
            ensureFirebaseAuth()
            val result = signInWithEmailJS(email, password).await()
            val user = parseFirebaseUser(result)
            if (user != null) {
                notifyListeners(user)
                AuthResult.Success(user)
            } else {
                AuthResult.Error("Failed to get user")
            }
        } catch (e: Exception) {
            AuthResult.Error(e.message ?: "Email sign in failed")
        }
    }

    actual suspend fun createAccountWithEmail(email: String, password: String): AuthResult {
        return try {
            ensureFirebaseAuth()
            val result = createAccountWithEmailJS(email, password).await()
            val user = parseFirebaseUser(result)
            if (user != null) {
                notifyListeners(user)
                AuthResult.Success(user)
            } else {
                AuthResult.Error("Failed to create user")
            }
        } catch (e: Exception) {
            AuthResult.Error(e.message ?: "Account creation failed")
        }
    }

    actual suspend fun sendPasswordResetEmail(email: String): Boolean {
        return try {
            ensureFirebaseAuth()
            sendPasswordResetEmailJS(email).await()
            true
        } catch (e: Exception) {
            false
        }
    }

    actual suspend fun signOut() {
        try {
            ensureFirebaseAuth()
            signOutJS().await()
            notifyListeners(null)
        } catch (e: Exception) {
            console.error("Sign out failed:", e.message)
        }
    }

    actual suspend fun deleteAccount(): Boolean {
        ensureFirebaseAuth()
        deleteAccountJS().await()
        notifyListeners(null)
        return true
    }

    actual fun addAuthStateListener(listener: (AuthUser?) -> Unit) {
        authStateListeners.add(listener)
        listener(getCurrentUser())
    }

    actual fun removeAuthStateListener(listener: (AuthUser?) -> Unit) {
        authStateListeners.remove(listener)
    }

    private fun notifyListeners(user: AuthUser?) {
        authStateListeners.forEach { it(user) }
    }

    /** Waits for window.firebaseAuth to be available */
    private suspend fun ensureFirebaseAuth() {
        val ready: Promise<dynamic> = js("""
            new Promise(function(resolve) {
                function check() {
                    if (window.firebaseAuth) { resolve(); }
                    else { setTimeout(check, 50); }
                }
                check();
            })
        """)
        ready.await()
    }

    private fun parseFirebaseUser(jsUser: dynamic): AuthUser? {
        if (jsUser == null || jsUser == undefined) return null

        val user = jsUser.user ?: jsUser

        val uid = user.uid as? String ?: return null
        val email = user.email as? String
        val displayName = user.displayName as? String
        val photoUrl = user.photoURL as? String

        // Determine provider
        val providerData = user.providerData
        var provider = AuthProvider.EMAIL
        if (providerData != null && providerData != undefined) {
            val providers = providerData as Array<dynamic>
            for (p in providers) {
                when (p.providerId as? String) {
                    "google.com" -> provider = AuthProvider.GOOGLE
                    "apple.com" -> provider = AuthProvider.APPLE
                    "facebook.com" -> provider = AuthProvider.FACEBOOK
                }
            }
        }

        return AuthUser(
            uid = uid,
            email = email,
            displayName = displayName,
            photoUrl = photoUrl,
            provider = provider
        )
    }
}

// External JS functions
private fun signInWithGoogleJS(): Promise<dynamic> = js("""
    (function() {
        var provider = new firebase.auth.GoogleAuthProvider();
        return window.firebaseAuth.signInWithPopup(provider);
    })()
""")

private fun signInWithAppleJS(): Promise<dynamic> = js("""
    (function() {
        var provider = new firebase.auth.OAuthProvider('apple.com');
        provider.addScope('email');
        provider.addScope('name');
        return window.firebaseAuth.signInWithPopup(provider);
    })()
""")

private fun signInWithFacebookJS(): Promise<dynamic> = js("""
    (function() {
        var provider = new firebase.auth.FacebookAuthProvider();
        provider.addScope('email');
        return window.firebaseAuth.signInWithPopup(provider);
    })()
""")

private fun signInWithEmailJS(email: String, password: String): Promise<dynamic> = js("""
    window.firebaseAuth.signInWithEmailAndPassword(email, password)
""")

private fun createAccountWithEmailJS(email: String, password: String): Promise<dynamic> = js("""
    window.firebaseAuth.createUserWithEmailAndPassword(email, password)
""")

private fun sendPasswordResetEmailJS(email: String): Promise<dynamic> = js("""
    window.firebaseAuth.sendPasswordResetEmail(email)
""")

private fun signOutJS(): Promise<dynamic> = js("""
    window.firebaseAuth.signOut()
""")

private fun deleteAccountJS(): Promise<dynamic> = js("""
    window.firebaseAuth.currentUser.delete()
""")

private external val undefined: dynamic
