package app.serpwidgets.snakemeasurer.util

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.toComposeImageBitmap
import kotlinx.browser.document
import kotlinx.browser.window
import org.jetbrains.skia.Image
import org.khronos.webgl.ArrayBuffer
import org.khronos.webgl.Int8Array
import org.khronos.webgl.get
import org.w3c.dom.HTMLInputElement
import org.w3c.dom.url.URL
import org.w3c.files.FileReader
import org.w3c.files.get

@Composable
actual fun rememberImagePicker(
    onImageSelected: (ImageBitmap, String) -> Unit
): () -> Unit {
    return remember {
        {
            launchFilePicker(onImageSelected, useCamera = false)
        }
    }
}

@Composable
actual fun rememberImagePickerWithSource(
    onImageSelected: (ImageBitmap, String) -> Unit
): (ImageSource) -> Unit {
    return remember {
        { source ->
            when (source) {
                ImageSource.GALLERY -> launchFilePicker(onImageSelected, useCamera = false)
                ImageSource.CAMERA -> launchFilePicker(onImageSelected, useCamera = true)
            }
        }
    }
}

actual fun isCameraAvailable(): Boolean {
    // Check if mediaDevices API is available (indicates camera support)
    return js("!!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia)") as Boolean
}

// Keep references to prevent garbage collection on iOS Safari
private var activeReader: FileReader? = null
private var activeInput: HTMLInputElement? = null

private fun launchFilePicker(
    onImageSelected: (ImageBitmap, String) -> Unit,
    useCamera: Boolean
) {
    // Create a hidden file input element
    val input = document.createElement("input") as HTMLInputElement
    activeInput = input // Keep reference for iOS
    input.type = "file"
    input.accept = "image/*"

    // For camera capture on mobile devices
    if (useCamera) {
        input.setAttribute("capture", "environment")
    }

    // iOS Safari fix: add to DOM temporarily
    input.style.position = "fixed"
    input.style.top = "-9999px"
    input.style.left = "-9999px"
    document.body?.appendChild(input)

    input.onchange = { _ ->
        val file = input.files?.get(0)
        if (file != null) {
            readFileWithRetry(file, input, onImageSelected, maxRetries = 3, currentRetry = 0)
        } else {
            // No file selected - cleanup
            cleanupInput(input)
        }
        null
    }

    // Trigger the file picker
    input.click()
}

private fun readFileWithRetry(
    file: org.w3c.files.File,
    input: HTMLInputElement,
    onImageSelected: (ImageBitmap, String) -> Unit,
    maxRetries: Int,
    currentRetry: Int
) {
    val reader = FileReader()
    activeReader = reader // Keep reference for iOS to prevent GC

    reader.onload = {
        try {
            val arrayBuffer = reader.result as ArrayBuffer
            val byteArray = Int8Array(arrayBuffer)
            val bytes = ByteArray(byteArray.length) { byteArray[it] }

            val image = Image.makeFromEncoded(bytes)
            val imageBitmap = image.toComposeImageBitmap()

            // Create object URL for the file
            val objectUrl = URL.createObjectURL(file)
            onImageSelected(imageBitmap, objectUrl)

            // Cleanup on success
            cleanupInput(input)
            activeReader = null
        } catch (e: Exception) {
            console.log("Error decoding image (attempt ${currentRetry + 1}): ${e.message}")
            if (currentRetry < maxRetries - 1) {
                // Retry with delay (exponential backoff: 100ms, 200ms, 400ms)
                val delay = 100 * (1 shl currentRetry)
                window.setTimeout({
                    readFileWithRetry(file, input, onImageSelected, maxRetries, currentRetry + 1)
                }, delay)
            } else {
                window.alert("Error loading image after $maxRetries attempts: ${e.message}")
                cleanupInput(input)
                activeReader = null
            }
        }
        null
    }

    reader.onerror = {
        console.log("FileReader error (attempt ${currentRetry + 1}): ${reader.error}")
        if (currentRetry < maxRetries - 1) {
            // Retry with delay
            val delay = 100 * (1 shl currentRetry)
            window.setTimeout({
                readFileWithRetry(file, input, onImageSelected, maxRetries, currentRetry + 1)
            }, delay)
        } else {
            window.alert("Error loading image after $maxRetries attempts")
            cleanupInput(input)
            activeReader = null
        }
        null
    }

    // Add timeout for iOS Safari (30 seconds)
    val timeoutId = window.setTimeout({
        if (reader.readyState == FileReader.LOADING) {
            console.log("FileReader timeout (attempt ${currentRetry + 1})")
            reader.abort()
            if (currentRetry < maxRetries - 1) {
                val delay = 100 * (1 shl currentRetry)
                window.setTimeout({
                    readFileWithRetry(file, input, onImageSelected, maxRetries, currentRetry + 1)
                }, delay)
            } else {
                window.alert("Image loading timed out after $maxRetries attempts")
                cleanupInput(input)
                activeReader = null
            }
        }
    }, 30000)

    // Clear timeout on successful load
    val originalOnload = reader.onload
    reader.onload = { event ->
        window.clearTimeout(timeoutId)
        originalOnload?.invoke(event)
    }

    reader.readAsArrayBuffer(file)
}

private fun cleanupInput(input: HTMLInputElement) {
    try {
        document.body?.removeChild(input)
    } catch (e: Exception) {
        // Input might already be removed
    }
    activeInput = null
}
