package app.serpwidgets.snakemeasurer.ui.components.modals

import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.text.BasicTextField
import androidx.compose.foundation.text.KeyboardActions
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.ColorFilter
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.platform.LocalSoftwareKeyboardController
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import app.serpwidgets.snakemeasurer.model.Language
import app.serpwidgets.snakemeasurer.model.MeasurementUnit
import app.serpwidgets.snakemeasurer.ui.stringResource
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.ui.theme.Shapes
import app.serpwidgets.snakemeasurer.ui.theme.Spacing
import app.serpwidgets.snakemeasurer.ui.theme.IconButtonDimens
import org.jetbrains.compose.resources.painterResource
import snakemeasurer.composeapp.generated.resources.Res
import snakemeasurer.composeapp.generated.resources.ic_close

@Composable
fun SizeInputModal(
    currentSize: Float,
    currentUnit: MeasurementUnit,
    onSizeSet: (Float, MeasurementUnit) -> Unit,
    onDismiss: () -> Unit,
    language: Language
) {
    val colors = AppTheme.colors
    val keyboardController = LocalSoftwareKeyboardController.current
    var sizeText by remember { mutableStateOf(if (currentSize > 0) currentSize.toString() else "") }
    var selectedUnit by remember { mutableStateOf(currentUnit) }

    // Backdrop - no dismiss on click to prevent accidental closure
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.6f)),
        contentAlignment = Alignment.Center
    ) {
        // Modal content
        Column(
            modifier = Modifier
                .widthIn(max = 450.dp)
                .fillMaxWidth(0.95f)
                .clip(Shapes.modal)
                .background(colors.bgTertiary)
                .clickable(enabled = false) {} // Prevent click through
                .imePadding()
                .verticalScroll(rememberScrollState())
                .padding(Spacing.xl),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Close button row
            Box(
                modifier = Modifier.fillMaxWidth()
            ) {
                Box(
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .size(IconButtonDimens.size)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(onClick = onDismiss),
                    contentAlignment = Alignment.Center
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_close),
                        contentDescription = stringResource("close"),
                        modifier = Modifier.size(IconButtonDimens.iconSize),
                        colorFilter = ColorFilter.tint(colors.textPrimary)
                    )
                }
            }

            Spacer(modifier = Modifier.height(Spacing.xs))

            // Title
            Text(
                text = stringResource("reference_size"),
                color = colors.textPrimary,
                style = AppTheme.typography.displaySmall
            )

            Spacer(modifier = Modifier.height(Spacing.xs))

            Text(
                text = stringResource("enter_reference_size_hint"),
                color = colors.textTertiary,
                style = AppTheme.typography.bodyMedium,
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(Spacing.xl))

            // Size input
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.large)
                    .background(colors.bgSecondary)
                    .border(
                        width = 2.dp,
                        color = if (sizeText.isNotEmpty()) colors.reference else colors.border,
                        shape = Shapes.large
                    )
                    .padding(Spacing.md)
            ) {
                BasicTextField(
                    value = sizeText,
                    onValueChange = { sizeText = it },
                    textStyle = AppTheme.typography.headlineMedium.copy(
                        color = colors.textPrimary,
                        textAlign = TextAlign.Center
                    ),
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Decimal,
                        imeAction = ImeAction.Done
                    ),
                    keyboardActions = KeyboardActions(
                        onDone = {
                            keyboardController?.hide()
                            val sizeValue = sizeText.toFloatOrNull()
                            if (sizeValue != null && sizeValue > 0) {
                                onSizeSet(sizeValue, selectedUnit)
                            }
                        }
                    ),
                    singleLine = true,
                    cursorBrush = SolidColor(colors.reference),
                    modifier = Modifier.fillMaxWidth(),
                    decorationBox = { innerTextField ->
                        Box(
                            modifier = Modifier.fillMaxWidth(),
                            contentAlignment = Alignment.Center
                        ) {
                            if (sizeText.isEmpty()) {
                                Text(
                                    text = stringResource("enter_size"),
                                    color = colors.textTertiary,
                                    style = AppTheme.typography.headlineMedium
                                )
                            }
                            innerTextField()
                        }
                    }
                )
            }

            // Error message
            val hasInput = sizeText.isNotEmpty()
            val parsedValue = sizeText.toFloatOrNull()
            val showError = hasInput && (parsedValue == null || parsedValue <= 0)

            if (showError) {
                Spacer(modifier = Modifier.height(Spacing.xs))
                Text(
                    text = stringResource("invalid_size_error"),
                    color = colors.danger,
                    style = AppTheme.typography.bodySmall,
                    textAlign = TextAlign.Center
                )
            }

            Spacer(modifier = Modifier.height(Spacing.md))

            // Unit selector
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
            ) {
                MeasurementUnit.entries.forEach { unit ->
                    UnitButton(
                        text = unit.getLocalizedAbbreviation(language),
                        isSelected = unit == selectedUnit,
                        onClick = { selectedUnit = unit },
                        modifier = Modifier.weight(1f)
                    )
                }
            }

            Spacer(modifier = Modifier.height(Spacing.xl))

            // Confirm button
            val sizeValue = sizeText.toFloatOrNull()
            val isValid = sizeValue != null && sizeValue > 0

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.large)
                    .background(if (isValid) colors.reference else colors.bgSecondary)
                    .then(
                        if (isValid && sizeValue != null) Modifier.clickable {
                            onSizeSet(sizeValue, selectedUnit)
                        } else Modifier
                    )
                    .padding(Spacing.md),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("done"),
                    color = if (isValid) Color.White else colors.textTertiary,
                    style = AppTheme.typography.titleLarge
                )
            }
        }
    }
}

@Composable
private fun UnitButton(
    text: String,
    isSelected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors

    Box(
        modifier = modifier
            .clip(Shapes.medium)
            .background(if (isSelected) colors.reference else colors.bgSecondary)
            .clickable(onClick = onClick)
            .padding(Spacing.sm),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = text,
            color = if (isSelected) Color.White else colors.textPrimary,
            style = AppTheme.typography.titleLarge
        )
    }
}
