import app.serpwidgets.snakemeasurer.ui.tutorial.TutorialTargetBox

/**
 * State needed for TopHeaderBar
 */
data class TopHeaderBarState(
    val hasImage: Boolean,
    val isViewingHistory: Boolean,
    val hasReferenceComplete: Boolean,
    val referenceLengthCm: Float,
    val hasResult: Boolean,
    val isLoggedIn: Boolean,
    val userName: String?,
    val selectedUnit: MeasurementUnit,
    val currentLanguage: Language,
    // Pre-formatted values (to avoid ViewModel dependency)
    val formattedReferenceLength: String,
    val formattedResult: String
)

/**
 * Top header bar with replace button, size display, save button, and menu.
 * Used in portrait phone layout.
 */
@Composable
fun TopHeaderBar(
    state: TopHeaderBarState,
    onLoadImage: () -> Unit,
    onAction: (MeasurementAction) -> Unit,
    isCompact: Boolean = false
) {
    val colors = AppTheme.colors

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(colors.bgTertiary)
            .statusBarsPadding()
    ) {
        BoxWithConstraints(
            modifier = Modifier
                .fillMaxWidth()
                .height(48.dp)
        ) {
            // Dynamic sizing based on available width
            val isNarrow = maxWidth < 360.dp
            val horizontalPadding = if (isNarrow) 6.dp else 12.dp
            val itemSpacing = if (isNarrow) 4.dp else 6.dp

            Row(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = horizontalPadding),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(itemSpacing)
            ) {
                // Replace button - only when image loaded and not in view mode
                if (state.hasImage && !state.isViewingHistory) {
                    IconButton(
                        icon = "refresh",
                        onClick = onLoadImage
                    )
                }

                // Divider
                if (state.hasImage && !state.isViewingHistory) {
                    Box(
                        modifier = Modifier
                            .width(1.dp)
                            .height(20.dp)
                            .background(colors.border)
                    )
                }

                // Size button (when reference complete)
                AnimatedVisibility(
                    visible = state.hasReferenceComplete,
                    enter = fadeIn() + expandHorizontally(),
                    exit = fadeOut() + shrinkHorizontally()
                ) {
                    if (state.referenceLengthCm > 0) {
                        // Size display - clickable to edit (wrapped for SIZE_BUTTON_TIP)
                        TutorialTargetBox(step = TutorialStep.SIZE_BUTTON_TIP) {
                            Box(
                                modifier = Modifier
                                    .height(HeaderButtonSize)
                                    .clip(Shapes.small)
                                    .background(colors.bgSecondary)
                                    .border(1.5.dp, colors.reference, Shapes.small)
                                    .clickable { onAction(MeasurementAction.ShowSizeModal) }
                                    .padding(horizontal = 8.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = state.formattedReferenceLength,
                                    color = colors.textPrimary,
                                    style = AppTheme.typography.labelMedium
                                )
                            }
                        }
                    } else {
                        // Size button with pulse effect
                        Box(
                            modifier = Modifier
                                .height(HeaderButtonSize)
                                .clip(Shapes.small)
                                .background(colors.reference)
                                .clickable { onAction(MeasurementAction.ShowSizeModal) }
                                .padding(horizontal = 8.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = stringResource("set_size"),
                                color = Color.White,
                                style = AppTheme.typography.labelMedium
                            )
                        }
                    }
                }

                // Result + Save combined (like fullscreen mode)
                AnimatedVisibility(
                    visible = state.hasResult,
                    enter = fadeIn() + expandHorizontally(),
                    exit = fadeOut() + shrinkHorizontally()
                ) {
                    TutorialTargetBox(step = TutorialStep.SAVE_RESULT) {
                        Box(
                            modifier = Modifier
                                .height(HeaderButtonSize)
                                .clip(Shapes.small)
                                .background(colors.success)
                                .then(
                                    if (!state.isViewingHistory) {
                                        Modifier.clickable { onAction(MeasurementAction.SaveMeasurement) }
                                    } else Modifier
                                )
                                .padding(horizontal = 8.dp),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = if (state.isViewingHistory) {
                                    state.formattedResult
                                } else {
                                    "${stringResource("save")} ${state.formattedResult}"
                                },
                                color = Color.White,
                                style = AppTheme.typography.labelMedium
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.weight(1f))

                // TODO: Restore ProfileAvatarButton when backend auth is ready
                // ProfileAvatarButton(
                //     isLoggedIn = state.isLoggedIn,
                //     userName = state.userName,
                //     onClick = {
                //         if (state.isLoggedIn) {
                //             onAction(MeasurementAction.ShowAccountModal)
                //         } else {
                //             onAction(MeasurementAction.ShowAuthProvidersModal)
                //         }
                //     }
                // )

                // Menu button (opens bottom sheet)
                IconButton(
                    icon = "menu",
                    onClick = { onAction(MeasurementAction.ShowBottomSheet) }
                )
            }
        }
    }
}
