package app.serpwidgets.snakemeasurer.model

import kotlinx.serialization.Serializable

/**
 * Tracks user usage for free tier limits
 */
@Serializable
data class UsageTracker(
    val measurementsThisMonth: Int = 0,
    val monthStartTimestamp: Long = 0 // Start of current tracking month
) {
    companion object {
        // Milliseconds in a month (approximate - 30 days)
        private const val MONTH_MS = 30L * 24 * 60 * 60 * 1000

        fun isNewMonth(tracker: UsageTracker, currentTime: Long): Boolean {
            return currentTime - tracker.monthStartTimestamp >= MONTH_MS
        }
    }

    /**
     * Reset counter for new month
     */
    fun resetForNewMonth(currentTime: Long): UsageTracker {
        return UsageTracker(
            measurementsThisMonth = 0,
            monthStartTimestamp = currentTime
        )
    }

    /**
     * Increment measurement count
     */
    fun incrementMeasurement(): UsageTracker {
        return copy(measurementsThisMonth = measurementsThisMonth + 1)
    }

    /**
     * Check if user can make a measurement (free tier)
     */
    fun canMeasure(): Boolean {
        return measurementsThisMonth < PremiumFeatures.FREE_MEASUREMENTS_PER_MONTH
    }

    /**
     * Get remaining measurements for free tier
     */
    fun remainingMeasurements(): Int {
        return (PremiumFeatures.FREE_MEASUREMENTS_PER_MONTH - measurementsThisMonth).coerceAtLeast(0)
    }
}
