@Composable
fun PaywallModal(
    remainingMeasurements: Int,
    onPurchase: (PremiumProduct) -> Unit,
    onRestore: () -> Unit,
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors

    // Backdrop
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.6f))
            .clickable(onClick = onDismiss),
        contentAlignment = Alignment.Center
    ) {
        // Modal content
        Column(
            modifier = Modifier
                .widthIn(max = 400.dp)
                .fillMaxWidth(0.95f)
                .heightIn(max = 600.dp)
                .fillMaxHeight(0.95f)
                .clip(Shapes.modal)
                .background(colors.bgTertiary)
                .clickable(enabled = false) {}
        ) {
            // Header with close button
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(Spacing.md)
            ) {
                // Close button
                Box(
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .size(IconButtonDimens.size)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(onClick = onDismiss),
                    contentAlignment = Alignment.Center
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_close),
                        contentDescription = stringResource("close"),
                        modifier = Modifier.size(IconButtonDimens.iconSize),
                        colorFilter = ColorFilter.tint(colors.textPrimary)
                    )
                }
            }

            // Content
            Column(
                modifier = Modifier
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = Spacing.xl)
                    .padding(bottom = Spacing.xl),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // Premium badge
                Box(
                    modifier = Modifier
                        .size(64.dp)
                        .clip(Shapes.extraLarge)
                        .background(colors.snake.copy(alpha = 0.15f)),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = stringResource("pro"),
                        color = colors.snake,
                        style = AppTheme.typography.displaySmall
                    )
                }

                Spacer(modifier = Modifier.height(Spacing.md))

                // Title
                Text(
                    text = stringResource("unlock_premium"),
                    color = colors.textPrimary,
                    style = AppTheme.typography.displayMedium
                )

                Spacer(modifier = Modifier.height(Spacing.xs))

                // Subtitle - show remaining measurements if applicable
                if (remainingMeasurements <= 0) {
                    Text(
                        text = stringResource("reached_free_limit"),
                        color = colors.textSecondary,
                        style = AppTheme.typography.bodyMedium,
                        textAlign = TextAlign.Center
                    )
                } else {
                    Text(
                        text = stringResource("n_measurements_remaining").replace("%d", remainingMeasurements.toString()),
                        color = colors.textSecondary,
                        style = AppTheme.typography.bodyMedium,
                        textAlign = TextAlign.Center
                    )
                }

                Spacer(modifier = Modifier.height(Spacing.xl))

                // Features list
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(Shapes.large)
                        .background(colors.bgSecondary)
                        .padding(Spacing.md),
                    verticalArrangement = Arrangement.spacedBy(Spacing.sm)
                ) {
                    FeatureRow(text = stringResource("unlimited_measurements"))
                    FeatureRow(text = stringResource("unlimited_history"))
                    FeatureRow(text = stringResource("one_time_purchase"))
                    FeatureRow(text = stringResource("support_development"))
                }

                Spacer(modifier = Modifier.height(Spacing.xl))

                // Free tier info
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = stringResource("free_tier_includes"),
                        color = colors.textTertiary,
                        style = AppTheme.typography.caption
                    )
                    Text(
                        text = stringResource("n_measurements_per_month").replace("%d", PremiumFeatures.FREE_MEASUREMENTS_PER_MONTH.toString()),
                        color = colors.textTertiary,
                        style = AppTheme.typography.caption
                    )
                }

                Spacer(modifier = Modifier.height(Spacing.xl))

                // Purchase button
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(Shapes.large)
                        .background(colors.snake)
                        .clickable { onPurchase(PremiumProduct.LIFETIME) }
                        .padding(vertical = Spacing.md),
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(
                            text = stringResource("get_premium"),
                            color = Color.White,
                            style = AppTheme.typography.titleLarge
                        )
                        Text(
                            text = stringResource("price_lifetime").replace("%s", PremiumProduct.LIFETIME.price),
                            color = Color.White.copy(alpha = 0.8f),
                            style = AppTheme.typography.bodySmall
                        )
                    }
                }

                Spacer(modifier = Modifier.height(Spacing.sm))

                // Restore purchases button
                Text(
                    text = stringResource("restore_purchases"),
                    color = colors.snake,
                    style = AppTheme.typography.labelLarge,
                    modifier = Modifier
                        .clickable(onClick = onRestore)
                        .padding(Spacing.xs)
                )

                Spacer(modifier = Modifier.height(Spacing.xs))

                // Continue with free
                Text(
                    text = stringResource("continue_with_free"),
                    color = colors.textTertiary,
                    style = AppTheme.typography.bodySmall,
                    modifier = Modifier
                        .clickable(onClick = onDismiss)
                        .padding(Spacing.xs)
                )
            }
        }
    }
}

@Composable
private fun FeatureRow(text: String) {
    val colors = AppTheme.colors

    Row(
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(Spacing.sm)
    ) {
        // Green dot indicator
        Box(
            modifier = Modifier
                .size(8.dp)
                .clip(CircleShape)
                .background(colors.success)
        )
        Text(
            text = text,
            color = colors.textPrimary,
            style = AppTheme.typography.bodyMedium
        )
    }
}
