package app.serpwidgets.snakemeasurer.util

import app.serpwidgets.snakemeasurer.model.CookieConsent
import app.serpwidgets.snakemeasurer.model.HelpState
import app.serpwidgets.snakemeasurer.model.MeasurementHistory
import app.serpwidgets.snakemeasurer.model.SubscriptionState
import app.serpwidgets.snakemeasurer.model.UsageTracker

/**
 * Interface for platform-specific storage implementations.
 * - Mobile (Android/iOS): SQLDelight database
 * - Web (JS/WASM): IndexedDB + localStorage
 */
interface MeasurementStorage {
    /**
     * Save measurement history to persistent storage
     */
    fun saveHistory(history: MeasurementHistory)

    /**
     * Load measurement history from persistent storage
     */
    fun loadHistory(): MeasurementHistory

    /**
     * Save selected language to persistent storage
     */
    fun saveLanguage(languageCode: String)

    /**
     * Load selected language from persistent storage
     */
    fun loadLanguage(): String?

    /**
     * Save cookie consent preferences
     */
    fun saveCookieConsent(consent: CookieConsent)

    /**
     * Load cookie consent preferences
     */
    fun loadCookieConsent(): CookieConsent?

    /**
     * Save subscription state
     */
    fun saveSubscription(subscription: SubscriptionState)

    /**
     * Load subscription state
     */
    fun loadSubscription(): SubscriptionState

    /**
     * Save usage tracker
     */
    fun saveUsageTracker(usageTracker: UsageTracker)

    /**
     * Load usage tracker
     */
    fun loadUsageTracker(): UsageTracker

    /**
     * Save theme mode to persistent storage
     */
    fun saveTheme(themeMode: String)

    /**
     * Load theme mode from persistent storage
     */
    fun loadTheme(): String?

    /**
     * Save selected measurement unit
     */
    fun saveUnit(unit: String)

    /**
     * Load selected measurement unit
     */
    fun loadUnit(): String?

    /**
     * Save help/tutorial state
     */
    fun saveHelpState(helpState: HelpState)

    /**
     * Load help/tutorial state
     */
    fun loadHelpState(): HelpState

    // ==================== Draft Auto-Save (mobile only) ====================

    /**
     * Save current draft session data and optionally the image.
     * No-op on web platforms.
     */
    fun saveDraft(draftJson: String, imageBase64: String?) {}

    /**
     * Load draft session JSON. Returns null if no draft exists.
     * Always returns null on web platforms.
     */
    fun loadDraftData(): String? = null

    /**
     * Load draft image base64. Returns null if no draft image exists.
     * Always returns null on web platforms.
     */
    fun loadDraftImage(): String? = null

    /**
     * Clear saved draft (after successful save or clear all).
     * No-op on web platforms.
     */
    fun clearDraft() {}
}

/**
 * Factory function to create platform-specific MeasurementStorage implementation
 */
expect fun createMeasurementStorage(): MeasurementStorage
