// ==================== TUTORIAL TARGET REGISTRY ====================

/**
 * Registry for tracking tutorial target positions
 */
class TutorialTargetRegistry {
    private val targets = mutableStateMapOf<TutorialStep, Rect>()

    fun register(step: TutorialStep, bounds: Rect) {
        targets[step] = bounds
    }

    fun unregister(step: TutorialStep) {
        targets.remove(step)
    }

    fun get(step: TutorialStep): Rect? = targets[step]
}

val LocalTutorialTargetRegistry = compositionLocalOf { TutorialTargetRegistry() }

@Composable
fun rememberTutorialTargetRegistry(): TutorialTargetRegistry {
    return remember { TutorialTargetRegistry() }
}

/**
 * Modifier to register an element as tutorial target for a specific step
 */
fun Modifier.tutorialTarget(step: TutorialStep): Modifier = this.then(
    Modifier.onGloballyPositioned { coordinates ->
        // Get registry from composition local - this is a workaround
        // The actual registration happens in TutorialTargetBox
    }
)

/**
 * Wrapper that registers its content as a tutorial target
 */
@Composable
fun TutorialTargetBox(
    step: TutorialStep,
    modifier: Modifier = Modifier,
    content: @Composable BoxScope.() -> Unit
) {
    val registry = LocalTutorialTargetRegistry.current

    DisposableEffect(step) {
        onDispose {
            registry.unregister(step)
        }
    }

    Box(
        modifier = modifier.onGloballyPositioned { coordinates ->
            registry.register(step, coordinates.boundsInRoot())
        },
        content = content
    )
}

// ==================== TUTORIAL OVERLAY ====================

/**
 * Full-screen tutorial overlay with spotlight effect.
 * Uses 4 rectangles around the target to create a "cutout" effect.
 * The target area is clickable (passes through clicks).
 */
@Composable
fun TutorialOverlay(
    visible: Boolean,
    currentStep: TutorialStep,
    onSkip: () -> Unit,
    onNext: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    val registry = LocalTutorialTargetRegistry.current
    val targetBounds = registry.get(currentStep)
    val isTipStep = currentStep == TutorialStep.SIZE_BUTTON_TIP ||
                    currentStep == TutorialStep.DRAG_POINTS_TIP ||
                    currentStep == TutorialStep.UNDO_TIP ||
                    currentStep == TutorialStep.SAVE_RESULT ||
                    currentStep == TutorialStep.HISTORY_TIP

    AnimatedVisibility(
        visible = visible && currentStep != TutorialStep.WELCOME && currentStep != TutorialStep.COMPLETED,
        enter = fadeIn(tween(300)),
        exit = fadeOut(tween(300)),
        modifier = modifier
    ) {
        BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
            val screenWidth = constraints.maxWidth.toFloat()
            val screenHeight = constraints.maxHeight.toFloat()
            val density = LocalDensity.current
            val padding = with(density) { 8.dp.toPx() }

            if (targetBounds != null) {
                // Spotlight with 4 dark rectangles around target
                SpotlightWithRectangles(
                    targetBounds = targetBounds,
                    screenWidth = screenWidth,
                    screenHeight = screenHeight,
                    padding = padding
                )

                // Hint card positioned near target
                PositionedHintCard(
                    step = currentStep,
                    targetBounds = targetBounds,
                    screenHeight = screenHeight,
                    isTipStep = isTipStep,
                    onSkip = onSkip,
                    onNext = onNext
                )
            } else {
                // Fallback: full dark overlay with centered hint
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(Color.Black.copy(alpha = 0.75f))
                        .clickable(
                            interactionSource = remember { MutableInteractionSource() },
                            indication = null
                        ) { /* Block clicks */ }
                )

                CenteredHintCard(
                    step = currentStep,
                    isTipStep = isTipStep,
                    onSkip = onSkip,
                    onNext = onNext,
                    modifier = Modifier.align(Alignment.Center)
                )
            }
        }
    }
}

/**
 * Creates spotlight effect with rounded rectangle cutout.
 * Uses 4 invisible clickable rectangles to block clicks outside target.
 * Visual scrim with rounded cutout is drawn separately.
 */
@Composable
private fun SpotlightWithRectangles(
    targetBounds: Rect,
    screenWidth: Float,
    screenHeight: Float,
    padding: Float
) {
    val density = LocalDensity.current
    val scrimColor = Color.Black.copy(alpha = 0.75f)
    val cornerRadiusPx = with(density) { AppCornerRadius.lg.toPx() }
    val borderWidthPx = with(density) { 2.5.dp.toPx() }

    // Animate target position for smooth transitions
    val animatedLeft by animateFloatAsState(
        targetValue = (targetBounds.left - padding).coerceAtLeast(0f),
        animationSpec = tween(300),
        label = "left"
    )
    val animatedTop by animateFloatAsState(
        targetValue = (targetBounds.top - padding).coerceAtLeast(0f),
        animationSpec = tween(300),
        label = "top"
    )
    val animatedRight by animateFloatAsState(
        targetValue = (targetBounds.right + padding).coerceAtMost(screenWidth),
        animationSpec = tween(300),
        label = "right"
    )
    val animatedBottom by animateFloatAsState(
        targetValue = (targetBounds.bottom + padding).coerceAtMost(screenHeight),
        animationSpec = tween(300),
        label = "bottom"
    )

    // Convert to Dp for layout
    val leftDp = with(density) { animatedLeft.toDp() }
    val topDp = with(density) { animatedTop.toDp() }
    val rightDp = with(density) { animatedRight.toDp() }
    val bottomDp = with(density) { animatedBottom.toDp() }
    val screenWidthDp = with(density) { screenWidth.toDp() }
    val screenHeightDp = with(density) { screenHeight.toDp() }

    // Full-screen Canvas for visual scrim with rounded cutout (doesn't block clicks)
    androidx.compose.foundation.Canvas(
        modifier = Modifier.fillMaxSize()
    ) {
        // Create full screen path
        val fullScreenPath = Path().apply {
            addRect(Rect(0f, 0f, size.width, size.height))
        }

        // Create rounded rectangle for cutout
        val roundRect = RoundRect(
            left = animatedLeft,
            top = animatedTop,
            right = animatedRight,
            bottom = animatedBottom,
            cornerRadius = CornerRadius(cornerRadiusPx, cornerRadiusPx)
        )

        // Create cutout path
        val cutoutPath = Path().apply {
            addRoundRect(roundRect)
        }

        // Subtract cutout from full screen
        val resultPath = Path().apply {
            op(fullScreenPath, cutoutPath, PathOperation.Difference)
        }

        // Draw the scrim with cutout
        drawPath(resultPath, scrimColor, style = Fill)

        // Draw white border
        drawRoundRect(
            color = Color.White,
            topLeft = androidx.compose.ui.geometry.Offset(animatedLeft, animatedTop),
            size = androidx.compose.ui.geometry.Size(
                animatedRight - animatedLeft,
                animatedBottom - animatedTop
            ),
            cornerRadius = CornerRadius(cornerRadiusPx, cornerRadiusPx),
            style = Stroke(width = borderWidthPx)
        )
    }

    // 4 INVISIBLE click-blocking rectangles around the target
    // Top
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(topDp)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null
            ) { /* Block clicks */ }
    )

    // Bottom
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(screenHeightDp - bottomDp)
            .offset(y = bottomDp)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null
            ) { /* Block clicks */ }
    )

    // Left (between top and bottom)
    Box(
        modifier = Modifier
            .width(leftDp)
            .height(bottomDp - topDp)
            .offset(y = topDp)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null
            ) { /* Block clicks */ }
    )

    // Right (between top and bottom)
    Box(
        modifier = Modifier
            .width(screenWidthDp - rightDp)
            .height(bottomDp - topDp)
            .offset(x = rightDp, y = topDp)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null
            ) { /* Block clicks */ }
    )
}

/**
 * Hint card positioned near the target (above or below)
 */
@Composable
private fun BoxWithConstraintsScope.PositionedHintCard(
    step: TutorialStep,
    targetBounds: Rect,
    screenHeight: Float,
    isTipStep: Boolean,
    onSkip: () -> Unit,
    onNext: () -> Unit
) {
    val colors = AppTheme.colors
    val density = LocalDensity.current

    // Determine if card should be above or below target
    val cardHeight = with(density) { 120.dp.toPx() }
    val margin = with(density) { 16.dp.toPx() }

    // Get navigation bar height for proper bottom spacing
    val navBarHeight = WindowInsets.navigationBars.getBottom(density)

    // Extra bottom padding to avoid overlapping with control buttons and navigation bar
    // Use at least 100dp or navigation bar height + 60dp for control buttons
    val bottomSafeArea = maxOf(with(density) { 100.dp.toPx() }, navBarHeight + with(density) { 60.dp.toPx() })

    val spaceAbove = targetBounds.top
    val spaceBelow = screenHeight - targetBounds.bottom - bottomSafeArea

    // Prefer showing above if target is in lower half of screen
    val showAbove = spaceAbove > spaceBelow || targetBounds.bottom > screenHeight * 0.6f

    val offsetY = with(density) {
        if (showAbove) {
            (targetBounds.top - cardHeight - margin).coerceAtLeast(margin).toDp()
        } else {
            (targetBounds.bottom + margin).coerceAtMost(screenHeight - cardHeight - margin - bottomSafeArea).toDp()
        }
    }

    // Calculate horizontal position - center on target but constrain to screen
    val cardMaxWidth = 350.dp
    val targetCenterX = (targetBounds.left + targetBounds.right) / 2
    val screenWidthDp = with(density) { constraints.maxWidth.toDp() }

    // Position hint card centered on target, but constrained to screen edges
    val offsetX = with(density) {
        val cardWidthPx = cardMaxWidth.toPx()
        val leftEdge = (targetCenterX - cardWidthPx / 2).coerceAtLeast(16.dp.toPx())
        val rightEdge = leftEdge + cardWidthPx
        if (rightEdge > constraints.maxWidth - 16.dp.toPx()) {
            (constraints.maxWidth - cardWidthPx - 16.dp.toPx()).coerceAtLeast(16.dp.toPx()).toDp()
        } else {
            leftEdge.toDp()
        }
    }

    Column(
        modifier = Modifier
            .width(cardMaxWidth)
            .offset(x = offsetX, y = offsetY)
            .clip(RoundedCornerShape(AppCornerRadius.md))
            .background(colors.bgSecondary)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null
            ) { /* Prevent click-through */ }
            .padding(Spacing.md),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            text = getStepHint(step),
            style = AppTheme.typography.bodyMedium,
            color = colors.textPrimary,
            textAlign = TextAlign.Center
        )

        Spacer(modifier = Modifier.height(Spacing.sm))

        Row(
            horizontalArrangement = Arrangement.spacedBy(Spacing.sm),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Skip button (always visible)
            Box(
                modifier = Modifier
                    .clip(RoundedCornerShape(AppCornerRadius.sm))
                    .background(colors.bgTertiary)
                    .clickable(onClick = onSkip)
                    .padding(horizontal = Spacing.md, vertical = Spacing.xs)
            ) {
                Text(
                    text = stringResource("skip"),
                    style = AppTheme.typography.labelMedium,
                    color = colors.textSecondary
                )
            }

            // Next/Got it button (only for tip steps)
            if (isTipStep) {
                Box(
                    modifier = Modifier
                        .clip(RoundedCornerShape(AppCornerRadius.sm))
                        .background(colors.snake)
                        .clickable(onClick = onNext)
                        .padding(horizontal = Spacing.md, vertical = Spacing.xs)
                ) {
                    Text(
                        text = stringResource("got_it"),
                        style = AppTheme.typography.labelMedium,
                        color = Color.White
                    )
                }
            }
        }
    }
}

