// ==================== HELPERS ====================

@Composable
private fun getStepHint(step: TutorialStep): String {
    return when (step) {
        TutorialStep.WELCOME -> ""
        TutorialStep.UPLOAD_PHOTO -> stringResource("tutorial_hint_upload")
        TutorialStep.PLACE_REFERENCE_POINTS -> stringResource("tutorial_hint_reference")
        TutorialStep.SET_REFERENCE_SIZE -> stringResource("tutorial_hint_size")
        TutorialStep.SIZE_BUTTON_TIP -> stringResource("tutorial_hint_size_tip")
        TutorialStep.SWITCH_TO_SNAKE -> stringResource("tutorial_hint_snake_mode")
        TutorialStep.PLACE_SNAKE_POINTS -> stringResource("tutorial_hint_snake_points")
        TutorialStep.DRAG_POINTS_TIP -> stringResource("tutorial_hint_drag")
        TutorialStep.UNDO_TIP -> stringResource("tutorial_hint_undo")
        TutorialStep.SAVE_RESULT -> stringResource("tutorial_hint_save")
        TutorialStep.HISTORY_TIP -> stringResource("tutorial_hint_history")
        TutorialStep.COMPLETED -> ""
    }
}
