package app.serpwidgets.snakemeasurer.model

import androidx.compose.ui.geometry.Offset

/**
 * Represents an undoable action in the measurement process
 */
sealed class UndoAction {
    /**
     * A point was added
     */
    data class AddPoint(
        val pointId: String,
        val pointType: PointType
    ) : UndoAction()

    /**
     * A point was moved from one position to another
     */
    data class MovePoint(
        val pointId: String,
        val pointType: PointType,
        val previousPosition: Offset
    ) : UndoAction()

    /**
     * Reference length was changed
     */
    data class SetReferenceLength(
        val previousLengthCm: Float
    ) : UndoAction()
}
