@Composable
fun HistoryModal(
    history: MeasurementHistory,
    currentUnit: MeasurementUnit,
    language: Language,
    onDelete: (String) -> Unit,
    onLoad: (MeasurementRecord) -> Unit,
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors

    // Backdrop
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.6f))
            .clickable(onClick = onDismiss),
        contentAlignment = Alignment.Center
    ) {
        // Modal content
        Column(
            modifier = Modifier
                .widthIn(max = 500.dp)
                .fillMaxWidth(0.95f)
                .heightIn(max = 600.dp)
                .fillMaxHeight(0.85f)
                .clip(Shapes.modal)
                .background(colors.bgTertiary)
                .clickable(enabled = false) {}
        ) {
            // Header
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(Spacing.xl),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = stringResource("history_title"),
                    color = colors.textPrimary,
                    style = AppTheme.typography.displayMedium
                )

                Box(
                    modifier = Modifier
                        .size(IconButtonDimens.size)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(onClick = onDismiss),
                    contentAlignment = Alignment.Center
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_close),
                        contentDescription = stringResource("close"),
                        modifier = Modifier.size(IconButtonDimens.iconSize),
                        colorFilter = ColorFilter.tint(colors.textPrimary)
                    )
                }
            }

            // Content
            if (history.records.isEmpty()) {
                // Empty state with icon and description
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                        .padding(Spacing.xxxl),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    // Icon
                    Box(
                        modifier = Modifier
                            .size(80.dp)
                            .clip(CircleShape)
                            .background(colors.bgTertiary),
                        contentAlignment = Alignment.Center
                    ) {
                        Image(
                            painter = painterResource(Res.drawable.ic_history),
                            contentDescription = stringResource("history_title"),
                            modifier = Modifier.size(40.dp),
                            colorFilter = ColorFilter.tint(colors.textTertiary)
                        )
                    }

                    Spacer(modifier = Modifier.height(Spacing.lg))

                    Text(
                        text = stringResource("no_saved_measurements"),
                        color = colors.textSecondary,
                        style = AppTheme.typography.headlineMedium
                    )

                    Spacer(modifier = Modifier.height(Spacing.xs))

                    Text(
                        text = stringResource("empty_history_hint"),
                        color = colors.textTertiary,
                        style = AppTheme.typography.bodyMedium,
                        textAlign = TextAlign.Center
                    )
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f)
                        .padding(horizontal = Spacing.lg),
                    verticalArrangement = Arrangement.spacedBy(Spacing.sm),
                    contentPadding = PaddingValues(bottom = Spacing.lg)
                ) {
                    items(history.records) { record ->
                        HistoryItem(
                            record = record,
                            language = language,
                            onDelete = { onDelete(record.id) },
                            onLoad = { onLoad(record) },
                            canLoad = record.getDisplayImage() != null
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun HistoryItem(
    record: MeasurementRecord,
    language: Language,
    onDelete: () -> Unit,
    onLoad: () -> Unit,
    canLoad: Boolean
) {
    val colors = AppTheme.colors

    // Decode thumbnail image (use new method with fallback for old records)
    val thumbnail = remember(record.thumbnailBase64, record.originalImageBase64, record.imageBase64) {
        record.getThumbnailOrFallback()?.let { ImageEncoder.decodeFromBase64(it) }
    }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(Shapes.extraLarge)
            .background(colors.bgSecondary)
            .then(if (canLoad) Modifier.clickable(onClick = onLoad) else Modifier)
            .padding(Spacing.md)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(Spacing.md)
        ) {
            // Thumbnail
            Box(
                modifier = Modifier
                    .size(80.dp)
                    .clip(Shapes.large)
                    .background(colors.bgElevated)
                    .border(1.dp, colors.border, Shapes.large),
                contentAlignment = Alignment.Center
            ) {
                if (thumbnail != null) {
                    Image(
                        bitmap = thumbnail,
                        contentDescription = "Measurement thumbnail",
                        modifier = Modifier.fillMaxSize(),
                        contentScale = ContentScale.Crop
                    )
                } else {
                    Image(
                        painter = painterResource(Res.drawable.ic_snake),
                        contentDescription = "Snake",
                        modifier = Modifier.size(32.dp),
                        colorFilter = ColorFilter.tint(colors.textTertiary)
                    )
                }
            }

            // Info
            Column(
                modifier = Modifier.weight(1f)
            ) {
                // Save time + Sync time
                Column {
                    // Save time
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                    ) {
                        Text(
                            text = "${stringResource("saved_at")}: ${formatTimestamp(record.timestamp, language)}",
                            color = colors.textTertiary,
                            style = AppTheme.typography.caption
                        )
                    }

                    // Sync time (if synced)
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                    ) {
                        // Sync status indicator
                        val syncColor = when (record.syncStatus) {
                            SyncStatus.SYNCED -> colors.success
                            SyncStatus.SYNCING -> colors.reference
                            SyncStatus.FAILED -> colors.danger
                            SyncStatus.PENDING_UPLOAD, SyncStatus.PENDING_DELETE -> colors.warning
                            SyncStatus.NOT_SYNCED -> colors.textTertiary
                        }
                        Box(
                            modifier = Modifier
                                .size(6.dp)
                                .clip(CircleShape)
                                .background(syncColor)
                        )

                        val syncText = when (record.syncStatus) {
                            SyncStatus.SYNCED -> record.syncedAt?.let {
                                "${stringResource("synced_at")}: ${formatTimestamp(it, language)}"
                            } ?: stringResource("synced")
                            SyncStatus.SYNCING -> stringResource("syncing")
                            SyncStatus.FAILED -> stringResource("sync_failed")
                            SyncStatus.PENDING_UPLOAD -> stringResource("pending_sync")
                            SyncStatus.PENDING_DELETE -> stringResource("pending_delete")
                            SyncStatus.NOT_SYNCED -> stringResource("not_synced")
                        }
                        Text(
                            text = syncText,
                            color = colors.textTertiary,
                            style = AppTheme.typography.caption
                        )
                    }
                }

                Spacer(modifier = Modifier.height(Spacing.xxs))

                // Length
                val lengthInUnit = record.unit.fromCentimeters(record.snakeLengthCm)
                Text(
                    text = "${language.formatNumber(lengthInUnit, 1)} ${record.unit.getLocalizedAbbreviation(language)}",
                    color = colors.success,
                    style = AppTheme.typography.displayMedium
                )

                Spacer(modifier = Modifier.height(Spacing.xxs))

                // Info
                val refLengthInUnit = record.unit.fromCentimeters(record.referenceLengthCm)
                Text(
                    text = "REF: ${language.formatNumber(refLengthInUnit, 1)} ${record.unit.getLocalizedAbbreviation(language)} • ${record.snakePointCount} pts",
                    color = colors.textSecondary,
                    style = AppTheme.typography.caption,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                // View hint
                if (canLoad) {
                    Spacer(modifier = Modifier.height(Spacing.xxs))
                    Text(
                        text = stringResource("tap_to_view"),
                        color = colors.textTertiary,
                        style = AppTheme.typography.caption
                    )
                }
            }

            // Delete button
            Box(
                modifier = Modifier
                    .size(IconButtonDimens.size)
                    .clip(Shapes.medium)
                    .background(colors.danger.copy(alpha = 0.1f))
                    .clickable(onClick = onDelete),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painter = painterResource(Res.drawable.ic_delete),
                    contentDescription = stringResource("delete_measurement"),
                    modifier = Modifier.size(IconButtonDimens.iconSize),
                    colorFilter = ColorFilter.tint(colors.danger)
                )
            }
        }
    }
}

private fun formatTimestamp(timestamp: Long, language: Language): String {
    // Simple cross-platform date formatting
    // Calculate date components from timestamp
    val secondsInMinute = 60
    val secondsInHour = 3600
    val secondsInDay = 86400

    val totalSeconds = timestamp / 1000
    val hours = ((totalSeconds % secondsInDay) / secondsInHour).toInt()
    val minutes = ((totalSeconds % secondsInHour) / secondsInMinute).toInt()

    // Simple day calculation (approximate - good enough for display)
    val days = (totalSeconds / secondsInDay).toInt()
    val year = 1970 + (days / 365)
    val dayOfYear = days % 365
    val month = (dayOfYear / 30) + 1
    val dayOfMonth = (dayOfYear % 30) + 1

    val monthNames = if (language.code == "ru") {
        listOf("янв", "фев", "мар", "апр", "май", "июн", "июл", "авг", "сен", "окт", "ноя", "дек")
    } else {
        listOf("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
    }

    val monthName = monthNames.getOrElse(month.coerceIn(1, 12) - 1) { "Jan" }
    val hourStr = hours.toString().padStart(2, '0')
    val minuteStr = minutes.toString().padStart(2, '0')

    return "$monthName $dayOfMonth, $hourStr:$minuteStr"
}

