import androidx.compose.animation.*
import androidx.compose.animation.core.*
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.shadow
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.unit.dp
import app.serpwidgets.snakemeasurer.model.MeasurementMode
import app.serpwidgets.snakemeasurer.model.TutorialStep
import app.serpwidgets.snakemeasurer.ui.stringResource
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.ui.theme.ButtonDimens
import app.serpwidgets.snakemeasurer.ui.theme.Shapes
import app.serpwidgets.snakemeasurer.ui.theme.Spacing
import app.serpwidgets.snakemeasurer.ui.tutorial.TutorialTargetBox

/**
 * State needed for FloatingInstruction
 */
data class FloatingInstructionState(
    val mode: MeasurementMode,
    val referencePointsCount: Int,
    val snakePointsCount: Int,
    val hasReferenceComplete: Boolean,
    val hasReferenceSizeSet: Boolean,
    val isViewingHistory: Boolean
)

/**
 * Floating instruction panel that shows current mode and action hints.
 * Includes Undo, Set Size, and New Measurement buttons.
 */
@Composable
fun FloatingInstruction(
    state: FloatingInstructionState,
    onAction: (MeasurementAction) -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors

    val hasPoints = when (state.mode) {
        MeasurementMode.REFERENCE -> state.referencePointsCount > 0
        MeasurementMode.SNAKE -> state.snakePointsCount > 0
    }

    // Check if reference is complete but size not set
    val needsReferenceSize = state.hasReferenceComplete && !state.hasReferenceSizeSet && !state.isViewingHistory

    Row(
        modifier = modifier
            .shadow(Spacing.xs, Shapes.extraLarge)
            .clip(Shapes.extraLarge)
            .background(colors.bgElevated)
            .padding(Spacing.sm + 2.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(Spacing.sm)
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(
                text = if (state.isViewingHistory) {
                    stringResource("viewing_saved_measurement")
                } else if (needsReferenceSize) {
                    stringResource("tap_to_set_size")
                } else {
                    when (state.mode) {
                        MeasurementMode.REFERENCE -> stringResource("tap_to_add_reference")
                        MeasurementMode.SNAKE -> stringResource("tap_along_snake_body")
                    }
                },
                color = if (needsReferenceSize) colors.reference else colors.textPrimary,
                style = AppTheme.typography.titleMedium
            )
            Text(
                text = if (state.isViewingHistory) {
                    stringResource("view_only")
                } else if (needsReferenceSize) {
                    "2/2"
                } else {
                    when (state.mode) {
                        MeasurementMode.REFERENCE -> "${state.referencePointsCount}/2"
                        MeasurementMode.SNAKE -> "${state.snakePointsCount} ${stringResource("points")}"
                    }
                },
                color = if (needsReferenceSize) colors.success else colors.textTertiary,
                style = AppTheme.typography.caption
            )
        }

        // Set Size button (shown when reference complete but size not set)
        AnimatedVisibility(
            visible = needsReferenceSize,
            enter = fadeIn() + expandHorizontally(),
            exit = fadeOut() + shrinkHorizontally()
        ) {
            // Blinking animation for attention (no scale to avoid text jumping)
            val infiniteTransition = rememberInfiniteTransition(label = "pulse")
            val alpha by infiniteTransition.animateFloat(
                initialValue = 1f,
                targetValue = 0.5f,
                animationSpec = infiniteRepeatable(
                    animation = tween(400, easing = LinearEasing),
                    repeatMode = RepeatMode.Reverse
                ),
                label = "alpha"
            )

            Box(
                modifier = Modifier
                    .graphicsLayer { this.alpha = alpha }
                    .clip(Shapes.medium)
                    .background(colors.reference)
                    .clickable { onAction(MeasurementAction.ShowSizeModal) }
                    .padding(horizontal = ButtonDimens.paddingHorizontalSmall + 2.dp, vertical = ButtonDimens.paddingVerticalSmall)
            ) {
                Text(
                    text = stringResource("set_size"),
                    color = Color.White,
                    style = AppTheme.typography.titleSmall
                )
            }
        }

        // Undo button (hidden in view mode and when needs reference size)
        AnimatedVisibility(
            visible = hasPoints && !state.isViewingHistory && !needsReferenceSize,
            enter = fadeIn() + expandHorizontally(),
            exit = fadeOut() + shrinkHorizontally()
        ) {
            TutorialTargetBox(step = TutorialStep.UNDO_TIP) {
                Box(
                    modifier = Modifier
                        .clip(Shapes.medium)
                        .background(colors.warning)
                        .clickable { onAction(MeasurementAction.UndoLastPoint) }
                        .padding(horizontal = ButtonDimens.paddingHorizontalSmall + 2.dp, vertical = ButtonDimens.paddingVerticalSmall)
                ) {
                    Text(
                        text = stringResource("undo"),
                        color = Color.White,
                        style = AppTheme.typography.titleSmall
                    )
                }
            }
        }

        // New Measurement button (shown in view mode)
        AnimatedVisibility(
            visible = state.isViewingHistory,
            enter = fadeIn() + expandHorizontally(),
            exit = fadeOut() + shrinkHorizontally()
        ) {
            Box(
                modifier = Modifier
                    .clip(Shapes.medium)
                    .background(colors.reference)
                    .clickable { onAction(MeasurementAction.StartNewMeasurementWithNewImage) }
                    .padding(horizontal = ButtonDimens.paddingHorizontalSmall + 2.dp, vertical = ButtonDimens.paddingVerticalSmall)
            ) {
                Text(
                    text = stringResource("new_measurement"),
                    color = Color.White,
                    style = AppTheme.typography.titleSmall
                )
            }
        }
    }
}
