package app.serpwidgets.snakemeasurer.ui.components

import androidx.compose.foundation.Canvas
import androidx.compose.foundation.gestures.awaitEachGesture
import androidx.compose.foundation.gestures.awaitFirstDown
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.runtime.getValue
import androidx.compose.ui.draw.clipToBounds
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Paint
import androidx.compose.ui.graphics.PaintingStyle
import androidx.compose.ui.graphics.drawscope.drawIntoCanvas
import androidx.compose.ui.input.pointer.PointerEventType
import androidx.compose.ui.input.pointer.pointerInput
import androidx.compose.ui.input.pointer.positionChange
import androidx.compose.ui.unit.IntOffset
import androidx.compose.foundation.gestures.detectTapGestures
import app.serpwidgets.snakemeasurer.model.MeasurementMode
import app.serpwidgets.snakemeasurer.model.MeasurementPoint
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.util.CoordinateTransform
import app.serpwidgets.snakemeasurer.viewmodel.MeasurementViewModel
import kotlin.math.sqrt

@Composable
fun MeasurementCanvas(
    viewModel: MeasurementViewModel,
    modifier: Modifier = Modifier
) {
    val state = viewModel.state
    val colors = AppTheme.colors
    val dragThreshold = 10f // Min movement to start drag/pan

    // Use rememberUpdatedState to always get the latest values in gesture handlers
    val currentZoom by rememberUpdatedState(state.zoomLevel)
    val currentPan by rememberUpdatedState(state.panOffset)
    val currentMode by rememberUpdatedState(state.mode)
    val currentSelectedPointId by rememberUpdatedState(state.selectedPointId)
    val currentReferencePoints by rememberUpdatedState(state.referencePoints)
    val currentSnakePoints by rememberUpdatedState(state.snakePoints)

    // Use image identity as key to reset gesture handling when image changes
    val imageKey = state.imageBitmap?.let { "${it.width}x${it.height}" } ?: "no-image"

    Canvas(
        modifier = modifier
            .fillMaxSize()
            .clipToBounds()
            // Single tap to add point (no double-tap - use pinch zoom or buttons instead)
            .pointerInput(imageKey) {
                detectTapGestures(
                    onTap = { tapPosition ->
                        state.imageBitmap?.let { bitmap ->
                            val imageSize = Size(bitmap.width.toFloat(), bitmap.height.toFloat())
                            val canvasSize = Size(size.width.toFloat(), size.height.toFloat())
                            val normalizedPos = CoordinateTransform.screenToNormalized(
                                screenOffset = tapPosition,
                                imageSize = imageSize,
                                canvasSize = canvasSize,
                                zoom = currentZoom,
                                pan = currentPan
                            )
                            viewModel.addPoint(normalizedPos)
                        }
                    }
                )
            }
            // Mouse wheel zoom support for web/desktop
            .pointerInput(imageKey) {
                awaitEachGesture {
                    val event = awaitPointerEvent()
                    if (event.type == PointerEventType.Scroll) {
                        val scrollDelta = event.changes.firstOrNull()?.scrollDelta ?: Offset.Zero
                        if (scrollDelta.y != 0f) {
                            state.imageBitmap?.let { bitmap ->
                                val imageSize = Size(bitmap.width.toFloat(), bitmap.height.toFloat())
                                val canvasSize = Size(size.width.toFloat(), size.height.toFloat())
                                val position = event.changes.firstOrNull()?.position ?: Offset.Zero

                                // Zoom in/out based on scroll direction - use latest zoom
                                val zoomDelta = -scrollDelta.y * 0.1f * currentZoom
                                viewModel.adjustZoom(
                                    delta = zoomDelta,
                                    focalPoint = position,
                                    imageSize = imageSize,
                                    canvasSize = canvasSize
                                )
                            }
                            event.changes.forEach { it.consume() }
                        }
                    }
                }
            }
            // Unified gesture handling for pinch zoom and pan
            .pointerInput(imageKey) {
                awaitEachGesture {
                    val firstDown = awaitFirstDown(requireUnconsumed = false)
                    val downPosition = firstDown.position
                    var totalDrag = Offset.Zero
                    var isDraggingPoint = false
                    var dragStarted = false
                    var isMultiTouch = false
                    var previousCentroid = downPosition
                    var previousDistance = 0f
                    var selectedPointIdForDrag: String? = null

                    state.imageBitmap?.let { bitmap ->
                        val imageSize = Size(bitmap.width.toFloat(), bitmap.height.toFloat())
                        val canvasSize = Size(size.width.toFloat(), size.height.toFloat())

                        // Check if we're near a point for dragging (single finger only)
                        // Use current values from rememberUpdatedState
                        val nearestPoint = findNearestPointInScreenSpaceFromLists(
                            downPosition,
                            currentReferencePoints,
                            currentSnakePoints,
                            currentZoom,
                            currentPan,
                            imageSize,
                            canvasSize
                        )
                        if (nearestPoint != null) {
                            viewModel.startMovePoint(nearestPoint.id)
                            selectedPointIdForDrag = nearestPoint.id
                            isDraggingPoint = true
                        }

                        // Process pointer events
                        do {
                            val event = awaitPointerEvent()
                            val pressedChanges = event.changes.filter { it.pressed }

                            if (pressedChanges.isEmpty()) {
                                // All fingers released
                                val totalMovement = sqrt(totalDrag.x * totalDrag.x + totalDrag.y * totalDrag.y)

                                // Tap handling is done by detectTapGestures above
                                // This block only handles drag/pinch gestures

                                if (isDraggingPoint) {
                                    viewModel.unselectPoint()
                                }
                                break
                            }

                            if (pressedChanges.size >= 2) {
                                // Multi-touch: pinch zoom and pan
                                isMultiTouch = true
                                isDraggingPoint = false // Cancel point drag on multi-touch

                                val pos1 = pressedChanges[0].position
                                val pos2 = pressedChanges[1].position
                                val centroid = Offset((pos1.x + pos2.x) / 2f, (pos1.y + pos2.y) / 2f)
                                val distance = sqrt((pos2.x - pos1.x) * (pos2.x - pos1.x) + (pos2.y - pos1.y) * (pos2.y - pos1.y))

                                if (previousDistance > 0f) {
                                    // Calculate zoom change - use current zoom
                                    val zoomFactor = distance / previousDistance
                                    if (zoomFactor != 1f) {
                                        val zoomDelta = (zoomFactor - 1f) * currentZoom
                                        viewModel.adjustZoom(
                                            delta = zoomDelta,
                                            focalPoint = centroid,
                                            imageSize = imageSize,
                                            canvasSize = canvasSize
                                        )
                                    }

                                    // Calculate pan change - use current pan
                                    val panDelta = centroid - previousCentroid
                                    if (panDelta != Offset.Zero) {
                                        val newPan = currentPan + panDelta
                                        viewModel.setPan(newPan, imageSize, canvasSize)
                                    }
                                }

                                previousCentroid = centroid
                                previousDistance = distance
                                pressedChanges.forEach { it.consume() }

                            } else if (pressedChanges.size == 1 && !isMultiTouch) {
                                // Single finger: drag point or pan
                                val change = pressedChanges[0]
                                val dragAmount = change.positionChange()
                                totalDrag += dragAmount

                                val totalMovement = sqrt(totalDrag.x * totalDrag.x + totalDrag.y * totalDrag.y)

                                // Start drag after threshold
                                if (totalMovement > dragThreshold && !dragStarted) {
                                    dragStarted = true
                                }

                                if (dragStarted) {
                                    if (isDraggingPoint && selectedPointIdForDrag != null) {
                                        // Move selected point - use current zoom/pan
                                        val normalizedPos = CoordinateTransform.screenToNormalized(
                                            screenOffset = change.position,
                                            imageSize = imageSize,
                                            canvasSize = canvasSize,
                                            zoom = currentZoom,
                                            pan = currentPan
                                        )
                                        viewModel.moveSelectedPoint(normalizedPos)
                                    } else {
                                        // Pan the canvas - use current pan
                                        val newPan = currentPan + dragAmount
                                        viewModel.setPan(newPan, imageSize, canvasSize)
                                    }
                                    change.consume()
                                }
                            }
                        } while (true)
                    }
                }
            }
    ) {
        // Draw image if available with zoom and pan
        state.imageBitmap?.let { bitmap ->
            val imageSize = Size(bitmap.width.toFloat(), bitmap.height.toFloat())
            val canvasSize = size
            val imageBounds = CoordinateTransform.getImageBounds(
                imageSize, canvasSize, state.zoomLevel, state.panOffset
            )

            drawImage(
                image = bitmap,
                dstOffset = IntOffset(imageBounds.left.toInt(), imageBounds.top.toInt()),
                dstSize = androidx.compose.ui.unit.IntSize(
                    imageBounds.width.toInt(),
                    imageBounds.height.toInt()
                )
            )

            // Draw reference lines (convert from normalized to screen coords)
            if (state.referencePoints.size >= 2) {
                val start = CoordinateTransform.normalizedToScreen(
                    state.referencePoints[0].position,
                    imageSize, canvasSize, state.zoomLevel, state.panOffset
                )
                val end = CoordinateTransform.normalizedToScreen(
                    state.referencePoints[1].position,
                    imageSize, canvasSize, state.zoomLevel, state.panOffset
                )
                drawLine(
                    color = colors.reference,
                    start = start,
                    end = end,
                    strokeWidth = 4f * state.zoomLevel
                )
            }

            // Draw snake path (convert from normalized to screen coords)
            if (state.snakePoints.size >= 2) {
                for (i in 0 until state.snakePoints.size - 1) {
                    val start = CoordinateTransform.normalizedToScreen(
                        state.snakePoints[i].position,
                        imageSize, canvasSize, state.zoomLevel, state.panOffset
                    )
                    val end = CoordinateTransform.normalizedToScreen(
                        state.snakePoints[i + 1].position,
                        imageSize, canvasSize, state.zoomLevel, state.panOffset
                    )
                    drawLine(
                        color = colors.snake,
                        start = start,
                        end = end,
                        strokeWidth = 3f * state.zoomLevel
                    )
                }
            }

            // Draw reference points (convert from normalized to screen coords)
            state.referencePoints.forEach { point ->
                val screenPos = CoordinateTransform.normalizedToScreen(
                    point.position,
                    imageSize, canvasSize, state.zoomLevel, state.panOffset
                )
                drawPoint(
                    position = screenPos,
                    color = colors.reference,
                    isSelected = point.id == state.selectedPointId,
                    zoom = state.zoomLevel
                )
            }

            // Draw snake points (convert from normalized to screen coords)
            state.snakePoints.forEach { point ->
                val screenPos = CoordinateTransform.normalizedToScreen(
                    point.position,
                    imageSize, canvasSize, state.zoomLevel, state.panOffset
                )
                drawPoint(
                    position = screenPos,
                    color = colors.snake,
                    isSelected = point.id == state.selectedPointId,
                    zoom = state.zoomLevel
                )
            }
        }
    }
}

/**
 * Find the nearest point to a screen position, using provided lists and zoom/pan values
 */
private fun findNearestPointInScreenSpaceFromLists(
    screenOffset: Offset,
    referencePoints: List<MeasurementPoint>,
    snakePoints: List<MeasurementPoint>,
    zoomLevel: Float,
    panOffset: Offset,
    imageSize: Size,
    canvasSize: Size,
    maxDistance: Float = 50f
): MeasurementPoint? {
    val allPoints = referencePoints + snakePoints
    var nearestPoint: MeasurementPoint? = null
    var minDistance = maxDistance

    allPoints.forEach { point ->
        val screenPos = CoordinateTransform.normalizedToScreen(
            point.position, imageSize, canvasSize, zoomLevel, panOffset
        )
        val distance = sqrt(
            (screenPos.x - screenOffset.x) * (screenPos.x - screenOffset.x) +
            (screenPos.y - screenOffset.y) * (screenPos.y - screenOffset.y)
        )
        if (distance < minDistance) {
            minDistance = distance
            nearestPoint = point
        }
    }

    return nearestPoint
}

private fun androidx.compose.ui.graphics.drawscope.DrawScope.drawPoint(
    position: Offset,
    color: Color,
    isSelected: Boolean,
    zoom: Float = 1f
) {
    // Scale point sizes based on zoom for better visibility
    val baseRadius = 12f
    val selectionRadius = 24f

    // Draw outer circle (selection indicator)
    if (isSelected) {
        drawCircle(
            color = color.copy(alpha = 0.3f),
            radius = selectionRadius,
            center = position
        )
    }

    // Draw main point circle
    drawCircle(
        color = color,
        radius = baseRadius,
        center = position
    )

    // Draw inner white circle
    drawCircle(
        color = Color.White,
        radius = baseRadius / 2f,
        center = position
    )

    // Draw border
    drawIntoCanvas { canvas ->
        val paint = Paint().apply {
            this.color = Color.White
            this.strokeWidth = 2f
            this.style = PaintingStyle.Stroke
        }
        canvas.drawCircle(position, baseRadius, paint)
    }
}
