    }

    // ========== Action Dispatcher ==========

    /**
     * Central action dispatcher for stateless UI components.
     * Maps MeasurementAction to existing ViewModel methods.
     */
    fun onAction(action: MeasurementAction) {
        when (action) {
            // Mode
            is MeasurementAction.SetMode -> setMode(action.mode)
            MeasurementAction.ClearCurrentMode -> clearCurrentMode()
            MeasurementAction.UndoLastPoint -> undoLastPoint()

            // Measurement
            MeasurementAction.SaveMeasurement -> saveMeasurement()
            MeasurementAction.StartNewMeasurement -> startNewMeasurement()
            MeasurementAction.StartNewMeasurementWithNewImage -> startNewMeasurementWithNewImage()

            // Reference Size
            MeasurementAction.ShowSizeModal -> showSizeModal()
            is MeasurementAction.SetReferenceLength -> setReferenceLength(action.lengthCm)

            // Zoom/Fullscreen
            MeasurementAction.ZoomIn -> zoomIn()
            MeasurementAction.ZoomOut -> zoomOut()
            MeasurementAction.ToggleFullscreen -> toggleFullscreen()

            // History
            MeasurementAction.ShowHistoryModal -> showHistoryModal()
            MeasurementAction.HideHistoryModal -> hideHistoryModal()
            is MeasurementAction.LoadMeasurement -> {
                state.measurementHistory.records.find { it.id == action.recordId }?.let {
                    loadMeasurement(it)
                }
            }
            is MeasurementAction.DeleteHistoryRecord -> deleteHistoryRecord(action.recordId)

            // Settings
            MeasurementAction.ShowSettingsModal -> showSettingsModal()
            MeasurementAction.HideSettingsModal -> hideSettingsModal()
            is MeasurementAction.SetLanguage -> setLanguage(action.language)
            is MeasurementAction.SetThemeMode -> setThemeMode(action.mode)
            is MeasurementAction.SetUnit -> setUnit(action.unit)
            MeasurementAction.CycleTheme -> cycleTheme()
            MeasurementAction.ClearAll -> clearAll()
            MeasurementAction.RestartTutorial -> restartTutorial()

            // FAQ
            MeasurementAction.ShowFaqModal -> showFaqModal()
            MeasurementAction.HideFaqModal -> hideFaqModal()

            // Paywall
            MeasurementAction.ShowPaywallModal -> showPaywallModal()
            MeasurementAction.HidePaywallModal -> hidePaywallModal()
            is MeasurementAction.OnPurchaseSuccess -> onPurchaseSuccess(action.productId)

            // Save Success Modal
            MeasurementAction.ShowSaveSuccessModal -> { /* handled internally */ }
            MeasurementAction.HideSaveSuccessModal -> hideSaveSuccessModal()

            // Unsaved Warning Modal
            MeasurementAction.ShowUnsavedWarningModal -> showUnsavedWarningModal()
            MeasurementAction.HideUnsavedWarningModal -> hideUnsavedWarningModal()

            // Bottom Sheet
            MeasurementAction.ShowBottomSheet -> showBottomSheet()
            MeasurementAction.HideBottomSheet -> hideBottomSheet()

            // Auth
            MeasurementAction.ShowAuthProvidersModal -> showAuthProvidersModal()
            MeasurementAction.HideAuthProvidersModal -> hideAuthProvidersModal()
            MeasurementAction.ShowEmailAuthModal -> showEmailAuthModal()
            MeasurementAction.HideEmailAuthModal -> hideEmailAuthModal()
            MeasurementAction.ShowAccountModal -> showAccountModal()
            MeasurementAction.HideAccountModal -> hideAccountModal()
            MeasurementAction.SignInWithGoogle -> signInWithGoogle()
            MeasurementAction.SignInWithApple -> signInWithApple()
            MeasurementAction.SignInWithFacebook -> signInWithFacebook()
            is MeasurementAction.SignInWithEmail -> signInWithEmail(action.email, action.password)
            is MeasurementAction.CreateAccountWithEmail -> createAccountWithEmail(action.email, action.password)
            is MeasurementAction.SendPasswordResetEmail -> sendPasswordResetEmail(action.email)
            MeasurementAction.SignOut -> signOut()
            MeasurementAction.DeleteAccount -> deleteAccount()
            MeasurementAction.ClearAuthError -> clearAuthError()

            // Tutorial
            MeasurementAction.StartTutorial -> startTutorial()
            MeasurementAction.SkipTutorial -> skipTutorial()
            MeasurementAction.AdvanceTutorialStep -> advanceTutorialStep()
            MeasurementAction.DismissTutorialCompleted -> dismissTutorialCompleted()
        }
    }

    // ========== Auth ==========

