    // ========== Mode ==========

    fun setMode(mode: MeasurementMode) {
        // Check free tier limit when switching to snake mode
        if (mode == MeasurementMode.SNAKE && state.snakePoints.isEmpty() && !state.canMeasure) {
            showPaywallModal()
            return
        }
        state = state.copy(mode = mode, selectedPointId = null)
        advanceTutorialIfNeeded()
    }

    // ========== Points ==========

    fun addPoint(position: Offset) {
        // Block editing in history view mode
        if (state.isViewingHistory) return

        // Block points outside image bounds (normalized coords should be 0.0-1.0)
        if (!isPositionInsideImage(position)) return

        // Block if too close to existing point (likely misclick or drag attempt)
        if (isTooCloseToExistingPoint(position)) return

        when (state.mode) {
            MeasurementMode.REFERENCE -> {
                if (state.referencePoints.size < 2) {
                    val newPoint = MeasurementPoint(
                        id = UuidGenerator.randomUUID(),
                        position = position,
                        type = PointType.REFERENCE
                    )
                    val undoAction = UndoAction.AddPoint(newPoint.id, PointType.REFERENCE)
                    state = state.copy(
                        referencePoints = state.referencePoints + newPoint,
                        undoStack = state.undoStack + undoAction
                    )
                    // Show size modal when 2 points are placed
                    if (state.referencePoints.size == 2 && state.referenceLengthCm == 0f) {
                        state = state.copy(showSizeModal = true)
                    }
                }
            }
            MeasurementMode.SNAKE -> {
                // Check free tier limit when starting to measure snake
                if (state.snakePoints.isEmpty() && !state.canMeasure) {
                    showPaywallModal()
                    return
                }

                if (state.canAddSnakePoints) {
                    val newPoint = MeasurementPoint(
                        id = UuidGenerator.randomUUID(),
                        position = position,
                        type = PointType.SNAKE
                    )
                    val undoAction = UndoAction.AddPoint(newPoint.id, PointType.SNAKE)
                    state = state.copy(
                        snakePoints = state.snakePoints + newPoint,
                        undoStack = state.undoStack + undoAction
                    )
                    updateSnakeLength()
                }
            }
        }
        advanceTutorialIfNeeded()
        scheduleDraftSave()
    }

    /**
     * Undo the last action (add point or move point)
     */
    fun undo() {
        if (state.isViewingHistory) return
        if (state.undoStack.isEmpty()) return

        val lastAction = state.undoStack.last()
        val newUndoStack = state.undoStack.dropLast(1)

        when (lastAction) {
            is UndoAction.AddPoint -> {
                // Remove the added point
                when (lastAction.pointType) {
                    PointType.REFERENCE -> {
                        val updatedPoints = state.referencePoints.filter { it.id != lastAction.pointId }
                        state = state.copy(
                            referencePoints = updatedPoints,
                            undoStack = newUndoStack
                        )
                    }
                    PointType.SNAKE -> {
                        val updatedPoints = state.snakePoints.filter { it.id != lastAction.pointId }
                        state = state.copy(
                            snakePoints = updatedPoints,
                            undoStack = newUndoStack
                        )
                        updateSnakeLength()
                    }
                }
            }
            is UndoAction.MovePoint -> {
                // Restore the point to its previous position
                when (lastAction.pointType) {
                    PointType.REFERENCE -> {
                        val updatedPoints = state.referencePoints.map { point ->
                            if (point.id == lastAction.pointId) {
                                point.copy(position = lastAction.previousPosition)
                            } else {
                                point
                            }
                        }
                        state = state.copy(
                            referencePoints = updatedPoints,
                            undoStack = newUndoStack
                        )
                    }
                    PointType.SNAKE -> {
                        val updatedPoints = state.snakePoints.map { point ->
                            if (point.id == lastAction.pointId) {
                                point.copy(position = lastAction.previousPosition)
                            } else {
                                point
                            }
                        }
                        state = state.copy(
                            snakePoints = updatedPoints,
                            undoStack = newUndoStack
                        )
                        updateSnakeLength()
                    }
                }
            }
            is UndoAction.SetReferenceLength -> {
                state = state.copy(
                    referenceLengthCm = lastAction.previousLengthCm,
                    undoStack = newUndoStack
                )
                updateSnakeLength()
            }
        }
        scheduleDraftSave()
    }

    // Keep old function name for compatibility
    fun undoLastPoint() = undo()

    fun selectPoint(pointId: String) {
        state = state.copy(selectedPointId = pointId)
    }

    // Track position before move for undo
    private var moveStartPosition: Offset? = null

    /**
     * Call when starting to drag a point - records original position for undo
     */
    fun startMovePoint(pointId: String) {
        if (state.isViewingHistory) return

        // Find the point and record its current position
        val refPoint = state.referencePoints.find { it.id == pointId }
        val snakePoint = state.snakePoints.find { it.id == pointId }
        val point = refPoint ?: snakePoint

        moveStartPosition = point?.position
        state = state.copy(selectedPointId = pointId)
    }

    fun moveSelectedPoint(newPosition: Offset) {
        if (state.isViewingHistory) return
        val selectedId = state.selectedPointId ?: return

        // Clamp position to image bounds
        val clampedPosition = Offset(
            x = newPosition.x.coerceIn(0f, 1f),
            y = newPosition.y.coerceIn(0f, 1f)
        )

        val referenceIndex = state.referencePoints.indexOfFirst { it.id == selectedId }
        if (referenceIndex != -1) {
            val updatedPoints = state.referencePoints.toMutableList()
            updatedPoints[referenceIndex] = updatedPoints[referenceIndex].copy(position = clampedPosition)
            state = state.copy(referencePoints = updatedPoints)
            updateSnakeLength()
            return
        }

        val snakeIndex = state.snakePoints.indexOfFirst { it.id == selectedId }
        if (snakeIndex != -1) {
            val updatedPoints = state.snakePoints.toMutableList()
            updatedPoints[snakeIndex] = updatedPoints[snakeIndex].copy(position = clampedPosition)
            state = state.copy(snakePoints = updatedPoints)
            updateSnakeLength()
        }
    }

    /**
     * Call when drag ends - records the move action for undo
     */
    fun endMovePoint() {
        if (state.isViewingHistory) return
        val selectedId = state.selectedPointId ?: return
        val startPos = moveStartPosition ?: return

        // Find the point type
        val refPoint = state.referencePoints.find { it.id == selectedId }
        val snakePoint = state.snakePoints.find { it.id == selectedId }
        val point = refPoint ?: snakePoint ?: return

        // Only record if position actually changed
        if (point.position != startPos) {
            val undoAction = UndoAction.MovePoint(selectedId, point.type, startPos)
            state = state.copy(undoStack = state.undoStack + undoAction)
            scheduleDraftSave()
        }

        moveStartPosition = null
    }

    fun unselectPoint() {
        // If we were moving a point, finalize the move
        if (moveStartPosition != null) {
            endMovePoint()
        }
        state = state.copy(selectedPointId = null)
    }

    fun clearCurrentMode() {
        if (state.isViewingHistory) return

        when (state.mode) {
            MeasurementMode.REFERENCE -> {
                state = state.copy(
                    referencePoints = emptyList(),
                    referenceLengthCm = 0f,
                    snakePoints = emptyList(),
                    calculatedSnakeLengthCm = 0f
                )
            }
            MeasurementMode.SNAKE -> {
                state = state.copy(
                    snakePoints = emptyList(),
                    calculatedSnakeLengthCm = 0f
                )
            }
        }
    }

    fun clearAll() {
        if (state.isViewingHistory) return

        state = state.copy(
            referencePoints = emptyList(),
            snakePoints = emptyList(),
            referenceLengthCm = 0f,
            calculatedSnakeLengthCm = 0f,
            selectedPointId = null,
            mode = MeasurementMode.REFERENCE,
            undoStack = emptyList() // Clear undo history
        )
        storageService.clearDraft()
    }

    // ========== Reference ==========

    fun setReferenceLength(length: Float) {
        if (state.isViewingHistory) return

        val lengthCm = state.selectedUnit.toCentimeters(length)
        state = state.copy(referenceLengthCm = lengthCm)
        updateSnakeLength()
        advanceTutorialIfNeeded() // Advance from SET_REFERENCE_SIZE

        // Auto-switch to snake mode after setting reference
        if (state.hasReferenceSizeSet) {
            // Analytics: track reference set
            if (state.cookieConsent?.analytics == true) {
                Analytics.trackEvent("Funnel", "reference_set", state.selectedUnit.abbreviation)
            }

            // Check free tier limit before switching to snake mode
            if (!state.canMeasure) {
                state = state.copy(showSizeModal = false)
                showPaywallModal()
                return
            }
            state = state.copy(mode = MeasurementMode.SNAKE, showSizeModal = false)
            advanceTutorialIfNeeded() // Advance from SWITCH_TO_SNAKE
        }
        scheduleDraftSave()
    }

    fun setUnit(unit: MeasurementUnit) {
        state = state.copy(selectedUnit = unit)
        storageService.saveUnit(unit.name)
    }

    private fun loadUnit() {
        val savedUnit = storageService.loadUnit()
        if (savedUnit != null) {
            try {
                val unit = MeasurementUnit.valueOf(savedUnit)
                state = state.copy(selectedUnit = unit)
            } catch (e: Exception) {
                // Invalid unit value, use default
            }
        }
    }

    private fun updateSnakeLength() {
        if (state.snakePoints.size >= 2 && state.referencePoints.size == 2 && state.referenceLengthCm > 0) {
            val snakeLength = MeasurementCalculator.calculateSnakeLengthInCm(
                snakePoints = state.snakePoints,
                referencePoints = state.referencePoints,
                referenceLengthCm = state.referenceLengthCm
            )
            state = state.copy(calculatedSnakeLengthCm = snakeLength)
        } else {
            state = state.copy(calculatedSnakeLengthCm = 0f)
        }
    }

    // ========== Zoom & Pan ==========

    fun setZoom(zoom: Float) {
        val constrainedZoom = zoom.coerceIn(state.minZoom, state.maxZoom)
        state = state.copy(zoomLevel = constrainedZoom)
    }

    fun setPan(offset: Offset, imageSize: Size, canvasSize: Size) {
        val constrainedPan = CoordinateTransform.constrainPan(
            offset, imageSize, canvasSize, state.zoomLevel
        )
        state = state.copy(panOffset = constrainedPan)
    }

    fun adjustZoom(delta: Float, focalPoint: Offset, imageSize: Size, canvasSize: Size) {
        val (newZoom, newPan) = CoordinateTransform.adjustZoomAtPoint(
            currentZoom = state.zoomLevel,
            zoomDelta = delta,
            focalPoint = focalPoint,
            currentPan = state.panOffset,
            imageSize = imageSize,
            canvasSize = canvasSize,
            minZoom = state.minZoom,
            maxZoom = state.maxZoom
        )
        state = state.copy(zoomLevel = newZoom, panOffset = newPan)
    }

    fun resetZoom() {
        state = state.copy(zoomLevel = 1f, panOffset = Offset.Zero)
    }

    fun zoomIn() {
        setZoom(state.zoomLevel * 1.3f)
    }

    fun zoomOut() {
        setZoom(state.zoomLevel / 1.3f)
    }

