        state = state.copy(measurementHistory = history)
    }

    fun saveMeasurement(): Boolean {
        if (!state.hasResult) return false

        // Check if user can measure (free tier limit)
        if (!state.canMeasure) {
            showPaywallModal()
            return false
        }

        // Encode images to base64
        val originalImage = state.imageBitmap
        val originalImageBase64 = originalImage?.let { ImageEncoder.encodeToBase64(it) }

        // Create thumbnail for fast display in history list (200px max)
        val thumbnailBase64 = originalImage?.let {
            val thumbnail = ImageEncoder.createThumbnail(it, maxSize = 200)
            ImageEncoder.encodeToBase64(thumbnail, maxSize = 0, quality = 70)
        }

        // Note: resultImageBase64 (image with measurement lines) would require
        // canvas capture which is complex. For now, we redraw lines from points.
        // TODO: Implement canvas capture for result image

        // Convert points to serializable format
        val serializableRefPoints = state.referencePoints.map { point ->
            SerializablePoint(point.position.x, point.position.y, point.type)
        }
        val serializableSnakePoints = state.snakePoints.map { point ->
            SerializablePoint(point.position.x, point.position.y, point.type)
        }

        val currentTime = PlatformInfo.currentTimeMillis()
        val record = MeasurementRecord(
            id = UuidGenerator.randomUUID(),
            timestamp = currentTime,
            snakeLengthCm = state.calculatedSnakeLengthCm,
            unit = state.selectedUnit,
            referenceLengthCm = state.referenceLengthCm,
            snakePointCount = state.snakePoints.size,
            // New fields
            originalImageBase64 = originalImageBase64,
            resultImageBase64 = null, // TODO: capture canvas with lines
            thumbnailBase64 = thumbnailBase64,
            // Legacy field for backwards compatibility
            imageBase64 = originalImageBase64,
            referencePoints = serializableRefPoints,
            snakePoints = serializableSnakePoints,
            // Sync metadata
            syncStatus = SyncStatus.NOT_SYNCED,
            syncedAt = null,
            serverId = null,
            updatedAt = currentTime
        )

        // Apply history limit for free users
        val historyLimit = if (state.isPremium) {
            PremiumFeatures.PREMIUM_HISTORY_UNLIMITED
        } else {
            PremiumFeatures.FREE_HISTORY_LIMIT
        }
        val updatedHistory = state.measurementHistory.addRecord(record, maxRecords = historyLimit)

        // Save and switch to read-only mode, show success
        state = state.copy(
            measurementHistory = updatedHistory,
            isViewingHistory = true,  // Switch to read-only after save
            lastSavedLengthCm = state.calculatedSnakeLengthCm,
            showSaveSuccessModal = true
        )
        storageService.saveHistory(updatedHistory)
        storageService.clearDraft()

        // Increment usage counter for free users
        if (!state.isPremium) {
            val updatedTracker = state.usageTracker.incrementMeasurement()
            state = state.copy(usageTracker = updatedTracker)
            storageService.saveUsageTracker(updatedTracker)
        }

        if (state.cookieConsent?.analytics == true) {
            Analytics.trackMeasurement(
                state.calculatedSnakeLengthCm,
                state.selectedUnit.abbreviation,
                state.snakePoints.size
            )
            // Track history count after save
            Analytics.trackEvent("History", "saved", updatedHistory.records.size.toString())
        }

        completeTutorialIfNeeded()
        return true
    }

    // ========== New Measurement Flow ==========

    /**
     * Start a new measurement - clears points but keeps the image
     */
    fun startNewMeasurement() {
        state = state.copy(
            referencePoints = emptyList(),
            snakePoints = emptyList(),
            referenceLengthCm = 0f,
            calculatedSnakeLengthCm = 0f,
            selectedPointId = null,
            mode = MeasurementMode.REFERENCE,
            isViewingHistory = false,
            undoStack = emptyList(),
            showSaveSuccessModal = false
        )
    }

    /**
     * Start a completely new measurement - clears everything including the image
     * Used when user wants to measure a new photo
     */
    fun startNewMeasurementWithNewImage() {
        state = state.copy(
            imageBitmap = null,
            imageUri = null,
            referencePoints = emptyList(),
            snakePoints = emptyList(),
            referenceLengthCm = 0f,
            calculatedSnakeLengthCm = 0f,
            selectedPointId = null,
            mode = MeasurementMode.REFERENCE,
            isViewingHistory = false,
            undoStack = emptyList(),
            showSaveSuccessModal = false,
            zoomLevel = 1f,
            panOffset = Offset.Zero
        )
    }

    /**
     * Try to start new measurement - shows warning if unsaved changes exist
     */
    fun tryStartNewMeasurement() {
        if (state.hasUnsavedChanges) {
            showUnsavedWarningModal()
        } else {
            startNewMeasurement()
        }
    }

    /**
     * Try to load new image - shows warning if unsaved changes exist
     */
    fun tryLoadNewImage(): Boolean {
        if (state.hasUnsavedChanges) {
            showUnsavedWarningModal()
            return false
        }
        return true
    }

    /**
     * Discard unsaved changes and proceed with action
     */
    fun discardAndStartNew() {
        hideUnsavedWarningModal()
        startNewMeasurement()
    }

    fun showUnsavedWarningModal() {
        state = state.copy(showUnsavedWarningModal = true)
    }

    fun hideUnsavedWarningModal() {
        state = state.copy(showUnsavedWarningModal = false)
    }

    fun hideSaveSuccessModal() {
        state = state.copy(showSaveSuccessModal = false)
    }

    fun loadMeasurement(record: MeasurementRecord) {
        // Decode image from base64 (use new method with fallback for old records)
        val imageBase64 = record.getDisplayImage()
        val imageBitmap = imageBase64?.let { ImageEncoder.decodeFromBase64(it) }

        if (imageBitmap == null && imageBase64 != null) {
            // Image decoding failed
            return
        }

        // Convert serializable points back to MeasurementPoints
        val referencePoints = record.referencePoints.map { point ->
            MeasurementPoint(
                id = UuidGenerator.randomUUID(),
                position = Offset(point.x, point.y),
                type = point.type
            )
        }
        val snakePoints = record.snakePoints.map { point ->
            MeasurementPoint(
                id = UuidGenerator.randomUUID(),
                position = Offset(point.x, point.y),
                type = point.type
            )
        }

        // Restore state (view-only mode)
        state = state.copy(
            imageBitmap = imageBitmap,
            imageUri = null, // We don't store the original URI
            referencePoints = referencePoints,
            snakePoints = snakePoints,
            referenceLengthCm = record.referenceLengthCm,
            calculatedSnakeLengthCm = record.snakeLengthCm,
            selectedUnit = record.unit,
            mode = MeasurementMode.SNAKE,
            zoomLevel = 1f,
            panOffset = Offset.Zero,
            showHistoryModal = false,
            isViewingHistory = true // Read-only mode
        )

        // Analytics: track history record loaded
        if (state.cookieConsent?.analytics == true) {
            Analytics.trackEvent("History", "record_loaded")
        }
    }

    fun deleteHistoryRecord(recordId: String) {
        val updatedHistory = state.measurementHistory.removeRecord(recordId)
        state = state.copy(measurementHistory = updatedHistory)
        storageService.saveHistory(updatedHistory)

        // Analytics: track record deleted with remaining count
        if (state.cookieConsent?.analytics == true) {
            Analytics.trackEvent("History", "record_deleted", updatedHistory.records.size.toString())
        }
