    private fun loadUsageTracker() {
        val currentTime = PlatformInfo.currentTimeMillis()
        var usageTracker = storageService.loadUsageTracker()

        // Check if we need to reset for a new month
        if (UsageTracker.isNewMonth(usageTracker, currentTime)) {
            usageTracker = usageTracker.resetForNewMonth(currentTime)
            storageService.saveUsageTracker(usageTracker)
        }

        // Initialize month start if it's 0 (first run)
        if (usageTracker.monthStartTimestamp == 0L) {
            usageTracker = usageTracker.copy(monthStartTimestamp = currentTime)
            storageService.saveUsageTracker(usageTracker)
        }

        state = state.copy(usageTracker = usageTracker)
    }

