    private fun handleAuthResult(result: AuthResult, provider: String) {
        when (result) {
            is AuthResult.Success -> {
                state = state.copy(
                    authState = AuthState(user = result.user, showProvidersModal = false),
                    showEmailAuthModal = false
                )
                // Analytics
                if (state.cookieConsent?.analytics == true) {
                    Analytics.trackEvent("Auth", "signed_in", provider)
                }
            }
            is AuthResult.Error -> {
                val friendlyMessage = AuthErrorMapper.mapError(result.message, state.currentLanguage)
                state = state.copy(
                    authState = state.authState.copy(
                        isLoading = false,
                        error = friendlyMessage,
                        rawError = result.message
                    )
                )
            }
            is AuthResult.Cancelled -> {
                state = state.copy(
                    authState = state.authState.copy(isLoading = false)
                )
            }
        }
    }

