    // ========== Help / Tutorial ==========

    private fun loadHelpState() {
        val helpState = storageService.loadHelpState()

        // If tutorial was completed, ensure it's not active
        if (helpState.tutorialCompleted) {
            val cleanState = helpState.copy(
                tutorialActive = false,
                currentStep = TutorialStep.WELCOME
            )
            state = state.copy(helpState = cleanState)
            // Save clean state if it was dirty
            if (helpState.tutorialActive) {
                storageService.saveHelpState(cleanState)
            }
        } else {
            // Show welcome dialog on first launch
            val updatedHelpState = helpState.copy(
                tutorialActive = true,
                currentStep = TutorialStep.WELCOME
            )
            state = state.copy(helpState = updatedHelpState)
        }
    }

    /** Start the interactive tutorial from welcome screen */
    fun startTutorial() {
