    /** Advance tutorial to next step based on current action */
    private fun advanceTutorialIfNeeded() {
        if (!state.helpState.tutorialActive) return

        val currentStep = state.helpState.currentStep
        val nextStep = when (currentStep) {
            TutorialStep.WELCOME -> null // Handled by startTutorial
            TutorialStep.UPLOAD_PHOTO -> {
                if (state.imageBitmap != null) TutorialStep.PLACE_REFERENCE_POINTS else null
            }
            TutorialStep.PLACE_REFERENCE_POINTS -> {
                if (state.referencePoints.size == 2) TutorialStep.SET_REFERENCE_SIZE else null
            }
            TutorialStep.SET_REFERENCE_SIZE -> {
                if (state.referenceLengthCm > 0) TutorialStep.SIZE_BUTTON_TIP else null
            }
            TutorialStep.SIZE_BUTTON_TIP -> null // Manual advance via advanceTutorialStep
            TutorialStep.SWITCH_TO_SNAKE -> {
                if (state.mode == MeasurementMode.SNAKE) TutorialStep.PLACE_SNAKE_POINTS else null
            }
            TutorialStep.PLACE_SNAKE_POINTS -> {
                if (state.snakePoints.size >= 2) TutorialStep.DRAG_POINTS_TIP else null
            }
            TutorialStep.DRAG_POINTS_TIP -> null // Manual advance via Got it
            TutorialStep.UNDO_TIP -> null // Manual advance via Got it
            TutorialStep.SAVE_RESULT -> null // Manual advance via Got it
            TutorialStep.HISTORY_TIP -> null // Manual advance via Got it
            TutorialStep.COMPLETED -> null
        }

        if (nextStep != null) {
            val updatedHelpState = state.helpState.copy(currentStep = nextStep)
            state = state.copy(helpState = updatedHelpState)
        }
    }

    /** Complete the tutorial (called after save) */
    private fun completeTutorialIfNeeded() {
        if (!state.helpState.tutorialActive) return
        if (state.helpState.currentStep != TutorialStep.SAVE_RESULT) return

        val updatedHelpState = state.helpState.copy(
            tutorialCompleted = true,
            currentStep = TutorialStep.COMPLETED
        )
        state = state.copy(helpState = updatedHelpState)
        storageService.saveHelpState(updatedHelpState)

        // Analytics: track tutorial completed
        if (state.cookieConsent?.analytics == true) {
            Analytics.trackEvent("Tutorial", "completed")
        }
    }

    /** Manually advance tutorial to next step (for tip steps) */
    fun advanceTutorialStep() {
        if (!state.helpState.tutorialActive) return

        val nextStep = when (state.helpState.currentStep) {
            TutorialStep.SIZE_BUTTON_TIP -> TutorialStep.SWITCH_TO_SNAKE
            TutorialStep.DRAG_POINTS_TIP -> TutorialStep.UNDO_TIP
            TutorialStep.UNDO_TIP -> TutorialStep.SAVE_RESULT
            TutorialStep.SAVE_RESULT -> TutorialStep.HISTORY_TIP
            TutorialStep.HISTORY_TIP -> TutorialStep.COMPLETED
            else -> return // Only tip steps can be manually advanced
        }

        val updatedHelpState = if (nextStep == TutorialStep.COMPLETED) {
            state.helpState.copy(tutorialCompleted = true, currentStep = nextStep)
        } else {
            state.helpState.copy(currentStep = nextStep)
        }
        state = state.copy(helpState = updatedHelpState)

        if (nextStep == TutorialStep.COMPLETED) {
            storageService.saveHelpState(updatedHelpState)
        }
    }

    /** Restart tutorial from settings */
    fun restartTutorial() {
        // Clear all data including image for fresh start
        startNewMeasurementWithNewImage()

        // Close settings modal if open
        val updatedHelpState = HelpState(
            tutorialCompleted = false,
            tutorialActive = true,
            currentStep = TutorialStep.UPLOAD_PHOTO
        )
        state = state.copy(
            helpState = updatedHelpState,
            showSettingsModal = false,
            showBottomSheet = false
        )
    }

    // ========== Draft Auto-Save ==========

    /**
     * Schedule a debounced draft save (2 sec delay).
     * Only saves when there's an image loaded and we're not viewing history.
     */
    private fun scheduleDraftSave() {
        if (PlatformInfo.isWeb) return

        draftSaveJob?.cancel()
        draftSaveJob = viewModelScope.launch {
            delay(2000)
            if (state.imageBitmap == null || state.isViewingHistory) return@launch

            val draft = DraftSession(
                referencePoints = state.referencePoints.map {
                    SerializablePoint(it.position.x, it.position.y, it.type)
                },
                snakePoints = state.snakePoints.map {
                    SerializablePoint(it.position.x, it.position.y, it.type)
                },
                referenceLengthCm = state.referenceLengthCm,
                calculatedSnakeLengthCm = state.calculatedSnakeLengthCm,
                selectedUnit = state.selectedUnit,
                mode = state.mode,
                zoomLevel = state.zoomLevel,
                panOffsetX = state.panOffset.x,
                panOffsetY = state.panOffset.y,
                isFullscreen = state.isFullscreen,
                timestamp = PlatformInfo.currentTimeMillis()
            )

            val json = draftJson.encodeToString(draft)
            val imageBase64 = state.imageBitmap?.let { ImageEncoder.encodeToBase64(it) }
            storageService.saveDraft(json, imageBase64)
        }
    }

    /**
     * Load draft session on startup if available.
     * Restores state including image, points, zoom, and mode.
     */
    private fun loadDraftIfAvailable() {
        if (PlatformInfo.isWeb) return

        try {
            val draftData = storageService.loadDraftData() ?: return
            val draft = draftJson.decodeFromString<DraftSession>(draftData)

            val imageBase64 = storageService.loadDraftImage()
            val imageBitmap = imageBase64?.let { ImageEncoder.decodeFromBase64(it) }

            if (imageBitmap == null) {
                // No image to restore — discard stale draft
                storageService.clearDraft()
                return
            }

            val referencePoints = draft.referencePoints.map { point ->
                MeasurementPoint(
                    id = UuidGenerator.randomUUID(),
                    position = Offset(point.x, point.y),
                    type = point.type
                )
            }
            val snakePoints = draft.snakePoints.map { point ->
                MeasurementPoint(
                    id = UuidGenerator.randomUUID(),
                    position = Offset(point.x, point.y),
                    type = point.type
                )
            }

            state = state.copy(
                imageBitmap = imageBitmap,
                referencePoints = referencePoints,
                snakePoints = snakePoints,
                referenceLengthCm = draft.referenceLengthCm,
                calculatedSnakeLengthCm = draft.calculatedSnakeLengthCm,
                selectedUnit = draft.selectedUnit,
                mode = draft.mode,
                zoomLevel = draft.zoomLevel,
                panOffset = Offset(draft.panOffsetX, draft.panOffsetY),
                isFullscreen = draft.isFullscreen,
                isViewingHistory = false
            )
        } catch (e: Exception) {
            println("Failed to restore draft: ${e.message}")
            storageService.clearDraft()
        }
    }

    // ========== Helpers ==========

    /**
     * Check if normalized position is inside image bounds (0.0-1.0)
     */
    private fun isPositionInsideImage(normalizedPosition: Offset): Boolean {
        return normalizedPosition.x in 0f..1f && normalizedPosition.y in 0f..1f
    }

    /**
     * Check if position is too close to any existing point.
     * Used to prevent accidental duplicate points from misclicks.
     * @param position Normalized position (0.0-1.0)
     * @param minDistance Minimum distance in normalized coordinates (default 0.03 = 3% of image)
     */
    private fun isTooCloseToExistingPoint(position: Offset, minDistance: Float = 0.03f): Boolean {
        val allPoints = state.referencePoints + state.snakePoints
        return allPoints.any { point ->
            val dx = point.position.x - position.x
            val dy = point.position.y - position.y
            val distance = kotlin.math.sqrt(dx * dx + dy * dy)
            distance < minDistance
        }
    }

    fun findNearestPoint(position: Offset, maxDistance: Float = 50f): MeasurementPoint? {
        val allPoints = state.referencePoints + state.snakePoints
        return MeasurementCalculator.findNearestPoint(position, allPoints, maxDistance)
    }

    fun getResultInCurrentUnit(): Float {
        return state.selectedUnit.fromCentimeters(state.calculatedSnakeLengthCm)
    }

    fun getReferenceLengthInCurrentUnit(): Float {
        return state.selectedUnit.fromCentimeters(state.referenceLengthCm)
    }
