package app.serpwidgets.snakemeasurer.ui.theme

import androidx.compose.runtime.Composable
import androidx.compose.runtime.staticCompositionLocalOf
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.sp

/**
 * Centralized typography system for Snake Measurer app.
 *
 * Scale based on Material Design 3 with adjustments for cross-platform readability.
 * All styles include explicit lineHeight for consistent rendering across iOS/Android/Web.
 */
data class AppTypographyScheme(
    // Display - Large prominent text (results, main values)
    val displayLarge: TextStyle,   // 28sp - Main measurement result
    val displayMedium: TextStyle,  // 24sp - Modal titles, large values
    val displaySmall: TextStyle,   // 20sp - Section headers, badges

    // Headline - Section titles and headers
    val headlineMedium: TextStyle, // 18sp - Modal titles
    val headlineSmall: TextStyle,  // 16sp - Important labels

    // Title - Prominent UI elements
    val titleLarge: TextStyle,     // 16sp - Primary buttons
    val titleMedium: TextStyle,    // 14sp - Secondary buttons, list titles
    val titleSmall: TextStyle,     // 13sp - Compact buttons

    // Body - Main content text
    val bodyLarge: TextStyle,      // 15sp - iOS-friendly body
    val bodyMedium: TextStyle,     // 14sp - Standard body text
    val bodySmall: TextStyle,      // 13sp - Secondary content

    // Label - UI labels and badges
    val labelLarge: TextStyle,     // 14sp - Prominent labels
    val labelMedium: TextStyle,    // 12sp - Standard labels, badges
    val labelSmall: TextStyle,     // 12sp - Minimum accessible size (was 10-11sp)

    // Caption - Timestamps, hints
    val caption: TextStyle,        // 12sp - Smallest readable text

    // Spaced variants for section headers
    val labelMediumSpaced: TextStyle  // 12sp with letter spacing for uppercase labels
)

/**
 * Default typography scheme
 */
val DefaultTypography = AppTypographyScheme(
    // Display styles - Bold, large, for emphasis
    displayLarge = TextStyle(
        fontSize = 28.sp,
        fontWeight = FontWeight.Bold,
        lineHeight = 34.sp
    ),
    displayMedium = TextStyle(
        fontSize = 24.sp,
        fontWeight = FontWeight.Bold,
        lineHeight = 30.sp
    ),
    displaySmall = TextStyle(
        fontSize = 20.sp,
        fontWeight = FontWeight.Bold,
        lineHeight = 26.sp
    ),

    // Headline styles - SemiBold for section headers
    headlineMedium = TextStyle(
        fontSize = 18.sp,
        fontWeight = FontWeight.SemiBold,
        lineHeight = 24.sp
    ),
    headlineSmall = TextStyle(
        fontSize = 16.sp,
        fontWeight = FontWeight.SemiBold,
        lineHeight = 22.sp
    ),

    // Title styles - For buttons and important UI
    titleLarge = TextStyle(
        fontSize = 16.sp,
        fontWeight = FontWeight.Bold,
        lineHeight = 22.sp
    ),
    titleMedium = TextStyle(
        fontSize = 14.sp,
        fontWeight = FontWeight.Bold,
        lineHeight = 20.sp
    ),
    titleSmall = TextStyle(
        fontSize = 13.sp,
        fontWeight = FontWeight.Bold,
        lineHeight = 18.sp
    ),

    // Body styles - Normal weight for readability
    bodyLarge = TextStyle(
        fontSize = 15.sp,
        fontWeight = FontWeight.Normal,
        lineHeight = 22.sp
    ),
    bodyMedium = TextStyle(
        fontSize = 14.sp,
        fontWeight = FontWeight.Normal,
        lineHeight = 20.sp
    ),
    bodySmall = TextStyle(
        fontSize = 13.sp,
        fontWeight = FontWeight.Normal,
        lineHeight = 18.sp
    ),

    // Label styles - Medium weight for UI labels
    labelLarge = TextStyle(
        fontSize = 14.sp,
        fontWeight = FontWeight.Medium,
        lineHeight = 20.sp
    ),
    labelMedium = TextStyle(
        fontSize = 12.sp,
        fontWeight = FontWeight.SemiBold,
        lineHeight = 16.sp
    ),
    labelSmall = TextStyle(
        fontSize = 12.sp,  // Minimum 12sp for WCAG accessibility
        fontWeight = FontWeight.SemiBold,
        lineHeight = 16.sp
    ),

    // Caption - For timestamps and hints
    caption = TextStyle(
        fontSize = 12.sp,
        fontWeight = FontWeight.Normal,
        lineHeight = 16.sp
    ),

    // Spaced variant for section headers (uppercase labels)
    labelMediumSpaced = TextStyle(
        fontSize = 12.sp,
        fontWeight = FontWeight.SemiBold,
        lineHeight = 16.sp,
        letterSpacing = 0.5.sp
    )
)

/**
 * CompositionLocal for typography access throughout the app
 */
val LocalAppTypography = staticCompositionLocalOf { DefaultTypography }

/**
 * Extension to access typography from AppTheme
 */
object AppTypography {
    val current: AppTypographyScheme
        @Composable
        get() = LocalAppTypography.current
}
