package app.serpwidgets.snakemeasurer.ui.theme

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.runtime.*
import androidx.compose.ui.graphics.Color

enum class ThemeMode {
    SYSTEM, LIGHT, DARK
}

data class AppColorScheme(
    // Backgrounds
    val bgPrimary: Color,
    val bgSecondary: Color,
    val bgTertiary: Color,
    val bgElevated: Color,

    // Text
    val textPrimary: Color,
    val textSecondary: Color,
    val textTertiary: Color,

    // Accents
    val reference: Color,
    val snake: Color,
    val accent: Color,
    val success: Color,
    val warning: Color,
    val danger: Color,

    // Neutrals
    val gray: Color,
    val grayLight: Color,
    val grayDark: Color,

    // Other
    val border: Color,
    val isDark: Boolean
)

private val LightColorScheme = AppColorScheme(
    bgPrimary = Color(0xFFFFFFFF),
    bgSecondary = Color(0xFFF2F2F7),
    bgTertiary = Color(0xFFFFFFFF),
    bgElevated = Color(0xFFFFFFFF),

    textPrimary = Color(0xFF000000),
    textSecondary = Color(0xFF3C3C43),
    textTertiary = Color(0x993C3C43),

    reference = Color(0xFF007AFF),
    snake = Color(0xFFAF52DE),
    accent = Color(0xFFFF9800),
    success = Color(0xFF34C759),
    warning = Color(0xFFFF9500),
    danger = Color(0xFFFF3B30),

    gray = Color(0xFF9E9E9E),
    grayLight = Color(0xFFE0E0E0),
    grayDark = Color(0xFF616161),

    border = Color(0xFFD1D1D6),
    isDark = false
)

private val DarkColorScheme = AppColorScheme(
    bgPrimary = Color(0xFF000000),
    bgSecondary = Color(0xFF1C1C1E),
    bgTertiary = Color(0xFF2C2C2E),
    bgElevated = Color(0xFF3A3A3C),

    textPrimary = Color(0xFFFFFFFF),
    textSecondary = Color(0xFFEBEBF5),
    textTertiary = Color(0x99EBEBF5),

    reference = Color(0xFF0A84FF),
    snake = Color(0xFFBF5AF2),
    accent = Color(0xFFFFB74D),
    success = Color(0xFF30D158),
    warning = Color(0xFFFF9F0A),
    danger = Color(0xFFFF453A),

    gray = Color(0xFF8E8E93),
    grayLight = Color(0xFF48484A),
    grayDark = Color(0xFFAEAEB2),

    border = Color(0xFF38383A),
    isDark = true
)

val LocalAppColors = compositionLocalOf { LightColorScheme }
val LocalThemeMode = compositionLocalOf { ThemeMode.SYSTEM }

object AppTheme {
    val colors: AppColorScheme
        @Composable
        @ReadOnlyComposable
        get() = LocalAppColors.current

    val typography: AppTypographyScheme
        @Composable
        @ReadOnlyComposable
        get() = LocalAppTypography.current
}

@Composable
fun AppThemeProvider(
    themeMode: ThemeMode,
    content: @Composable () -> Unit
) {
    val systemIsDark = isSystemInDarkTheme()

    val isDark = when (themeMode) {
        ThemeMode.SYSTEM -> systemIsDark
        ThemeMode.LIGHT -> false
        ThemeMode.DARK -> true
    }

    val colorScheme = if (isDark) DarkColorScheme else LightColorScheme

    CompositionLocalProvider(
        LocalAppColors provides colorScheme,
        LocalThemeMode provides themeMode,
        LocalAppTypography provides DefaultTypography
    ) {
        content()
    }
}
