package app.serpwidgets.snakemeasurer.util

import kotlinx.browser.window
import kotlin.js.Date

actual object PlatformInfo {
    actual val isWeb: Boolean = true
    actual val isAndroid: Boolean = false
    actual val isIOS: Boolean = false
    actual val platformName: String = "Web (JS)"

    actual fun currentTimeMillis(): Long = Date.now().toLong()

    actual fun getDeviceLanguage(): String {
        val lang = js("navigator.language || navigator.userLanguage || 'en'") as String
        return lang.split("-").firstOrNull() ?: "en"
    }

    actual fun openUrl(url: String) {
        window.open(url, "_blank")
    }

    actual fun onAppReady() {
        val hideLoader = window.asDynamic()._hideLoader
        if (hideLoader != null) {
            hideLoader()
        }
    }
}
