package app.serpwidgets.snakemeasurer.model

import kotlinx.serialization.Serializable

/**
 * Premium subscription state
 */
@Serializable
data class SubscriptionState(
    val isPremium: Boolean = false,
    val purchaseDate: Long? = null,
    val expirationDate: Long? = null, // null = lifetime
    val productId: String? = null
)

/**
 * Premium features and limits
 */
object PremiumFeatures {
    // Free tier limits
    // TESTING PHASE: Unlimited measurements (was 5, will be 50 after testing)
    const val FREE_MEASUREMENTS_PER_MONTH = Int.MAX_VALUE / 2
    const val FREE_HISTORY_LIMIT = 100 // Generous limit for testing

    // Premium benefits
    const val PREMIUM_MEASUREMENTS_UNLIMITED = Int.MAX_VALUE
    const val PREMIUM_HISTORY_UNLIMITED = Int.MAX_VALUE
}

/**
 * Available products for purchase
 */
enum class PremiumProduct(
