// Header button size - minimum touch target (44dp for accessibility)
val HeaderButtonSize = 44.dp
val HeaderIconSize = 20.dp

@Composable
fun HeaderButton(
    text: String,
    icon: String,
    isPrimary: Boolean,
    backgroundColor: Color? = null,
    onClick: () -> Unit
) {
    val colors = AppTheme.colors
    val bgColor = backgroundColor ?: if (isPrimary) colors.snake else colors.bgSecondary
    val textColor = if (isPrimary || backgroundColor != null) Color.White else colors.textPrimary

    Box(
        modifier = Modifier
            .clip(Shapes.small)
            .background(bgColor)
            .clickable(onClick = onClick)
            .padding(horizontal = ButtonDimens.paddingHorizontalSmall, vertical = ButtonDimens.paddingVerticalSmall)
    ) {
        Text(
            text = text,
            color = textColor,
            style = AppTheme.typography.titleSmall
        )
    }
}

@Composable
fun IconButton(
    icon: String,
    onClick: () -> Unit,
    showTooltip: Boolean = true
) {
    val colors = AppTheme.colors
    var isTooltipVisible by remember { mutableStateOf(false) }

    val iconResource = when (icon) {
        "history" -> Res.drawable.ic_history
        "settings" -> Res.drawable.ic_settings
        "moon" -> Res.drawable.ic_moon
        "sun" -> Res.drawable.ic_sun
        "auto" -> Res.drawable.ic_auto
        "menu" -> Res.drawable.ic_menu
        "refresh" -> Res.drawable.ic_refresh
        else -> Res.drawable.ic_settings
    }
    val tooltipText = when (icon) {
        "history" -> stringResource("open_history")
        "settings" -> stringResource("open_settings")
        "menu" -> stringResource("open_menu")
        "moon" -> stringResource("dark_theme")
        "sun" -> stringResource("light_theme")
        "auto" -> stringResource("system_theme")
        "refresh" -> stringResource("replace")
        else -> icon
    }

    // Auto-hide tooltip after delay
    LaunchedEffect(isTooltipVisible) {
        if (isTooltipVisible) {
            delay(2000)
            isTooltipVisible = false
        }
    }

    Box(
        modifier = Modifier
            .size(HeaderButtonSize)
            .clip(Shapes.small)
            .background(colors.bgSecondary)
            .pointerInput(Unit) {
                detectTapGestures(
                    onTap = { onClick() },
                    onLongPress = { isTooltipVisible = true }
                )
            },
        contentAlignment = Alignment.Center
    ) {
        Image(
            painter = painterResource(iconResource),
            contentDescription = tooltipText,
            modifier = Modifier.size(HeaderIconSize),
            colorFilter = ColorFilter.tint(colors.textPrimary)
        )

        // Tooltip as Popup (renders on top, doesn't affect layout)
        if (isTooltipVisible && showTooltip) {
            Popup(
                alignment = Alignment.BottomCenter,
                offset = IntOffset(0, 50),
                onDismissRequest = { isTooltipVisible = false },
                properties = PopupProperties(focusable = false)
            ) {
                Box(
                    modifier = Modifier
                        .shadow(4.dp, Shapes.small)
                        .clip(Shapes.small)
                        .background(colors.bgElevated)
                        .padding(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = tooltipText,
                        color = colors.textPrimary,
                        style = AppTheme.typography.caption
                    )
                }
            }
        }
    }
}

@Composable
fun ProfileAvatarButton(
    isLoggedIn: Boolean,
    userName: String?,
    onClick: () -> Unit,
    showTooltip: Boolean = true
) {
    val colors = AppTheme.colors
    var isTooltipVisible by remember { mutableStateOf(false) }

    val tooltipText = if (isLoggedIn) {
        stringResource("account")
    } else {
        stringResource("sign_in")
    }

    // Auto-hide tooltip after delay
    LaunchedEffect(isTooltipVisible) {
        if (isTooltipVisible) {
            delay(2000)
            isTooltipVisible = false
        }
    }

    Box(
        modifier = Modifier
            .size(HeaderButtonSize)
            .clip(Shapes.small)
            .background(if (isLoggedIn) colors.snake else colors.bgSecondary)
            .pointerInput(Unit) {
                detectTapGestures(
                    onTap = { onClick() },
                    onLongPress = { isTooltipVisible = true }
                )
            },
        contentAlignment = Alignment.Center
    ) {
        if (isLoggedIn && userName != null) {
            Text(
                text = userName.take(1).uppercase(),
                color = Color.White,
                style = AppTheme.typography.labelMedium
            )
        } else {
            Image(
                painter = painterResource(Res.drawable.ic_user),
                contentDescription = tooltipText,
                modifier = Modifier.size(HeaderIconSize),
                colorFilter = ColorFilter.tint(colors.textPrimary)
            )
        }

        // Tooltip as Popup
        if (isTooltipVisible && showTooltip) {
            Popup(
                alignment = Alignment.BottomCenter,
                offset = IntOffset(0, 50),
                onDismissRequest = { isTooltipVisible = false },
                properties = PopupProperties(focusable = false)
            ) {
                Box(
                    modifier = Modifier
                        .shadow(4.dp, Shapes.small)
                        .clip(Shapes.small)
                        .background(colors.bgElevated)
                        .padding(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = tooltipText,
                        color = colors.textPrimary,
                        style = AppTheme.typography.caption
                    )
                }
            }
        }
    }
}

@Composable
fun ModeButton(
    text: String,
    isActive: Boolean,
    activeColor: Color,
    enabled: Boolean = true,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors
    val bgColor = when {
        !enabled -> colors.bgSecondary.copy(alpha = 0.5f)
        isActive -> activeColor
        else -> colors.bgSecondary
    }
    val textColor = when {
        !enabled -> colors.textTertiary
        isActive -> Color.White
        else -> colors.textSecondary
    }

    Box(
        modifier = modifier
            .clip(Shapes.large)
            .background(bgColor)
            .then(if (enabled) Modifier.clickable(onClick = onClick) else Modifier)
            .padding(vertical = ButtonDimens.paddingVerticalMedium),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = text,
            color = textColor,
            style = AppTheme.typography.titleSmall
        )
    }
}

@Composable
fun SidePanelSection(
    title: String,
    isCompact: Boolean,
    content: @Composable () -> Unit
) {
    val colors = AppTheme.colors

    Column {
        Text(
            text = title.uppercase(),
            color = colors.textTertiary,
            style = AppTheme.typography.labelMediumSpaced
        )
        Spacer(modifier = Modifier.height(if (isCompact) Spacing.xxs + 2.dp else Spacing.xs))
        content()
    }
}

// Internal spacing - matches Spacing object
private object Spacing {
    val xxs = 4.dp
    val xs = 8.dp
}

@Composable
fun SidePanelModeButton(
    text: String,
    subtitle: String,
    isActive: Boolean,
    activeColor: Color,
    enabled: Boolean = true,
    onClick: () -> Unit,
    isCompact: Boolean
) {
    val colors = AppTheme.colors
    val bgColor = when {
        !enabled -> colors.bgSecondary.copy(alpha = 0.5f)
        isActive -> activeColor
        else -> colors.bgSecondary
    }
    val textColor = when {
        !enabled -> colors.textTertiary
        isActive -> Color.White
        else -> colors.textPrimary
    }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(Shapes.medium)
            .background(bgColor)
            .then(if (enabled) Modifier.clickable(onClick = onClick) else Modifier)
            .padding(if (isCompact) ButtonDimens.paddingVerticalSmall + 2.dp else ButtonDimens.paddingVerticalMedium)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = text,
                color = textColor,
                style = if (isCompact) AppTheme.typography.titleSmall else AppTheme.typography.titleMedium
            )
            Text(
                text = subtitle,
                color = if (isActive) Color.White.copy(alpha = 0.85f) else colors.textTertiary,
                style = AppTheme.typography.caption
            )
        }
    }
}
