package app.serpwidgets.snakemeasurer.util

/**
 * Firebase Analytics implementation for Web (JS)
 */
actual object Analytics {
    private var isInitialized = false
    private var analyticsEnabled = false

    actual fun initialize(analyticsEnabled: Boolean) {
        this.analyticsEnabled = analyticsEnabled
        if (analyticsEnabled && !isInitialized) {
            try {
                js("if (window.initFirebaseAnalytics) window.initFirebaseAnalytics(true)")
                isInitialized = true
                console.log("Firebase Analytics initialized")
            } catch (e: Exception) {
                console.error("Failed to initialize Firebase Analytics:", e.message)
            }
        }
    }

    actual fun trackEvent(category: String, action: String, label: String?) {
        if (!analyticsEnabled || !isInitialized) return

        try {
            val eventName = category.lowercase().replace(" ", "_")
            val labelValue = label ?: ""
            js("if (window.trackFirebaseEvent) window.trackFirebaseEvent(eventName, { category: category, action: action, label: labelValue })")
        } catch (e: Exception) {
            console.error("Failed to track event:", e.message)
        }
    }

    actual fun trackPageView(path: String) {
        if (!analyticsEnabled || !isInitialized) return

        try {
            js("if (window.trackFirebasePageView) window.trackFirebasePageView(path)")
        } catch (e: Exception) {
            console.error("Failed to track page view:", e.message)
        }
    }

    actual fun trackMeasurement(lengthCm: Float, unit: String, pointCount: Int) {
        if (!analyticsEnabled || !isInitialized) return

        try {
            js("if (window.trackFirebaseEvent) window.trackFirebaseEvent('snake_measurement', { length_cm: lengthCm, unit: unit, point_count: pointCount })")
        } catch (e: Exception) {
            console.error("Failed to track measurement:", e.message)
        }
    }
}
