package app.serpwidgets.snakemeasurer.resources

import app.serpwidgets.snakemeasurer.util.simpleFormat
import app.serpwidgets.snakemeasurer.model.Language
import app.serpwidgets.snakemeasurer.resources.strings.StringsDe
import app.serpwidgets.snakemeasurer.resources.strings.StringsEn
import app.serpwidgets.snakemeasurer.resources.strings.StringsEs
import app.serpwidgets.snakemeasurer.resources.strings.StringsFr
import app.serpwidgets.snakemeasurer.resources.strings.StringsIt
import app.serpwidgets.snakemeasurer.resources.strings.StringsPt
import app.serpwidgets.snakemeasurer.resources.strings.StringsNl
import app.serpwidgets.snakemeasurer.resources.strings.StringsPl
import app.serpwidgets.snakemeasurer.resources.strings.StringsRu
import app.serpwidgets.snakemeasurer.resources.strings.StringsUk
import app.serpwidgets.snakemeasurer.resources.strings.StringsAr
import app.serpwidgets.snakemeasurer.resources.strings.StringsJa
import app.serpwidgets.snakemeasurer.resources.strings.StringsKo


/**
 * Repository for accessing localized strings
 */
object StringsRepository {
    private val translations = mapOf(
        Language.ENGLISH to StringsEn.strings,
        Language.RUSSIAN to StringsRu.strings,
        Language.SPANISH to StringsEs.strings,
        Language.FRENCH to StringsFr.strings,
        Language.GERMAN to StringsDe.strings,
        Language.PORTUGUESE to StringsPt.strings,
        Language.ITALIAN to StringsIt.strings,
        Language.UKRAINIAN to StringsUk.strings,
        Language.DUTCH to StringsNl.strings,
        Language.POLISH to StringsPl.strings,
        Language.ARABIC to StringsAr.strings,
        Language.JAPANESE to StringsJa.strings,
        Language.KOREAN to StringsKo.strings
    )

    /**
     * Get a localized string by key for the given language
     * Falls back to English if language not supported, then to key itself
     */
    fun getString(key: String, language: Language): String {
        return translations[language]?.get(key)
            ?: translations[Language.ENGLISH]?.get(key)
            ?: key
    }

    /**
     * Get a localized string with format arguments
     */
    fun getString(key: String, language: Language, vararg args: Any): String {
        val toFormatStr = getString(key, language)
        return try {
            simpleFormat(toFormatStr, *args)
        } catch (e: Exception) {
            toFormatStr
        }
    }
}
