/**
 * State needed for SidePanel
 */
data class SidePanelState(
    val hasImage: Boolean,
    val isViewingHistory: Boolean,
    val mode: MeasurementMode,
    val referencePointsCount: Int,
    val snakePointsCount: Int,
    val hasReferenceComplete: Boolean,
    val referenceLengthCm: Float,
    val hasReferenceSizeSet: Boolean,
    val hasResult: Boolean,
    val isLoggedIn: Boolean,
    val userName: String?,
    val themeMode: ThemeMode,
    val hasHistoryRecords: Boolean,
    val selectedUnit: MeasurementUnit,
    val currentLanguage: Language,
    // Pre-formatted values (to avoid ViewModel dependency)
    val formattedReferenceLength: String,
    val formattedReferenceLengthWithUnit: String,
    val formattedResult: String,
    val formattedResultWithUnit: String
)

/**
 * Side panel with mode selector, reference size, result, and action buttons.
 * Used in landscape phone and tablet/web layouts.
 */
@Composable
fun SidePanel(
    state: SidePanelState,
    onLoadImage: () -> Unit,
    onAction: (MeasurementAction) -> Unit,
    isCompact: Boolean
) {
    val colors = AppTheme.colors
    val panelWidth = if (isCompact) 200.dp else 320.dp

    Column(
        modifier = Modifier
            .width(panelWidth)
            .fillMaxHeight()
            .background(colors.bgTertiary)
            .windowInsetsPadding(WindowInsets.safeDrawing)
            .verticalScroll(rememberScrollState())
            .padding(if (isCompact) Spacing.sm else Spacing.lg),
        verticalArrangement = Arrangement.spacedBy(if (isCompact) Spacing.sm else Spacing.md)
    ) {
        // Header with menu/buttons
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Image(
                painter = painterResource(Res.drawable.ic_snake),
                contentDescription = "Snake Measurer",
                modifier = Modifier.size(if (isCompact) Spacing.xxl else 40.dp)
            )

            if (isCompact) {
                // Mobile landscape - menu button
                Row(horizontalArrangement = Arrangement.spacedBy(Spacing.xs)) {
                    // TODO: Restore ProfileAvatarButton when backend auth is ready
//                    ProfileAvatarButton(
//                        isLoggedIn = state.isLoggedIn,
//                        userName = state.userName,
//                        onClick = {
//                            if (state.isLoggedIn) {
//                                onAction(MeasurementAction.ShowAccountModal)
//                            } else {
//                                onAction(MeasurementAction.ShowAuthProvidersModal)
//                            }
//                        }
//                    )

                    IconButton(
                        icon = "menu",
                        onClick = { onAction(MeasurementAction.ShowBottomSheet) }
                    )
                }
            } else {
                // Tablet/Web - show buttons directly
                Row(horizontalArrangement = Arrangement.spacedBy(Spacing.xs)) {
                    if (state.hasHistoryRecords) {
                        TutorialTargetBox(step = TutorialStep.HISTORY_TIP) {
                            IconButton(
                                icon = "history",
                                onClick = { onAction(MeasurementAction.ShowHistoryModal) }
                            )
                        }
                    }
                    IconButton(
                        icon = when (state.themeMode) {
                            ThemeMode.DARK -> "moon"
                            ThemeMode.LIGHT -> "sun"
                            ThemeMode.SYSTEM -> "auto"
                        },
                        onClick = { onAction(MeasurementAction.CycleTheme) }
                    )
                    // TODO: Restore ProfileAvatarButton when backend auth is ready
                    IconButton(
                        icon = "settings",
                        onClick = { onAction(MeasurementAction.ShowSettingsModal) }
                    )
                }
            }
        }

        // Upload/Replace/New Measurement button
        if (state.isViewingHistory) {
            // In view mode: show "New Measurement" instead of Replace
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.medium)
                    .background(colors.reference)
                    .clickable { onAction(MeasurementAction.StartNewMeasurementWithNewImage) }
                    .padding(vertical = if (isCompact) ButtonDimens.paddingVerticalSmall else ButtonDimens.paddingVerticalLarge),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("new_measurement"),
                    color = Color.White,
                    style = if (isCompact) AppTheme.typography.titleSmall else AppTheme.typography.titleMedium
                )
            }
        } else {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.medium)
                    .background(if (!state.hasImage) colors.snake else colors.bgSecondary)
                    .clickable(onClick = onLoadImage)
                    .padding(vertical = if (isCompact) ButtonDimens.paddingVerticalSmall else ButtonDimens.paddingVerticalLarge),
                contentAlignment = Alignment.Center
            ) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(Spacing.xs),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    if (state.hasImage) {
                        Image(
                            painter = painterResource(Res.drawable.ic_refresh),
                            contentDescription = null,
                            modifier = Modifier.size(18.dp),
                            colorFilter = ColorFilter.tint(colors.textPrimary)
                        )
                    }
                    Text(
                        text = if (!state.hasImage) stringResource("upload_photo") else stringResource("replace"),
                        color = if (!state.hasImage) Color.White else colors.textPrimary,
                        style = if (isCompact) AppTheme.typography.titleSmall else AppTheme.typography.titleMedium
                    )
                }
            }
        }

        if (state.hasImage) {
            // Mode selector
            SidePanelSection(title = stringResource("mode"), isCompact = isCompact) {
                Column(verticalArrangement = Arrangement.spacedBy(Spacing.xs)) {
                    SidePanelModeButton(
                        text = stringResource("reference"),
                        subtitle = "${state.referencePointsCount}/2 ${stringResource("points")}",
                        isActive = state.mode == MeasurementMode.REFERENCE,
                        activeColor = colors.reference,
                        onClick = { onAction(MeasurementAction.SetMode(MeasurementMode.REFERENCE)) },
                        isCompact = isCompact
                    )
                    TutorialTargetBox(step = TutorialStep.SWITCH_TO_SNAKE) {
                        SidePanelModeButton(
                            text = stringResource("snake"),
                            subtitle = "${state.snakePointsCount} ${stringResource("points")}",
                            isActive = state.mode == MeasurementMode.SNAKE,
                            activeColor = colors.snake,
                            enabled = state.hasReferenceSizeSet,
                            onClick = { onAction(MeasurementAction.SetMode(MeasurementMode.SNAKE)) },
                            isCompact = isCompact
                        )
                    }
                }
            }

            // Reference size
            if (state.hasReferenceComplete) {
                val needsSize = state.referenceLengthCm <= 0

                // Blinking animation for "Set Size" button (no scale to avoid text jumping)
                val infiniteTransition = rememberInfiniteTransition(label = "sidePanelPulse")
                val pulseAlpha by infiniteTransition.animateFloat(
                    initialValue = 1f,
                    targetValue = 0.5f,
                    animationSpec = infiniteRepeatable(
                        animation = tween(400, easing = LinearEasing),
                        repeatMode = RepeatMode.Reverse
                    ),
                    label = "alpha"
                )

                SidePanelSection(title = stringResource("reference_size"), isCompact = isCompact) {
                    TutorialTargetBox(step = TutorialStep.SIZE_BUTTON_TIP) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .then(if (needsSize) Modifier.graphicsLayer { alpha = pulseAlpha } else Modifier)
                                .clip(Shapes.small)
                                .background(if (needsSize) colors.reference else colors.bgSecondary)
                                .border(2.dp, colors.reference, Shapes.small)
                                .clickable { onAction(MeasurementAction.ShowSizeModal) }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.Center
                        ) {
                            if (!needsSize) {
                                Text(
                                    text = state.formattedReferenceLengthWithUnit,
                                    color = colors.textPrimary,
                                    style = if (isCompact) AppTheme.typography.headlineSmall else AppTheme.typography.headlineMedium
                                )
                            } else {
                                Text(
                                    text = stringResource("set_size"),
                                    color = Color.White,
                                    style = if (isCompact) AppTheme.typography.titleMedium else AppTheme.typography.titleLarge
                                )
                            }
                        }
                    }
                }
            }

            // Result
            AnimatedVisibility(visible = state.hasResult) {
                SidePanelSection(title = stringResource("result"), isCompact = isCompact) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(Shapes.large)
                            .background(colors.success.copy(alpha = 0.15f))
                            .border(2.dp, colors.success, Shapes.large)
                            .padding(Spacing.md),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = state.formattedResultWithUnit,
                            color = colors.success,
                            style = if (isCompact) AppTheme.typography.displayMedium.copy(fontSize = 22.sp, lineHeight = 28.sp) else AppTheme.typography.displayLarge
                        )
                    }
                }
            }

            // Spacer only for tablet/web to push buttons to bottom
            if (!isCompact) {
                Spacer(modifier = Modifier.weight(1f))
            }

            // View-only indicator
            if (state.isViewingHistory) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .padding(Spacing.sm),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = stringResource("view_only"),
                        color = colors.textTertiary,
                        style = AppTheme.typography.labelLarge
                    )
                }
            } else {
                // Action buttons (only in edit mode)
                val hasPoints = when (state.mode) {
                    MeasurementMode.REFERENCE -> state.referencePointsCount > 0
                    MeasurementMode.SNAKE -> state.snakePointsCount > 0
                }

                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                ) {
                    if (hasPoints) {
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .clip(Shapes.medium)
                                .background(colors.warning)
                                .clickable { onAction(MeasurementAction.UndoLastPoint) }
                                .padding(vertical = ButtonDimens.paddingVerticalMedium),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = stringResource("undo"),
                                color = Color.White,
                                style = AppTheme.typography.titleSmall
                            )
                        }
                        Box(
                            modifier = Modifier
                                .weight(1f)
                                .clip(Shapes.medium)
                                .background(colors.danger)
                                .clickable { onAction(MeasurementAction.ClearCurrentMode) }
                                .padding(vertical = ButtonDimens.paddingVerticalMedium),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = stringResource("clear"),
                                color = Color.White,
                                style = AppTheme.typography.titleSmall
                            )
                        }
                    }
                }

                // Save button
                if (state.hasResult) {
                    Spacer(modifier = Modifier.height(Spacing.xs))
                    TutorialTargetBox(
                        step = TutorialStep.SAVE_RESULT,
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.success)
                                .clickable { onAction(MeasurementAction.SaveMeasurement) }
                                .padding(vertical = ButtonDimens.paddingVerticalLarge),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = stringResource("save_measurement"),
                                color = Color.White,
                                style = AppTheme.typography.titleMedium
                            )
                        }
                    }
                }
            }
        }
    }
}
