package app.serpwidgets.snakemeasurer.util

import kotlinx.browser.localStorage
import kotlinx.browser.window
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import app.serpwidgets.snakemeasurer.model.CookieConsent
import app.serpwidgets.snakemeasurer.model.HelpState
import app.serpwidgets.snakemeasurer.model.MeasurementHistory
import app.serpwidgets.snakemeasurer.model.SubscriptionState
import app.serpwidgets.snakemeasurer.model.UsageTracker
import org.w3c.dom.events.Event

/**
 * IndexedDB-based implementation of MeasurementStorage for JS web platform
 * Uses IndexedDB for history (large data with images)
 * Uses localStorage for small settings (language, theme, etc.)
 */
class IndexedDbMeasurementStorage : MeasurementStorage {
    private val json = Json {
        ignoreUnknownKeys = true
        prettyPrint = false
    }

    // In-memory cache for history (loaded from IndexedDB on init)
    private var historyCache: MeasurementHistory? = null
    private var isIndexedDBReady = false

    init {
        // Initialize IndexedDB and load history into cache
        initIndexedDB()
    }

    // ==================== IndexedDB Setup ====================

    private fun initIndexedDB() {
        try {
            val request = window.asDynamic().indexedDB.open(DB_NAME, DB_VERSION)

            request.onerror = { event: Event ->
                console.error("IndexedDB error:", event)
                // Fallback: try to load from localStorage
                loadHistoryFromLocalStorage()
            }

            request.onsuccess = { _: Event ->
                val db = request.result
                isIndexedDBReady = true
                // Load history from IndexedDB into cache
                loadHistoryFromIndexedDB(db)
            }

            request.onupgradeneeded = { event: Event ->
                val db = request.result
                // Create object store for history if it doesn't exist
                if (!db.objectStoreNames.contains(HISTORY_STORE)) {
                    db.createObjectStore(HISTORY_STORE, js("{ keyPath: 'id' }"))
                    console.log("Created IndexedDB object store: $HISTORY_STORE")
                }
            }
        } catch (e: Exception) {
            console.error("Failed to init IndexedDB:", e.message)
            loadHistoryFromLocalStorage()
        }
    }

    private fun loadHistoryFromIndexedDB(db: dynamic) {
        try {
            val transaction = db.transaction(arrayOf(HISTORY_STORE), "readonly")
            val store = transaction.objectStore(HISTORY_STORE)
            val request = store.get(HISTORY_KEY)

            request.onsuccess = {
                val result = request.result
                if (result != null && result != undefined) {
                    try {
                        val jsonString = result.data as? String
                        if (jsonString != null) {
                            historyCache = json.decodeFromString<MeasurementHistory>(jsonString)
                            console.log("Loaded history from IndexedDB: ${historyCache?.records?.size ?: 0} records")
                        }
                    } catch (e: Exception) {
                        console.error("Failed to parse history from IndexedDB:", e.message)
                        historyCache = MeasurementHistory()
                    }
                } else {
                    // No history in IndexedDB, try localStorage migration
                    migrateFromLocalStorage(db)
                }
            }

            request.onerror = { event: Event ->
                console.error("Failed to load history from IndexedDB:", event)
                loadHistoryFromLocalStorage()
            }
        } catch (e: Exception) {
            console.error("Error loading from IndexedDB:", e.message)
            loadHistoryFromLocalStorage()
        }
    }

    private fun migrateFromLocalStorage(db: dynamic) {
        // Try to migrate existing data from localStorage to IndexedDB
        val oldHistory = loadHistoryFromLocalStorage()
        if (oldHistory.records.isNotEmpty()) {
            console.log("Migrating ${oldHistory.records.size} records from localStorage to IndexedDB")
            historyCache = oldHistory
            saveHistoryToIndexedDB(db, oldHistory)
        } else {
            historyCache = MeasurementHistory()
        }
    }

    private fun loadHistoryFromLocalStorage(): MeasurementHistory {
        return try {
            val jsonString = localStorage.getItem(HISTORY_KEY)
            if (jsonString != null) {
                json.decodeFromString<MeasurementHistory>(jsonString)
            } else {
                MeasurementHistory()
            }
        } catch (e: Exception) {
            console.error("Failed to load history from localStorage:", e.message)
            MeasurementHistory()
        }
    }

    private fun saveHistoryToIndexedDB(db: dynamic, history: MeasurementHistory) {
        try {
            val transaction = db.transaction(arrayOf(HISTORY_STORE), "readwrite")
            val store = transaction.objectStore(HISTORY_STORE)
            val jsonString = json.encodeToString(history)
            val data = js("({ id: arguments[0], data: arguments[1] })")
            data.id = HISTORY_KEY
            data.data = jsonString
            store.put(data)

            transaction.oncomplete = {
                console.log("History saved to IndexedDB: ${history.records.size} records")
            }

            transaction.onerror = { event: Event ->
                console.error("Failed to save history to IndexedDB:", event)
                // Fallback to localStorage
                saveHistoryToLocalStorage(history)
            }
        } catch (e: Exception) {
            console.error("Error saving to IndexedDB:", e.message)
            saveHistoryToLocalStorage(history)
        }
    }

    private fun saveHistoryToLocalStorage(history: MeasurementHistory) {
        try {
            val jsonString = json.encodeToString(history)
            localStorage.setItem(HISTORY_KEY, jsonString)
        } catch (e: Exception) {
            console.error("Failed to save history to localStorage:", e.message)
        }
    }

    private fun getIndexedDB(callback: (dynamic) -> Unit) {
        try {
            val request = window.asDynamic().indexedDB.open(DB_NAME, DB_VERSION)
            request.onsuccess = {
                callback(request.result)
            }
            request.onerror = {
                console.error("Failed to open IndexedDB")
            }
        } catch (e: Exception) {
            console.error("IndexedDB not available:", e.message)
        }
    }

    // ==================== History (IndexedDB) ====================

    override fun saveHistory(history: MeasurementHistory) {
        // Update cache immediately (synchronous behavior)
        historyCache = history

        // Save to IndexedDB asynchronously
        if (isIndexedDBReady) {
            getIndexedDB { db ->
                saveHistoryToIndexedDB(db, history)
            }
        } else {
            // Fallback to localStorage if IndexedDB not ready
            saveHistoryToLocalStorage(history)
        }
    }

    override fun loadHistory(): MeasurementHistory {
        // Return from cache (already loaded from IndexedDB)
        return historyCache ?: loadHistoryFromLocalStorage()
    }

    // ==================== Small Settings (localStorage) ====================

    override fun saveLanguage(languageCode: String) {
        try {
            localStorage.setItem(LANGUAGE_KEY, languageCode)
        } catch (e: Exception) {
            console.error("Failed to save language:", e.message)
        }
    }

    override fun loadLanguage(): String? {
        return try {
            localStorage.getItem(LANGUAGE_KEY)
        } catch (e: Exception) {
            console.error("Failed to load language:", e.message)
            null
        }
    }

    override fun saveCookieConsent(consent: CookieConsent) {
        try {
            val jsonString = json.encodeToString<CookieConsent>(consent)
            localStorage.setItem(COOKIE_CONSENT_KEY, jsonString)
        } catch (e: Exception) {
            console.error("Failed to save cookie consent:", e.message)
        }
    }

    override fun loadCookieConsent(): CookieConsent? {
        return try {
            val jsonString = localStorage.getItem(COOKIE_CONSENT_KEY)
            if (jsonString != null) {
                json.decodeFromString<CookieConsent>(jsonString)
            } else {
                null
            }
        } catch (e: Exception) {
            console.error("Failed to load cookie consent:", e.message)
            null
        }
    }

    override fun saveSubscription(subscription: SubscriptionState) {
        try {
            val jsonString = json.encodeToString<SubscriptionState>(subscription)
            localStorage.setItem(SUBSCRIPTION_KEY, jsonString)
        } catch (e: Exception) {
            console.error("Failed to save subscription:", e.message)
        }
    }

    override fun loadSubscription(): SubscriptionState {
        return try {
            val jsonString = localStorage.getItem(SUBSCRIPTION_KEY)
            if (jsonString != null) {
                json.decodeFromString<SubscriptionState>(jsonString)
            } else {
                SubscriptionState()
            }
        } catch (e: Exception) {
            console.error("Failed to load subscription:", e.message)
            SubscriptionState()
        }
    }

    override fun saveUsageTracker(usageTracker: UsageTracker) {
        try {
            val jsonString = json.encodeToString<UsageTracker>(usageTracker)
            localStorage.setItem(USAGE_TRACKER_KEY, jsonString)
        } catch (e: Exception) {
            console.error("Failed to save usage tracker:", e.message)
        }
    }

    override fun loadUsageTracker(): UsageTracker {
        return try {
            val jsonString = localStorage.getItem(USAGE_TRACKER_KEY)
            if (jsonString != null) {
                json.decodeFromString<UsageTracker>(jsonString)
            } else {
                UsageTracker()
            }
        } catch (e: Exception) {
            console.error("Failed to load usage tracker:", e.message)
            UsageTracker()
        }
    }

    override fun saveTheme(themeMode: String) {
        try {
            localStorage.setItem(THEME_KEY, themeMode)
        } catch (e: Exception) {
            console.error("Failed to save theme:", e.message)
        }
    }

    override fun loadTheme(): String? {
        return try {
            localStorage.getItem(THEME_KEY)
        } catch (e: Exception) {
            console.error("Failed to load theme:", e.message)
            null
        }
    }

    override fun saveUnit(unit: String) {
        try {
            localStorage.setItem(UNIT_KEY, unit)
        } catch (e: Exception) {
            console.error("Failed to save unit:", e.message)
        }
    }

    override fun loadUnit(): String? {
        return try {
            localStorage.getItem(UNIT_KEY)
        } catch (e: Exception) {
            console.error("Failed to load unit:", e.message)
            null
        }
    }

    override fun saveHelpState(helpState: HelpState) {
        try {
            val jsonString = json.encodeToString<HelpState>(helpState)
            localStorage.setItem(HELP_STATE_KEY, jsonString)
        } catch (e: Exception) {
            console.error("Failed to save help state:", e.message)
        }
    }

    override fun loadHelpState(): HelpState {
        return try {
            val jsonString = localStorage.getItem(HELP_STATE_KEY)
            if (jsonString != null) {
                json.decodeFromString<HelpState>(jsonString)
            } else {
                HelpState()
            }
        } catch (e: Exception) {
            console.error("Failed to load help state:", e.message)
            HelpState()
        }
    }

    companion object {
        // IndexedDB config
        private const val DB_NAME = "snake_measurer_db"
        private const val DB_VERSION = 1
        private const val HISTORY_STORE = "history"

        // Keys
        private const val HISTORY_KEY = "snake_measurer_history"
        private const val LANGUAGE_KEY = "snake_measurer_language"
        private const val COOKIE_CONSENT_KEY = "snake_measurer_cookie_consent"
        private const val SUBSCRIPTION_KEY = "snake_measurer_subscription"
        private const val USAGE_TRACKER_KEY = "snake_measurer_usage_tracker"
        private const val THEME_KEY = "snake_measurer_theme"
        private const val UNIT_KEY = "snake_measurer_unit"
        private const val HELP_STATE_KEY = "snake_measurer_help_state"
    }
}

/**
 * Creates IndexedDB-based MeasurementStorage for JS
 */
actual fun createMeasurementStorage(): MeasurementStorage {
    return IndexedDbMeasurementStorage()
}
