package app.serpwidgets.snakemeasurer.model

import kotlinx.serialization.Serializable

/**
 * Auto-saved draft session data for mobile platforms.
 * Restored on app relaunch after process death.
 * Image is stored separately (base64 in DraftImageEntity).
 */
@Serializable
data class DraftSession(
    val referencePoints: List<SerializablePoint> = emptyList(),
    val snakePoints: List<SerializablePoint> = emptyList(),
    val referenceLengthCm: Float = 0f,
    val calculatedSnakeLengthCm: Float = 0f,
    val selectedUnit: MeasurementUnit = MeasurementUnit.CENTIMETERS,
    val mode: MeasurementMode = MeasurementMode.REFERENCE,
    val zoomLevel: Float = 1f,
    val panOffsetX: Float = 0f,
    val panOffsetY: Float = 0f,
    val isFullscreen: Boolean = false,
    val timestamp: Long = 0L
)
