package app.serpwidgets.snakemeasurer.ui.components.modals

import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.ColorFilter
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import snakemeasurer.composeapp.generated.resources.Res
import snakemeasurer.composeapp.generated.resources.ic_close
import snakemeasurer.composeapp.generated.resources.ic_auto
import snakemeasurer.composeapp.generated.resources.ic_sun
import snakemeasurer.composeapp.generated.resources.ic_moon
import app.serpwidgets.snakemeasurer.model.Language
import app.serpwidgets.snakemeasurer.ui.stringResource
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.ui.theme.IconButtonDimens
import app.serpwidgets.snakemeasurer.ui.theme.Shapes
import app.serpwidgets.snakemeasurer.ui.theme.Spacing
import app.serpwidgets.snakemeasurer.ui.theme.ThemeMode
import org.jetbrains.compose.resources.painterResource

@Composable
fun SettingsModal(
    currentLanguage: Language,
    currentTheme: ThemeMode,
    onLanguageChange: (Language) -> Unit,
    onThemeChange: (ThemeMode) -> Unit,
    onClearAll: () -> Unit,
    onShowTutorial: () -> Unit = {},
    onShowFaq: () -> Unit = {},
    onOpenPrivacyPolicy: () -> Unit = {},
    onOpenTerms: () -> Unit = {},
    onOpenAppStore: () -> Unit = {},
    onOpenGooglePlay: () -> Unit = {},
    onOpenTelegram: () -> Unit = {},
    hasPoints: Boolean,
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors

    // Backdrop
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.5f))
            .clickable(onClick = onDismiss),
        contentAlignment = Alignment.Center
    ) {
        // Modal content
        Column(
            modifier = Modifier
                .widthIn(max = 420.dp)
                .fillMaxWidth(0.95f)
                .heightIn(max = 650.dp)
                .clip(Shapes.modal)
                .background(colors.bgTertiary)
                .clickable(enabled = false) {}
        ) {
            // Header
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(Spacing.lg),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = stringResource("settings"),
                    color = colors.textPrimary,
                    style = AppTheme.typography.headlineMedium
                )

                Box(
                    modifier = Modifier
                        .size(IconButtonDimens.size)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(onClick = onDismiss),
                    contentAlignment = Alignment.Center
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_close),
                        contentDescription = stringResource("close"),
                        modifier = Modifier.size(IconButtonDimens.iconSize),
                        colorFilter = ColorFilter.tint(colors.textPrimary)
                    )
                }
            }

            // Settings content (scrollable)
            Column(
                modifier = Modifier
                    .weight(1f, fill = false)
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = Spacing.lg, vertical = Spacing.xs),
                verticalArrangement = Arrangement.spacedBy(Spacing.md)
            ) {
                // Language
                SettingsSection(title = stringResource("language")) {
                    // Languages in a wrapped grid (3 columns)
                    val languages = Language.entries
                    val chunkedLanguages = languages.chunked(3)

                    Column(verticalArrangement = Arrangement.spacedBy(Spacing.xs)) {
                        chunkedLanguages.forEach { row ->
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                            ) {
                                row.forEach { lang ->
                                    LanguageChip(
                                        language = lang,
                                        isSelected = lang == currentLanguage,
                                        onClick = { onLanguageChange(lang) },
                                        modifier = Modifier.weight(1f)
                                    )
                                }
                                // Fill empty slots if last row is not complete
                                repeat(3 - row.size) {
                                    Spacer(modifier = Modifier.weight(1f))
                                }
                            }
                        }
                    }
                }

                // Theme
                SettingsSection(title = stringResource("theme")) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                    ) {
                        ThemeOption(
                            text = stringResource("theme_auto"),
                            themeMode = ThemeMode.SYSTEM,
                            isSelected = currentTheme == ThemeMode.SYSTEM,
                            onClick = { onThemeChange(ThemeMode.SYSTEM) },
                            modifier = Modifier.weight(1f)
                        )
                        ThemeOption(
                            text = stringResource("theme_light"),
                            themeMode = ThemeMode.LIGHT,
                            isSelected = currentTheme == ThemeMode.LIGHT,
                            onClick = { onThemeChange(ThemeMode.LIGHT) },
                            modifier = Modifier.weight(1f)
                        )
                        ThemeOption(
                            text = stringResource("theme_dark"),
                            themeMode = ThemeMode.DARK,
                            isSelected = currentTheme == ThemeMode.DARK,
                            onClick = { onThemeChange(ThemeMode.DARK) },
                            modifier = Modifier.weight(1f)
                        )
                    }
                }

                // Help & Support section
                SettingsSection(title = stringResource("help_support")) {
                    Column(verticalArrangement = Arrangement.spacedBy(Spacing.xs)) {
                        // Tutorial
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.bgSecondary)
                                .clickable {
                                    onShowTutorial()
                                    onDismiss()
                                }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Text(
                                text = stringResource("show_tutorial"),
                                color = colors.accent,
                                style = AppTheme.typography.titleMedium
                            )
                        }

                        // FAQ
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.bgSecondary)
                                .clickable {
                                    onShowFaq()
                                    onDismiss()
                                }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Text(
                                text = stringResource("faq"),
                                color = colors.textPrimary,
                                style = AppTheme.typography.titleMedium
                            )
                        }

                        // Privacy Policy
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.bgSecondary)
                                .clickable {
                                    onOpenPrivacyPolicy()
                                    onDismiss()
                                }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Text(
                                text = stringResource("privacy_policy"),
                                color = colors.textPrimary,
                                style = AppTheme.typography.titleMedium
                            )
                        }

                        // Terms of Service
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.bgSecondary)
                                .clickable {
                                    onOpenTerms()
                                    onDismiss()
                                }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Text(
                                text = stringResource("terms_of_service"),
                                color = colors.textPrimary,
                                style = AppTheme.typography.titleMedium
                            )
                        }
                    }
                }

                // Get the App section
                SettingsSection(title = stringResource("get_the_app")) {
                    Column(verticalArrangement = Arrangement.spacedBy(Spacing.xs)) {
                        // App Store
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.bgSecondary)
                                .clickable {
                                    onOpenAppStore()
                                    onDismiss()
                                }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Text(
                                text = stringResource("app_store"),
                                color = colors.textPrimary,
                                style = AppTheme.typography.titleMedium
                            )
                        }

                        // Google Play
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.bgSecondary)
                                .clickable {
                                    onOpenGooglePlay()
                                    onDismiss()
                                }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Text(
                                text = stringResource("google_play"),
                                color = colors.textPrimary,
                                style = AppTheme.typography.titleMedium
                            )
                        }

                        // Telegram
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(Shapes.medium)
                                .background(colors.bgSecondary)
                                .clickable {
                                    onOpenTelegram()
                                    onDismiss()
                                }
                                .padding(Spacing.sm),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Text(
                                text = stringResource("telegram"),
                                color = colors.accent,
                                style = AppTheme.typography.titleMedium
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(Spacing.lg))
        }
    }
}

@Composable
private fun SettingsSection(
    title: String,
    content: @Composable () -> Unit
) {
    val colors = AppTheme.colors

    Column {
        Text(
            text = title.uppercase(),
            color = colors.textTertiary,
            style = AppTheme.typography.labelMediumSpaced
        )
        Spacer(modifier = Modifier.height(Spacing.xs))
        content()
    }
}

@Composable
private fun LanguageChip(
    language: Language,
    isSelected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors

    Box(
        modifier = modifier
            .clip(Shapes.small)
            .background(if (isSelected) colors.snake else colors.bgSecondary)
            .clickable(onClick = onClick)
            .padding(horizontal = Spacing.xs, vertical = Spacing.sm),
        contentAlignment = Alignment.Center
    ) {
        Row(
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Language code badge
            Box(
                modifier = Modifier
                    .clip(RoundedCornerShape(Spacing.xxs))
                    .background(if (isSelected) Color.White.copy(alpha = 0.2f) else colors.bgTertiary)
                    .padding(horizontal = Spacing.xxs, vertical = 2.dp)
            ) {
                Text(
                    text = language.code.uppercase(),
                    color = if (isSelected) Color.White else colors.textTertiary,
                    style = AppTheme.typography.labelMedium
                )
            }
            Spacer(modifier = Modifier.width(6.dp))
            Text(
                text = language.displayName, // English name instead of native
                color = if (isSelected) Color.White else colors.textPrimary,
                style = AppTheme.typography.labelMedium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
private fun ThemeOption(
    text: String,
    themeMode: ThemeMode,
    isSelected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors
    val iconResource = when (themeMode) {
        ThemeMode.SYSTEM -> Res.drawable.ic_auto
        ThemeMode.LIGHT -> Res.drawable.ic_sun
        ThemeMode.DARK -> Res.drawable.ic_moon
    }

    Box(
        modifier = modifier
            .clip(Shapes.small)
            .background(if (isSelected) colors.snake else colors.bgSecondary)
            .clickable(onClick = onClick)
            .padding(horizontal = Spacing.xs, vertical = Spacing.sm),
        contentAlignment = Alignment.Center
    ) {
        Row(
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Image(
                painter = painterResource(iconResource),
                contentDescription = text,
                modifier = Modifier.size(IconButtonDimens.iconSize),
                colorFilter = ColorFilter.tint(if (isSelected) Color.White else colors.textPrimary)
            )
            Spacer(modifier = Modifier.width(6.dp))
            Text(
                text = text,
                color = if (isSelected) Color.White else colors.textPrimary,
                style = AppTheme.typography.labelMedium
            )
        }
    }
}
