/**
 * Floating zoom controls for canvas.
 * Can show fullscreen toggle button on small screens.
 * Long press shows tooltip.
 */
@Composable
fun FloatingZoomControls(
    isFullscreen: Boolean,
    showFullscreenButton: Boolean = true,
    onAction: (MeasurementAction) -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors

    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(Spacing.sm)
    ) {
        // Fullscreen toggle (only on small screens)
        if (showFullscreenButton) {
            ZoomControlButton(
                iconRes = if (isFullscreen) Res.drawable.ic_fullscreen_exit else Res.drawable.ic_fullscreen,
                tooltipText = stringResource("toggle_fullscreen"),
                backgroundColor = if (isFullscreen) colors.snake else colors.bgElevated,
                iconTint = if (isFullscreen) Color.White else colors.textPrimary,
                onClick = { onAction(MeasurementAction.ToggleFullscreen) }
            )
        }

        // Zoom in
        ZoomControlButton(
            iconRes = Res.drawable.ic_zoom_in,
            tooltipText = stringResource("zoom_in"),
            backgroundColor = colors.bgElevated,
            iconTint = colors.textPrimary,
            onClick = { onAction(MeasurementAction.ZoomIn) }
        )

        // Zoom out
        ZoomControlButton(
            iconRes = Res.drawable.ic_zoom_out,
            tooltipText = stringResource("zoom_out"),
            backgroundColor = colors.bgElevated,
            iconTint = colors.textPrimary,
            onClick = { onAction(MeasurementAction.ZoomOut) }
        )
    }
}

@Composable
private fun ZoomControlButton(
    iconRes: org.jetbrains.compose.resources.DrawableResource,
    tooltipText: String,
    backgroundColor: Color,
    iconTint: Color,
    onClick: () -> Unit
) {
    val colors = AppTheme.colors
    var isTooltipVisible by remember { mutableStateOf(false) }

    // Auto-hide tooltip after delay
    LaunchedEffect(isTooltipVisible) {
        if (isTooltipVisible) {
            delay(2000)
            isTooltipVisible = false
        }
    }

    Box(
        modifier = Modifier
            .size(IconButtonDimens.sizeLarge)
            .shadow(Spacing.xs, CircleShape)
            .clip(CircleShape)
            .background(backgroundColor)
            .pointerInput(Unit) {
                detectTapGestures(
                    onTap = { onClick() },
                    onLongPress = { isTooltipVisible = true }
                )
            },
        contentAlignment = Alignment.Center
    ) {
        Image(
            painter = painterResource(iconRes),
            contentDescription = tooltipText,
            modifier = Modifier.size(IconButtonDimens.iconSizeLarge),
            colorFilter = ColorFilter.tint(iconTint)
        )

        // Tooltip as Popup (renders on top, doesn't affect layout)
        // Positioned below and to the left to avoid going off-screen
        if (isTooltipVisible) {
            Popup(
                alignment = Alignment.BottomStart,
                offset = IntOffset(-80, 8),
                onDismissRequest = { isTooltipVisible = false },
                properties = PopupProperties(focusable = false)
            ) {
                Box(
                    modifier = Modifier
                        .shadow(4.dp, Shapes.small)
                        .clip(Shapes.small)
                        .background(colors.bgElevated)
                        .padding(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = tooltipText,
                        color = colors.textPrimary,
                        style = AppTheme.typography.caption,
                        maxLines = 1
                    )
                }
            }
        }
    }
}
