package app.serpwidgets.snakemeasurer

import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.layout.onGloballyPositioned
import androidx.compose.ui.unit.dp
import androidx.compose.ui.zIndex
import androidx.lifecycle.viewmodel.compose.viewModel
import app.serpwidgets.snakemeasurer.ui.ProvideLanguage
import app.serpwidgets.snakemeasurer.ui.components.CookieConsentBanner
import app.serpwidgets.snakemeasurer.ui.components.CookiePreferencesDialog
import app.serpwidgets.snakemeasurer.ui.components.modals.ImageSourcePickerModal
import app.serpwidgets.snakemeasurer.ui.screens.MeasurementScreen
import app.serpwidgets.snakemeasurer.ui.theme.AppThemeProvider
import app.serpwidgets.snakemeasurer.util.ImageSource
import app.serpwidgets.snakemeasurer.util.PlatformInfo
import app.serpwidgets.snakemeasurer.util.rememberImagePicker
import app.serpwidgets.snakemeasurer.util.rememberImagePickerWithSource
import app.serpwidgets.snakemeasurer.viewmodel.MeasurementViewModel
import org.jetbrains.compose.ui.tooling.preview.Preview

@Composable
@Preview
fun App() {
    val viewModel: MeasurementViewModel = viewModel { MeasurementViewModel() }
    var showPreferencesDialog by remember { mutableStateOf(false) }
    var showImageSourcePicker by remember { mutableStateOf(false) }
    var loaderHidden by remember { mutableStateOf(false) }

    // Image picker with source selection (for native platforms)
    val imagePickerWithSource = rememberImagePickerWithSource { imageBitmap, uri ->
        viewModel.setImage(imageBitmap, uri)
    }

    // Simple image picker (for web - browser shows its own picker with camera option)
    val simpleImagePicker = rememberImagePicker { imageBitmap, uri ->
        viewModel.setImage(imageBitmap, uri)
    }

    // Check for free tier limit and unsaved changes before loading new image
    val onLoadImage: () -> Unit = {
        // Check free tier limit first
        if (!viewModel.state.canMeasure) {
            viewModel.showPaywallModal()
        } else if (viewModel.state.hasUnsavedChanges) {
            viewModel.showUnsavedWarningModal()
        } else {
            // On web: browser shows its own picker with camera option on mobile
            // On native: show our custom source picker
            if (PlatformInfo.isWeb) {
                simpleImagePicker()
            } else {
                showImageSourcePicker = true
            }
        }
    }

    // Wrap app with theme and language providers
    AppThemeProvider(themeMode = viewModel.state.themeMode) {
        ProvideLanguage(language = viewModel.state.currentLanguage) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .onGloballyPositioned {
                        // Hide loader only when UI is actually rendered
                        if (!loaderHidden) {
                            loaderHidden = true
                            PlatformInfo.onAppReady()
                        }
                    }
            ) {
                MeasurementScreen(
                    onLoadImage = onLoadImage,
                    viewModel = viewModel,
                    modifier = Modifier.fillMaxSize()
                )

                // Image source picker (native platforms only)
                if (showImageSourcePicker) {
                    ImageSourcePickerModal(
                        onSourceSelected = { source ->
                            imagePickerWithSource(source)
                        },
                        onDismiss = { showImageSourcePicker = false }
                    )
                }

                // Cookie consent banner (web only)
                if (PlatformInfo.isWeb && viewModel.state.showCookieBanner) {
                    CookieConsentBanner(
                        onAcceptAll = { viewModel.acceptAllCookies() },
                        onRejectNonEssential = { viewModel.rejectNonEssentialCookies() },
                        onManagePreferences = { showPreferencesDialog = true },
                        modifier = Modifier
                            .align(Alignment.BottomCenter)
                            .fillMaxWidth()
                            .padding(16.dp)
                            .zIndex(100f)
                    )
                }

                // Cookie preferences dialog
                if (showPreferencesDialog) {
                    CookiePreferencesDialog(
                        currentConsent = viewModel.state.cookieConsent ?: app.serpwidgets.snakemeasurer.model.CookieConsent(),
                        onSave = { consent ->
                            viewModel.setCustomCookieConsent(consent)
                            showPreferencesDialog = false
                        },
                        onDismiss = { showPreferencesDialog = false }
                    )
                }
            }
        }
    }
}
