/**
 * Layout mode for responsive design
 */
private enum class LayoutMode {
    PORTRAIT_PHONE,    // Vertical phone - bottom bar
    LANDSCAPE_PHONE,   // Horizontal phone - side panel
    TABLET_WEB         // Tablet/web - spacious side panel
}

// Privacy Policy & Terms of Service URLs
private fun getPolicyUrl(lang: Language) = "https://snakemeasurer.com/privacy-policy${if (lang == Language.ENGLISH) "" else "-${lang.code}"}.html"
private fun getTermsUrl(lang: Language) = "https://snakemeasurer.com/terms${if (lang == Language.ENGLISH) "" else "-${lang.code}"}.html"

// App Store, Google Play & Telegram URLs
private const val APP_STORE_URL = "https://apps.apple.com/app/snake-measurer/id000000000"
private const val GOOGLE_PLAY_URL = "https://play.google.com/store/apps/details?id=app.serpwidgets.snakemeasurer"
private const val TELEGRAM_URL = "https://t.me/snakemeasurer"

@Composable
fun MeasurementScreen(
    onLoadImage: () -> Unit,
    modifier: Modifier = Modifier,
    viewModel: MeasurementViewModel = viewModel { MeasurementViewModel() }
) {
    val state = viewModel.state
    val colors = AppTheme.colors
    val tutorialRegistry = rememberTutorialTargetRegistry()

    CompositionLocalProvider(LocalTutorialTargetRegistry provides tutorialRegistry) {
        Box(
            modifier = modifier
                .fillMaxSize()
                .background(colors.bgPrimary)
        ) {
            BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
                // Determine layout mode based on screen dimensions
                val layoutMode = when {
                    // Tablet or web: wide enough for comfortable side panel
                    maxWidth > 900.dp -> LayoutMode.TABLET_WEB
                    // Landscape phone: width > height and not too small
                    maxWidth > maxHeight && maxHeight < 500.dp -> LayoutMode.LANDSCAPE_PHONE
                    // Wide but short (landscape tablet)
                    maxWidth > 700.dp && maxHeight < 600.dp -> LayoutMode.LANDSCAPE_PHONE
                    // Portrait phone or small tablet
                    else -> LayoutMode.PORTRAIT_PHONE
                }

                when (layoutMode) {
                    LayoutMode.PORTRAIT_PHONE -> PortraitPhoneLayout(
                        viewModel = viewModel,
                        onLoadImage = onLoadImage
                    )
                    LayoutMode.LANDSCAPE_PHONE -> LandscapePhoneLayout(
                        viewModel = viewModel,
                        onLoadImage = onLoadImage
                    )
                    LayoutMode.TABLET_WEB -> TabletWebLayout(
                        viewModel = viewModel,
                        onLoadImage = onLoadImage
                    )
                }
            }

            // Modals
            Modals(viewModel = viewModel, onLoadImage = onLoadImage)
        }
    }
}

@Composable
private fun Modals(viewModel: MeasurementViewModel, onLoadImage: () -> Unit) {
    val state = viewModel.state

    // Handle back button - close topmost modal
    val hasOpenModal = state.showSizeModal || state.showHistoryModal ||
                       state.showSettingsModal || state.showPaywallModal ||
                       state.showFaqModal || state.showSaveSuccessModal ||
                       state.showUnsavedWarningModal || state.showBottomSheet ||
                       state.showEmailAuthModal || state.authState.showProvidersModal

    app.serpwidgets.snakemeasurer.util.BackHandler(enabled = hasOpenModal) {
        when {
            state.showEmailAuthModal -> viewModel.hideEmailAuthModal()
            state.authState.showProvidersModal -> viewModel.hideAuthProvidersModal()
            state.showFaqModal -> viewModel.hideFaqModal()
            state.showPaywallModal -> viewModel.hidePaywallModal()
            state.showUnsavedWarningModal -> viewModel.hideUnsavedWarningModal()
            state.showSaveSuccessModal -> viewModel.hideSaveSuccessModal()
            state.showSizeModal -> viewModel.hideSizeModal()
            state.showHistoryModal -> viewModel.hideHistoryModal()
            state.showSettingsModal -> viewModel.hideSettingsModal()
            state.showBottomSheet -> viewModel.hideBottomSheet()
        }
    }

    // Auto-open size modal when tutorial reaches SET_REFERENCE_SIZE step
    LaunchedEffect(state.helpState.currentStep, state.hasReferenceComplete) {
        if (state.helpState.tutorialActive &&
            state.helpState.currentStep == TutorialStep.SET_REFERENCE_SIZE &&
            state.hasReferenceComplete &&
            !state.showSizeModal
        ) {
            viewModel.showSizeModal()
        }
    }

    if (state.showSizeModal) {
        // Wrap modal for SET_REFERENCE_SIZE tutorial step
        TutorialTargetBox(step = TutorialStep.SET_REFERENCE_SIZE) {
            SizeInputModal(
                currentSize = viewModel.getReferenceLengthInCurrentUnit(),
                currentUnit = state.selectedUnit,
                language = state.currentLanguage,
                onSizeSet = { size, unit ->
                    viewModel.setUnit(unit)
                    viewModel.setReferenceLength(size)
                },
                onDismiss = { viewModel.hideSizeModal() }
            )
        }
    }

    if (state.showHistoryModal) {
        HistoryModal(
            history = state.measurementHistory,
            currentUnit = state.selectedUnit,
            language = state.currentLanguage,
            onDelete = { viewModel.deleteHistoryRecord(it) },
            onLoad = { record -> viewModel.loadMeasurement(record) },
            onDismiss = { viewModel.hideHistoryModal() }
        )
    }

    if (state.showSettingsModal) {
        SettingsModal(
            currentLanguage = state.currentLanguage,
            currentTheme = state.themeMode,
            onLanguageChange = { viewModel.setLanguage(it) },
            onThemeChange = { viewModel.setThemeMode(it) },
            onClearAll = { viewModel.clearAll() },
            onShowTutorial = { viewModel.restartTutorial() },
            onShowFaq = { viewModel.showFaqModal() },
            onOpenPrivacyPolicy = { PlatformInfo.openUrl(getPolicyUrl(state.currentLanguage)) },
            onOpenTerms = { PlatformInfo.openUrl(getTermsUrl(state.currentLanguage)) },
            onOpenAppStore = { PlatformInfo.openUrl(APP_STORE_URL) },
            onOpenGooglePlay = { PlatformInfo.openUrl(GOOGLE_PLAY_URL) },
            onOpenTelegram = { PlatformInfo.openUrl(TELEGRAM_URL) },
            hasPoints = state.referencePoints.isNotEmpty() || state.snakePoints.isNotEmpty(),
            onDismiss = { viewModel.hideSettingsModal() }
        )
    }

    if (state.showFaqModal) {
        FaqModal(
            onDismiss = { viewModel.hideFaqModal() }
        )
    }

    // Tutorial - Welcome Dialog (first launch)
    TutorialWelcomeDialog(
        visible = state.helpState.tutorialActive && state.helpState.currentStep == TutorialStep.WELCOME,
        onStart = { viewModel.startTutorial() },
        onSkip = { viewModel.skipTutorial() }
    )

    // Tutorial - Interactive Spotlight Overlay
    TutorialOverlay(
        visible = state.helpState.tutorialActive,
        currentStep = state.helpState.currentStep,
        onSkip = { viewModel.skipTutorial() },
        onNext = { viewModel.advanceTutorialStep() }
    )

    // Tutorial - Completion Dialog
    TutorialCompletedDialog(
        visible = state.helpState.tutorialActive && state.helpState.currentStep == TutorialStep.COMPLETED,
        onDismiss = { viewModel.dismissTutorialCompleted() }
    )

    if (state.showPaywallModal) {
        PaywallModal(
            remainingMeasurements = state.remainingMeasurements,
            onPurchase = { product ->
                // TODO: Implement actual IAP - for now just simulate purchase
                viewModel.onPurchaseSuccess(product.productId)
            },
            onRestore = {
                // TODO: Implement restore purchases
            },
            onDismiss = { viewModel.hidePaywallModal() }
        )
    }

    // Save Success Modal
    if (state.showSaveSuccessModal) {
        SaveSuccessModal(
            lengthCm = state.lastSavedLengthCm,
            unit = state.selectedUnit,
            language = state.currentLanguage,
            onNewMeasurement = {
                viewModel.startNewMeasurementWithNewImage()
                onLoadImage()
            },
            onViewHistory = {
                viewModel.hideSaveSuccessModal()
                viewModel.showHistoryModal()
            },
            onDismiss = { viewModel.hideSaveSuccessModal() }
        )
    }

    // Unsaved Changes Warning Modal
    if (state.showUnsavedWarningModal) {
        UnsavedWarningModal(
            onSave = {
                viewModel.saveMeasurement()
                viewModel.hideUnsavedWarningModal()
                onLoadImage()
            },
            onDiscard = {
                viewModel.hideUnsavedWarningModal()
                viewModel.startNewMeasurement()
                onLoadImage()
            },
            onCancel = { viewModel.hideUnsavedWarningModal() }
        )
    }

    // Auth Providers Modal (social login selection)
    if (state.authState.showProvidersModal) {
        AuthProvidersModal(
            isLoading = state.authState.isLoading,
            onGoogleClick = {
                viewModel.signInWithGoogle()
            },
            onAppleClick = {
                viewModel.signInWithApple()
            },
            onEmailClick = {
                viewModel.hideAuthProvidersModal()
                viewModel.showEmailAuthModal()
            },
            onDismiss = { viewModel.hideAuthProvidersModal() }
        )
    }

    // Account Modal (profile, sign out, delete)
    if (state.showAccountModal && state.currentUser != null) {
        AccountModal(
            user = state.currentUser!!,
            isLoading = state.authState.isLoading,
            error = state.authState.error,
            onSignOut = { viewModel.signOut() },
            onDeleteAccount = { viewModel.deleteAccount() },
            onClearError = { viewModel.clearAuthError() },
            onDismiss = { viewModel.hideAccountModal() }
        )
    }

    // Email Auth Modal
    if (state.showEmailAuthModal) {
        EmailAuthModal(
            isLoading = state.authState.isLoading,
            error = state.authState.error,
            onSignIn = { email, password ->
                viewModel.signInWithEmail(email, password)
            },
            onCreateAccount = { email, password ->
                viewModel.createAccountWithEmail(email, password)
            },
            onForgotPassword = { email ->
                viewModel.sendPasswordResetEmail(email)
            },
            onClearError = { viewModel.clearAuthError() },
            onDismiss = { viewModel.hideEmailAuthModal() }
        )
    }

    // Bottom Sheet (main menu)
    AppBottomSheet(
        isVisible = state.showBottomSheet,
        onDismiss = { viewModel.hideBottomSheet() },
        isLoggedIn = state.isLoggedIn,
        userName = state.currentUser?.displayName ?: state.currentUser?.email,
        onSignIn = {
            viewModel.hideBottomSheet()
            viewModel.showAuthProvidersModal()
        },
        onSignOut = {
            viewModel.hideBottomSheet()
            viewModel.showAccountModal()
        },
        currentTheme = state.themeMode,
        onThemeChange = { viewModel.setThemeMode(it) },
        currentLanguage = state.currentLanguage,
        onLanguageChange = { viewModel.setLanguage(it) },
        historyCount = state.measurementHistory.records.size,
        onHistoryClick = { viewModel.showHistoryModal() },
        hasPoints = state.referencePoints.isNotEmpty() || state.snakePoints.isNotEmpty(),
        onClearAll = { viewModel.clearAll() },
        onShowTutorial = { viewModel.restartTutorial() },
        onShowFaq = { viewModel.showFaqModal() },
        onOpenPrivacyPolicy = { PlatformInfo.openUrl(getPolicyUrl(state.currentLanguage)) },
        onOpenTerms = { PlatformInfo.openUrl(getTermsUrl(state.currentLanguage)) }
    )
}

// ==================== PORTRAIT PHONE LAYOUT ====================
@Composable
private fun PortraitPhoneLayout(
    viewModel: MeasurementViewModel,
    onLoadImage: () -> Unit
) {
    val state = viewModel.state
    val colors = AppTheme.colors

    // Create state objects for stateless components
    val topHeaderBarState = TopHeaderBarState(
        hasImage = state.imageBitmap != null,
        isViewingHistory = state.isViewingHistory,
        hasReferenceComplete = state.hasReferenceComplete,
        referenceLengthCm = state.referenceLengthCm,
        hasResult = state.hasResult,
        isLoggedIn = state.isLoggedIn,
        userName = state.currentUser?.displayName ?: state.currentUser?.email,
        selectedUnit = state.selectedUnit,
        currentLanguage = state.currentLanguage,
        formattedReferenceLength = "${state.currentLanguage.formatNumber(viewModel.getReferenceLengthInCurrentUnit(), 1)} ${state.selectedUnit.getLocalizedAbbreviation(state.currentLanguage)}",
        formattedResult = "${state.currentLanguage.formatNumber(viewModel.getResultInCurrentUnit(), 1)} ${state.selectedUnit.getLocalizedAbbreviation(state.currentLanguage)}"
    )

    val floatingInstructionState = FloatingInstructionState(
        mode = state.mode,
        referencePointsCount = state.referencePoints.size,
        snakePointsCount = state.snakePoints.size,
        hasReferenceComplete = state.hasReferenceComplete,
        hasReferenceSizeSet = state.referenceLengthCm > 0,
        isViewingHistory = state.isViewingHistory
    )

    val bottomModeBarState = BottomModeBarState(
        mode = state.mode,
        hasReferencePoints = state.referencePoints.isNotEmpty(),
        hasSnakePoints = state.snakePoints.isNotEmpty(),
        hasReferenceSizeSet = state.referenceLengthCm > 0,
        isViewingHistory = state.isViewingHistory
    )

    Column(modifier = Modifier.fillMaxSize()) {
        // Top Header Bar
        if (!state.isFullscreen) {
            TopHeaderBar(
                state = topHeaderBarState,
                onLoadImage = onLoadImage,
                onAction = viewModel::onAction,
                isCompact = true
            )
        }

        // Main Content
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
        ) {
            if (state.imageBitmap == null) {
                UploadPlaceholder(
                    onLoadImage = onLoadImage,
                    modifier = Modifier.align(Alignment.Center)
                )
            } else {
                // Canvas wrapped for tutorial steps (reference/snake points/drag)
                TutorialTargetBox(
                    step = TutorialStep.PLACE_REFERENCE_POINTS,
                    modifier = Modifier.fillMaxSize()
                ) {
                    TutorialTargetBox(
                        step = TutorialStep.PLACE_SNAKE_POINTS,
                        modifier = Modifier.fillMaxSize()
                    ) {
                        TutorialTargetBox(
                            step = TutorialStep.DRAG_POINTS_TIP,
                            modifier = Modifier.fillMaxSize()
                        ) {
                            MeasurementCanvas(
                                viewModel = viewModel,
                                modifier = Modifier.fillMaxSize()
                            )
                        }
                    }
                }

                // Floating instruction (top-left)
                FloatingInstruction(
                    state = floatingInstructionState,
                    onAction = viewModel::onAction,
                    modifier = Modifier
                        .align(Alignment.TopStart)
                        .then(if (state.isFullscreen) Modifier.statusBarsPadding() else Modifier)
                        .padding(Spacing.md)
                        .zIndex(10f)
                )

                // Fullscreen: floating result + save (bottom-left)
                if (state.isFullscreen && state.hasResult) {
                    TutorialTargetBox(
                        step = TutorialStep.SAVE_RESULT,
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .zIndex(10f)
                            .navigationBarsPadding()
                            .padding(Spacing.md)
                    ) {
                        Box(
                            modifier = Modifier
                                .shadow(Spacing.xs, Shapes.large)
                                .clip(Shapes.large)
                                .background(colors.success)
                                .then(
                                    if (!state.isViewingHistory) {
                                        Modifier.clickable { viewModel.onAction(MeasurementAction.SaveMeasurement) }
                                    } else Modifier
                                )
                                .padding(horizontal = ButtonDimens.paddingHorizontalSmall + 2.dp, vertical = ButtonDimens.paddingVerticalSmall + 2.dp)
                        ) {
                            Text(
                                text = if (state.isViewingHistory) {
                                    topHeaderBarState.formattedResult
                                } else {
                                    "${stringResource("save")} ${topHeaderBarState.formattedResult}"
                                },
                                color = Color.White,
                                style = AppTheme.typography.titleSmall
                            )
                        }
                    }
                }

                // Zoom controls (bottom-right) - always same position
                FloatingZoomControls(
                    isFullscreen = state.isFullscreen,
                    showFullscreenButton = true,
                    onAction = viewModel::onAction,
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .zIndex(10f)
                        .navigationBarsPadding()
                        .padding(end = Spacing.md, bottom = Spacing.md)
                )
            }
        }

        // Bottom Mode Bar
        if (state.imageBitmap != null && !state.isFullscreen) {
            BottomModeBar(
                state = bottomModeBarState,
                onAction = viewModel::onAction
            )
        }
    }
}

// ==================== LANDSCAPE PHONE LAYOUT ====================
@Composable
private fun LandscapePhoneLayout(
    viewModel: MeasurementViewModel,
    onLoadImage: () -> Unit
) {
    val state = viewModel.state
    val colors = AppTheme.colors

    // Create state objects for stateless components
    val floatingInstructionState = FloatingInstructionState(
        mode = state.mode,
        referencePointsCount = state.referencePoints.size,
        snakePointsCount = state.snakePoints.size,
        hasReferenceComplete = state.hasReferenceComplete,
        hasReferenceSizeSet = state.referenceLengthCm > 0,
        isViewingHistory = state.isViewingHistory
    )

    val sidePanelState = createSidePanelState(state, viewModel)
    val formattedResult = "${state.currentLanguage.formatNumber(viewModel.getResultInCurrentUnit(), 1)} ${state.selectedUnit.getLocalizedAbbreviation(state.currentLanguage)}"

    Row(modifier = Modifier.fillMaxSize()) {
        // Main Canvas Area
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
        ) {
            if (state.imageBitmap == null) {
                UploadPlaceholder(
                    onLoadImage = onLoadImage,
                    modifier = Modifier.align(Alignment.Center)
                )
            } else {
                // Canvas wrapped for tutorial steps (reference/snake points/drag)
                TutorialTargetBox(
                    step = TutorialStep.PLACE_REFERENCE_POINTS,
                    modifier = Modifier.fillMaxSize()
                ) {
                    TutorialTargetBox(
                        step = TutorialStep.PLACE_SNAKE_POINTS,
                        modifier = Modifier.fillMaxSize()
                    ) {
                        TutorialTargetBox(
                            step = TutorialStep.DRAG_POINTS_TIP,
                            modifier = Modifier.fillMaxSize()
                        ) {
                            MeasurementCanvas(
                                viewModel = viewModel,
                                modifier = Modifier.fillMaxSize()
                            )
                        }
                    }
                }

                // Compact floating instruction at top (always show)
                FloatingInstruction(
                    state = floatingInstructionState,
                    onAction = viewModel::onAction,
                    modifier = Modifier
                        .align(Alignment.TopStart)
                        .statusBarsPadding()
                        .padding(Spacing.md)
                        .zIndex(10f)
                )

                // Fullscreen: floating result + save (bottom-left to avoid overlap with undo)
                if (state.isFullscreen && state.hasResult) {
                    TutorialTargetBox(
                        step = TutorialStep.SAVE_RESULT,
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .zIndex(10f)
                            .navigationBarsPadding()
                            .padding(Spacing.md)
                    ) {
                        Box(
                            modifier = Modifier
                                .shadow(Spacing.xs, Shapes.large)
                                .clip(Shapes.large)
                                .background(colors.success)
                                .then(
                                    if (!state.isViewingHistory) {
                                        Modifier.clickable { viewModel.onAction(MeasurementAction.SaveMeasurement) }
                                    } else Modifier
                                )
                                .padding(horizontal = ButtonDimens.paddingHorizontalSmall + 2.dp, vertical = ButtonDimens.paddingVerticalSmall + 2.dp)
                        ) {
                            Text(
                                text = if (state.isViewingHistory) formattedResult else "${stringResource("save")} $formattedResult",
                                color = Color.White,
                                style = AppTheme.typography.titleSmall
                            )
                        }
                    }
                }

                // Zoom controls (bottom-right) - fixed padding for consistency
                FloatingZoomControls(
                    isFullscreen = state.isFullscreen,
                    showFullscreenButton = true,
                    onAction = viewModel::onAction,
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .zIndex(10f)
                        .navigationBarsPadding()
                        .padding(Spacing.md)
                )
            }
        }

        // Side Panel (hide in fullscreen mode)
        AnimatedVisibility(
            visible = !state.isFullscreen,
            enter = fadeIn() + expandHorizontally(),
            exit = fadeOut() + shrinkHorizontally()
        ) {
            SidePanel(
                state = sidePanelState,
                onLoadImage = onLoadImage,
                onAction = viewModel::onAction,
                isCompact = true
            )
        }
    }
}

