// Helper function to create SidePanelState
@Composable
private fun createSidePanelState(state: app.serpwidgets.snakemeasurer.model.MeasurementState, viewModel: MeasurementViewModel): SidePanelState {
    return SidePanelState(
        hasImage = state.imageBitmap != null,
        isViewingHistory = state.isViewingHistory,
        mode = state.mode,
        referencePointsCount = state.referencePoints.size,
        snakePointsCount = state.snakePoints.size,
        hasReferenceComplete = state.hasReferenceComplete,
        referenceLengthCm = state.referenceLengthCm,
        hasReferenceSizeSet = state.referenceLengthCm > 0,
        hasResult = state.hasResult,
        isLoggedIn = state.isLoggedIn,
        userName = state.currentUser?.displayName ?: state.currentUser?.email,
        themeMode = state.themeMode,
        hasHistoryRecords = state.measurementHistory.records.isNotEmpty(),
        selectedUnit = state.selectedUnit,
        currentLanguage = state.currentLanguage,
        formattedReferenceLength = "${state.currentLanguage.formatNumber(viewModel.getReferenceLengthInCurrentUnit(), 1)}",
        formattedReferenceLengthWithUnit = "${state.currentLanguage.formatNumber(viewModel.getReferenceLengthInCurrentUnit(), 1)} ${state.selectedUnit.getLocalizedAbbreviation(state.currentLanguage)}",
        formattedResult = "${state.currentLanguage.formatNumber(viewModel.getResultInCurrentUnit(), 1)}",
        formattedResultWithUnit = "${state.currentLanguage.formatNumber(viewModel.getResultInCurrentUnit(), 1)} ${state.selectedUnit.getLocalizedAbbreviation(state.currentLanguage)}"
    )
}

@Composable
private fun UploadPlaceholder(
    onLoadImage: () -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors

    // Wrap in TutorialTargetBox for UPLOAD_PHOTO step
    TutorialTargetBox(
        step = TutorialStep.UPLOAD_PHOTO,
        modifier = modifier
    ) {
        Box(
