// ========== Save Success Modal ==========

@Composable
private fun SaveSuccessModal(
    lengthCm: Float,
    unit: app.serpwidgets.snakemeasurer.model.MeasurementUnit,
    language: app.serpwidgets.snakemeasurer.model.Language,
    onNewMeasurement: () -> Unit,
    onViewHistory: () -> Unit,
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors
    val lengthInUnit = unit.fromCentimeters(lengthCm)
    val formattedLength = "${language.formatNumber(lengthInUnit, 1)} ${unit.getLocalizedAbbreviation(language)}"

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.6f))
            .clickable(onClick = onDismiss),
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .widthIn(max = 300.dp)
                .padding(Spacing.xl)
                .clip(Shapes.modal)
                .background(colors.bgSecondary)
                .clickable(enabled = false) {} // Prevent click-through
                .verticalScroll(rememberScrollState())
                .padding(Spacing.xl),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Success icon
            Box(
                modifier = Modifier
                    .size(64.dp)
                    .clip(CircleShape)
                    .background(colors.snake.copy(alpha = 0.2f)),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painter = painterResource(Res.drawable.ic_check),
                    contentDescription = "Success",
                    modifier = Modifier.size(Spacing.xxl),
                    colorFilter = ColorFilter.tint(colors.snake)
                )
            }

            Spacer(modifier = Modifier.height(Spacing.md))

            Text(
                text = stringResource("measurement_saved"),
                color = colors.textPrimary,
                style = AppTheme.typography.displaySmall,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center
            )

            Spacer(modifier = Modifier.height(Spacing.xs))

            Text(
                text = stringResource("saved_length").replace("%s", formattedLength),
                color = colors.snake,
                style = AppTheme.typography.displayMedium,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center
            )

            Spacer(modifier = Modifier.height(Spacing.xl))

            // New Measurement button
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.large)
                    .background(colors.reference)
                    .clickable(onClick = onNewMeasurement)
                    .padding(vertical = ButtonDimens.paddingVerticalLarge),
                contentAlignment = Alignment.Center
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_camera),
                        contentDescription = null,
                        modifier = Modifier.size(18.dp),
                        colorFilter = ColorFilter.tint(Color.White)
                    )
                    Text(
                        text = stringResource("new_measurement"),
                        color = Color.White,
                        style = AppTheme.typography.titleMedium
                    )
                }
            }

            Spacer(modifier = Modifier.height(Spacing.sm))

            // View History button
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.large)
                    .background(colors.bgTertiary)
                    .clickable(onClick = onViewHistory)
                    .padding(vertical = ButtonDimens.paddingVerticalLarge),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("view_in_history"),
                    color = colors.textPrimary,
                    style = AppTheme.typography.labelLarge
                )
            }
        }
    }
}

// ========== Unsaved Warning Modal ==========

@Composable
private fun UnsavedWarningModal(
    onSave: () -> Unit,
    onDiscard: () -> Unit,
    onCancel: () -> Unit
) {
    val colors = AppTheme.colors

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.6f))
            .clickable(onClick = onCancel),
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .widthIn(max = 300.dp)
                .padding(Spacing.xl)
                .clip(Shapes.modal)
                .background(colors.bgSecondary)
                .clickable(enabled = false) {}
                .verticalScroll(rememberScrollState())
                .padding(Spacing.xl),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Warning icon
            Box(
                modifier = Modifier
                    .size(64.dp)
                    .clip(CircleShape)
                    .background(colors.danger.copy(alpha = 0.2f)),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    painter = painterResource(Res.drawable.ic_warning),
                    contentDescription = "Warning",
                    modifier = Modifier.size(Spacing.xxl),
                    colorFilter = ColorFilter.tint(colors.danger)
                )
            }

            Spacer(modifier = Modifier.height(Spacing.md))

            Text(
                text = stringResource("unsaved_changes"),
                color = colors.textPrimary,
                style = AppTheme.typography.displaySmall,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center
            )

            Spacer(modifier = Modifier.height(Spacing.xs))

            Text(
                text = stringResource("unsaved_changes_warning"),
                color = colors.textSecondary,
                style = AppTheme.typography.bodyMedium,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                modifier = Modifier.padding(horizontal = Spacing.xs)
            )

            Spacer(modifier = Modifier.height(Spacing.xl))

            // Save First button (primary action)
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.large)
                    .background(colors.snake)
                    .clickable(onClick = onSave)
                    .padding(vertical = ButtonDimens.paddingVerticalLarge),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("save_first"),
                    color = Color.White,
                    style = AppTheme.typography.titleMedium
                )
            }

            Spacer(modifier = Modifier.height(Spacing.sm))

            // Cancel button (safe action - stay here)
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.large)
                    .background(colors.bgTertiary)
                    .clickable(onClick = onCancel)
                    .padding(vertical = ButtonDimens.paddingVerticalLarge),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("cancel"),
                    color = colors.textPrimary,
                    style = AppTheme.typography.labelLarge
                )
            }

            Spacer(modifier = Modifier.height(Spacing.sm))

            // Discard button (destructive - last position)
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.large)
                    .background(colors.danger.copy(alpha = 0.1f))
                    .clickable(onClick = onDiscard)
                    .padding(vertical = ButtonDimens.paddingVerticalLarge),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("discard"),
                    color = colors.danger,
                    style = AppTheme.typography.labelLarge
                )
            }
        }
    }
}

