@Composable
fun FaqModal(
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors

    // FAQ items
    val faqItems = listOf(
        stringResource("faq_q1") to stringResource("faq_a1"),
        stringResource("faq_q2") to stringResource("faq_a2"),
        stringResource("faq_q3") to stringResource("faq_a3"),
        stringResource("faq_q4") to stringResource("faq_a4"),
        stringResource("faq_q5") to stringResource("faq_a5"),
        stringResource("faq_q6") to stringResource("faq_a6")
    )

    // Backdrop
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.5f))
            .clickable(onClick = onDismiss),
        contentAlignment = Alignment.Center
    ) {
        // Modal content
        Column(
            modifier = Modifier
                .widthIn(max = 500.dp)
                .fillMaxWidth(0.95f)
                .heightIn(max = 550.dp)
                .fillMaxHeight(0.9f)
                .clip(Shapes.modal)
                .background(colors.bgTertiary)
                .clickable(enabled = false) {}
        ) {
            // Header
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(Spacing.lg),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = stringResource("faq"),
                    color = colors.textPrimary,
                    style = AppTheme.typography.headlineMedium
                )

                Box(
                    modifier = Modifier
                        .size(IconButtonDimens.size)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(onClick = onDismiss),
                    contentAlignment = Alignment.Center
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_close),
                        contentDescription = stringResource("close"),
                        modifier = Modifier.size(IconButtonDimens.iconSize),
                        colorFilter = ColorFilter.tint(colors.textPrimary)
                    )
                }
            }

            // FAQ items (scrollable)
            Column(
                modifier = Modifier
                    .weight(1f, fill = false)
                    .verticalScroll(rememberScrollState())
                    .padding(horizontal = Spacing.lg, vertical = Spacing.xs),
                verticalArrangement = Arrangement.spacedBy(Spacing.xs)
            ) {
                faqItems.forEach { (question, answer) ->
                    FaqItem(
                        question = question,
                        answer = answer
                    )
                }
            }

            Spacer(modifier = Modifier.height(Spacing.lg))
        }
    }
}

@Composable
private fun FaqItem(
    question: String,
    answer: String
) {
    val colors = AppTheme.colors
    var isExpanded by remember { mutableStateOf(false) }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .clip(Shapes.medium)
            .background(colors.bgSecondary)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null // Disable ripple that can interfere with text colors on Android
            ) { isExpanded = !isExpanded }
    ) {
        // Question row
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(Spacing.sm),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = question,
                color = colors.textPrimary,
                style = AppTheme.typography.titleMedium,
                modifier = Modifier.weight(1f)
            )

            Image(
                painter = painterResource(
                    if (isExpanded) Res.drawable.ic_arrow_up else Res.drawable.ic_arrow_down
                ),
                contentDescription = if (isExpanded) stringResource("hide") else stringResource("show"),
                modifier = Modifier.size(Spacing.md),
                colorFilter = ColorFilter.tint(colors.textTertiary)
            )
        }

        // Answer (expandable)
        AnimatedVisibility(
            visible = isExpanded,
            enter = expandVertically(),
            exit = shrinkVertically()
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = Spacing.sm, end = Spacing.sm, bottom = Spacing.sm)
            ) {
                Text(
                    text = answer,
                    color = colors.textSecondary,
                    style = AppTheme.typography.bodyMedium
                )
            }
        }
    }
}
