package app.serpwidgets.snakemeasurer.util

import kotlin.math.abs
import kotlin.math.pow
import kotlin.math.roundToLong

/**
 * Multiplatform replacement for sprintf-style formatting.
 * Supports: %s, %d, %.Nf
 */
fun formatFloat(value: Double, decimals: Int): String {
    if (decimals <= 0) return value.roundToLong().toString()
    val factor = 10.0.pow(decimals)
    val rounded = (value * factor).roundToLong()
    val isNegative = rounded < 0
    val absRounded = abs(rounded)
    val intPart = absRounded / factor.toLong()
    val fracPart = absRounded % factor.toLong()
    val fracStr = fracPart.toString().padStart(decimals, '0')
    val prefix = if (isNegative) "-" else ""
    return "$prefix$intPart.$fracStr"
}

fun formatFloat(value: Float, decimals: Int): String = formatFloat(value.toDouble(), decimals)

/**
 * Simple format function that replaces %s, %d, %.Nf placeholders with args.
 */
fun simpleFormat(template: String, vararg args: Any): String {
    var result = StringBuilder()
    var argIndex = 0
    var i = 0
    while (i < template.length) {
        if (template[i] == '%' && i + 1 < template.length) {
            val next = template[i + 1]
            when {
                next == 's' -> {
                    result.append(args.getOrNull(argIndex)?.toString() ?: "")
                    argIndex++
                    i += 2
                }
                next == 'd' -> {
                    val arg = args.getOrNull(argIndex)
                    result.append(
                        when (arg) {
                            is Int -> arg.toString()
                            is Long -> arg.toString()
                            is Float -> arg.toInt().toString()
                            is Double -> arg.toInt().toString()
                            else -> arg?.toString() ?: ""
                        }
                    )
                    argIndex++
                    i += 2
                }
                next == '.' -> {
                    // Parse %.Nf
                    var j = i + 2
                    while (j < template.length && template[j].isDigit()) j++
                    if (j < template.length && template[j] == 'f') {
                        val decimals = template.substring(i + 2, j).toIntOrNull() ?: 1
                        val arg = args.getOrNull(argIndex)
                        val value = when (arg) {
                            is Float -> arg.toDouble()
                            is Double -> arg
                            is Int -> arg.toDouble()
                            is Long -> arg.toDouble()
                            else -> 0.0
                        }
                        result.append(formatFloat(value, decimals))
                        argIndex++
                        i = j + 1
                    } else {
                        result.append('%')
                        i++
                    }
                }
                next == '%' -> {
                    result.append('%')
                    i += 2
                }
                else -> {
                    result.append('%')
                    i++
                }
            }
        } else {
            result.append(template[i])
            i++
        }
    }
    return result.toString()
}
