import snakemeasurer.composeapp.generated.resources.ic_camera

/**
 * Modal for choosing image source (gallery or camera)
 */
@Composable
fun ImageSourcePickerModal(
    onSourceSelected: (ImageSource) -> Unit,
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors
    val cameraAvailable = isCameraAvailable()

    // Backdrop
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.5f))
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null,
                onClick = onDismiss
            ),
        contentAlignment = Alignment.Center
    ) {
        // Modal content
        Column(
            modifier = Modifier
                .widthIn(max = 320.dp)
                .clip(RoundedCornerShape(CornerRadius.lg))
                .background(colors.bgSecondary)
                .clickable(
                    interactionSource = remember { MutableInteractionSource() },
                    indication = null
                ) { /* Prevent click through */ }
                .padding(Spacing.lg),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = stringResource("choose_image_source"),
                style = AppTheme.typography.headlineMedium,
                color = colors.textPrimary
            )

            Spacer(modifier = Modifier.height(Spacing.lg))

            // Gallery option
            SourceOption(
                icon = Res.drawable.ic_gallery,
                label = stringResource("from_gallery"),
                backgroundColor = colors.reference,
                onClick = {
                    onDismiss()
                    onSourceSelected(ImageSource.GALLERY)
                }
            )

            // Camera option
            if (cameraAvailable) {
                Spacer(modifier = Modifier.height(Spacing.sm))
                SourceOption(
                    icon = Res.drawable.ic_camera,
                    label = stringResource("take_photo"),
                    backgroundColor = colors.snake,
                    onClick = {
                        onDismiss()
                        onSourceSelected(ImageSource.CAMERA)
                    }
                )
            }

            Spacer(modifier = Modifier.height(Spacing.md))

            // Cancel button
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(CornerRadius.md))
                    .background(colors.bgTertiary)
                    .clickable(onClick = onDismiss)
                    .padding(vertical = Spacing.md),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("cancel"),
                    style = AppTheme.typography.titleSmall,
                    color = colors.textSecondary
                )
            }
        }
    }
}

@Composable
private fun SourceOption(
    icon: org.jetbrains.compose.resources.DrawableResource,
    label: String,
    backgroundColor: Color,
    onClick: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(CornerRadius.md))
            .background(backgroundColor)
            .clickable(onClick = onClick)
            .padding(vertical = Spacing.md, horizontal = Spacing.lg)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center
        ) {
            Image(
                painter = painterResource(icon),
                contentDescription = null,
                modifier = Modifier.size(24.dp),
                colorFilter = ColorFilter.tint(Color.White)
            )
            Spacer(modifier = Modifier.width(Spacing.sm))
            Text(
                text = label,
                style = AppTheme.typography.titleMedium,
                color = Color.White
            )
        }
    }
}
