package app.serpwidgets.snakemeasurer.util

import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.asSkiaBitmap
import androidx.compose.ui.graphics.toComposeImageBitmap
import org.jetbrains.skia.Bitmap
import org.jetbrains.skia.Canvas
import org.jetbrains.skia.ColorAlphaType
import org.jetbrains.skia.ColorType
import org.jetbrains.skia.Image
import org.jetbrains.skia.ImageInfo
import org.jetbrains.skia.SamplingMode
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

@OptIn(ExperimentalEncodingApi::class)
actual object ImageEncoder {
    actual fun encodeToBase64(image: ImageBitmap): String? {
        return try {
            val skiaBitmap = image.asSkiaBitmap()
            val skiaImage = Image.makeFromBitmap(skiaBitmap)
            val data = skiaImage.encodeToData(org.jetbrains.skia.EncodedImageFormat.JPEG, 80)
            data?.bytes?.let { Base64.encode(it) }
        } catch (e: Exception) {
            null
        }
    }

    actual fun decodeFromBase64(base64: String): ImageBitmap? {
        return try {
            val bytes = Base64.decode(base64)
            val skiaImage = Image.makeFromEncoded(bytes)
            skiaImage.toComposeImageBitmap()
        } catch (e: Exception) {
            null
        }
    }

    actual fun createThumbnail(image: ImageBitmap, maxSize: Int): ImageBitmap {
        return try {
            val skiaBitmap = image.asSkiaBitmap()
            val width = skiaBitmap.width
            val height = skiaBitmap.height

            // If already small enough, return as-is
            if (width <= maxSize && height <= maxSize) {
                return image
            }

            // Calculate new dimensions maintaining aspect ratio
            val scale = minOf(maxSize.toFloat() / width, maxSize.toFloat() / height)
            val newWidth = (width * scale).toInt()
            val newHeight = (height * scale).toInt()

            // Create scaled bitmap
            val srcImage = Image.makeFromBitmap(skiaBitmap)
            val dstInfo = ImageInfo(newWidth, newHeight, ColorType.RGBA_8888, ColorAlphaType.PREMUL)
            val dstBitmap = Bitmap()
            dstBitmap.allocPixels(dstInfo)

            val canvas = Canvas(dstBitmap)
            canvas.drawImageRect(
                srcImage,
                org.jetbrains.skia.Rect.makeWH(width.toFloat(), height.toFloat()),
                org.jetbrains.skia.Rect.makeWH(newWidth.toFloat(), newHeight.toFloat()),
                SamplingMode.LINEAR,
                null,
                true
            )

            Image.makeFromBitmap(dstBitmap).toComposeImageBitmap()
        } catch (e: Exception) {
            image // Return original on error
        }
    }

    actual fun encodeToBase64(image: ImageBitmap, maxSize: Int, quality: Int): String? {
        return try {
            val imageToEncode = if (maxSize > 0) {
                createThumbnail(image, maxSize)
            } else {
                image
            }

            val skiaBitmap = imageToEncode.asSkiaBitmap()
            val skiaImage = Image.makeFromBitmap(skiaBitmap)
            val data = skiaImage.encodeToData(org.jetbrains.skia.EncodedImageFormat.JPEG, quality)
            data?.bytes?.let { Base64.encode(it) }
        } catch (e: Exception) {
            null
        }
    }
}
