package app.serpwidgets.snakemeasurer.ui.components

import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.ColorFilter
import androidx.compose.ui.unit.dp
import app.serpwidgets.snakemeasurer.ui.stringResource
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.ui.theme.Shapes
import app.serpwidgets.snakemeasurer.ui.theme.Spacing
import app.serpwidgets.snakemeasurer.util.PlatformInfo
import org.jetbrains.compose.resources.painterResource
import snakemeasurer.composeapp.generated.resources.*

/**
 * Auth provider button colors
 */
object AuthColors {
    val google = Color(0xFFDB4437)
    val apple = Color(0xFF000000)
    val email = Color(0xFF5C6BC0)
}

/**
 * Social login buttons section
 */
@Composable
fun AuthButtonsSection(
    isLoading: Boolean,
    onGoogleClick: () -> Unit,
    onAppleClick: () -> Unit,
    onEmailClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    Column(
        modifier = modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(Spacing.sm)
    ) {
        // Google
        AuthProviderButton(
            text = stringResource("continue_with_google"),
            backgroundColor = AuthColors.google,
            icon = Res.drawable.ic_google,
            isLoading = isLoading,
            onClick = onGoogleClick
        )

        // Apple (only on iOS and Web - not supported on Android)
        if (!PlatformInfo.isAndroid) {
            AuthProviderButton(
                text = stringResource("continue_with_apple"),
                backgroundColor = AuthColors.apple,
                icon = Res.drawable.ic_apple,
                isLoading = isLoading,
                onClick = onAppleClick
            )
        }

        // Email
        AuthProviderButton(
            text = stringResource("continue_with_email"),
            backgroundColor = AuthColors.email,
            icon = Res.drawable.ic_email,
            isLoading = isLoading,
            onClick = onEmailClick
        )
    }
}

@Composable
private fun AuthProviderButton(
    text: String,
    backgroundColor: Color,
    icon: org.jetbrains.compose.resources.DrawableResource,
    isLoading: Boolean,
    onClick: () -> Unit,
    textColor: Color = Color.White,
    iconTint: Color = Color.White
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(Shapes.medium)
            .background(backgroundColor)
            .clickable(enabled = !isLoading, onClick = onClick)
            .padding(vertical = Spacing.sm, horizontal = Spacing.md)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center
        ) {
            Image(
                painter = painterResource(icon),
                contentDescription = null,
                modifier = Modifier.size(20.dp),
                colorFilter = ColorFilter.tint(iconTint)
            )
            Spacer(modifier = Modifier.width(Spacing.sm))
            Text(
                text = text,
                style = AppTheme.typography.titleSmall,
                color = textColor
            )
        }
    }
}

/**
 * Compact auth buttons for settings
 */
@Composable
fun CompactAuthButtons(
    isLoading: Boolean,
    onGoogleClick: () -> Unit,
    onAppleClick: () -> Unit,
    onEmailClick: () -> Unit,
    modifier: Modifier = Modifier
) {
    Row(
        modifier = modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
    ) {
        CompactAuthButton(
            backgroundColor = AuthColors.google,
            icon = Res.drawable.ic_google,
            contentDescription = "Google",
            isLoading = isLoading,
            onClick = onGoogleClick,
            modifier = Modifier.weight(1f)
        )
        // Apple (only on iOS and Web - not supported on Android)
        if (!PlatformInfo.isAndroid) {
            CompactAuthButton(
                backgroundColor = AuthColors.apple,
                icon = Res.drawable.ic_apple,
                contentDescription = "Apple",
                isLoading = isLoading,
                onClick = onAppleClick,
                modifier = Modifier.weight(1f)
            )
        }
        CompactAuthButton(
            backgroundColor = AuthColors.email,
            icon = Res.drawable.ic_email,
            contentDescription = "Email",
            isLoading = isLoading,
            onClick = onEmailClick,
            modifier = Modifier.weight(1f)
        )
    }
}

@Composable
private fun CompactAuthButton(
    backgroundColor: Color,
    icon: org.jetbrains.compose.resources.DrawableResource,
    contentDescription: String,
    isLoading: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    iconTint: Color = Color.White
) {
    Box(
        modifier = modifier
            .clip(Shapes.medium)
            .background(backgroundColor)
            .clickable(enabled = !isLoading, onClick = onClick)
            .padding(vertical = Spacing.sm),
        contentAlignment = Alignment.Center
    ) {
        if (isLoading) {
            CircularProgressIndicator(
                color = iconTint,
                modifier = Modifier.size(20.dp),
                strokeWidth = 2.dp
            )
        } else {
            Image(
                painter = painterResource(icon),
                contentDescription = contentDescription,
                modifier = Modifier.size(20.dp),
                colorFilter = ColorFilter.tint(iconTint)
            )
        }
    }
}
