package app.serpwidgets.snakemeasurer.util

actual object WebLoginForm {
    actual fun show(
        isCreateMode: Boolean,
        isDark: Boolean,
        onSubmit: (email: String, password: String) -> Unit,
        onCreateAccount: (email: String, password: String) -> Unit,
        onForgotPassword: (email: String) -> Unit,
        onDismiss: () -> Unit
    ) {
        js("""
            window._nativeLoginOnSubmit = function(email, password) { onSubmit(email, password); };
            window._nativeLoginOnCreateAccount = function(email, password) { onCreateAccount(email, password); };
            window._nativeLoginOnForgotPassword = function(email) { onForgotPassword(email); };
            window._nativeLoginOnDismiss = function() { onDismiss(); };
        """)
        val mode = if (isCreateMode) "create" else "signin"
        js("if (typeof window.showNativeLoginForm === 'function') { window.showNativeLoginForm(mode, isDark); }")
    }

    actual fun hide() {
        js("if (typeof window.hideNativeLoginForm === 'function') { window.hideNativeLoginForm(); }")
    }

    actual fun showError(message: String?) {
        if (message != null) {
            js("if (typeof window.showNativeLoginError === 'function') { window.showNativeLoginError(message); }")
        } else {
            js("if (typeof window.hideNativeLoginError === 'function') { window.hideNativeLoginError(); }")
        }
    }

    actual val isAvailable: Boolean = true
}
