package app.serpwidgets.snakemeasurer.ui.components.modals

import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.foundation.text.KeyboardActions
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.OutlinedTextField
import androidx.compose.material3.OutlinedTextFieldDefaults
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.focus.FocusDirection
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalFocusManager
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.text.input.PasswordVisualTransformation
import androidx.compose.ui.autofill.ContentType
import androidx.compose.ui.semantics.contentType
import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import app.serpwidgets.snakemeasurer.ui.stringResource
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.ui.theme.IconButtonDimens
import app.serpwidgets.snakemeasurer.ui.theme.Shapes
import app.serpwidgets.snakemeasurer.ui.theme.Spacing
import androidx.compose.foundation.Image
import androidx.compose.ui.graphics.ColorFilter
import app.serpwidgets.snakemeasurer.util.WebLoginForm
import org.jetbrains.compose.resources.painterResource
import snakemeasurer.composeapp.generated.resources.Res
import snakemeasurer.composeapp.generated.resources.ic_close

@Composable
fun EmailAuthModal(
    isLoading: Boolean,
    error: String?,
    onSignIn: (email: String, password: String) -> Unit,
    onCreateAccount: (email: String, password: String) -> Unit,
    onForgotPassword: (email: String) -> Unit,
    onClearError: () -> Unit,
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors

    // On web/iOS, use native form for browser autofill/password-save support
    if (WebLoginForm.isAvailable) {
        val isDark = colors.isDark
        DisposableEffect(Unit) {
            WebLoginForm.show(
                isCreateMode = false,
                isDark = isDark,
                onSubmit = { email, password -> onSignIn(email, password) },
                onCreateAccount = { email, password -> onCreateAccount(email, password) },
                onForgotPassword = { email -> onForgotPassword(email) },
                onDismiss = onDismiss
            )
            onDispose { WebLoginForm.hide() }
        }
        // Forward error state to native HTML form
        LaunchedEffect(error) {
            WebLoginForm.showError(error)
        }
        return
    }
    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var isCreateMode by remember { mutableStateOf(false) }
    var showForgotPassword by remember { mutableStateOf(false) }
    val focusManager = LocalFocusManager.current

    // Clear error when switching modes
    LaunchedEffect(isCreateMode) {
        onClearError()
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.5f))
            .clickable(onClick = onDismiss),
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .widthIn(max = 400.dp)
                .fillMaxWidth(0.9f)
                .heightIn(max = 500.dp)
                .clip(Shapes.modal)
                .background(colors.bgTertiary)
                .clickable(enabled = false) {}
                .imePadding()
                .verticalScroll(rememberScrollState())
        ) {
            // Header with title and close button
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(Spacing.lg),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = if (showForgotPassword) {
                        stringResource("reset_password")
                    } else if (isCreateMode) {
                        stringResource("create_account")
                    } else {
                        stringResource("sign_in_email")
                    },
                    style = AppTheme.typography.headlineMedium,
                    color = colors.textPrimary
                )

                // Close button
                Box(
                    modifier = Modifier
                        .size(IconButtonDimens.size)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(onClick = onDismiss),
                    contentAlignment = Alignment.Center
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_close),
                        contentDescription = stringResource("close"),
                        modifier = Modifier.size(IconButtonDimens.iconSize),
                        colorFilter = ColorFilter.tint(colors.textPrimary)
                    )
                }
            }

            // Content
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = Spacing.lg)
                    .padding(bottom = Spacing.xl),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(Spacing.md)
            ) {

            // Error message
            if (error != null) {
                Text(
                    text = error,
                    style = AppTheme.typography.bodySmall,
                    color = colors.danger,
                    textAlign = TextAlign.Center
                )
            }

            // Email field
            OutlinedTextField(
                value = email,
                onValueChange = { email = it },
                label = { Text(stringResource("email")) },
                singleLine = true,
                keyboardOptions = KeyboardOptions(
                    keyboardType = KeyboardType.Email,
                    imeAction = if (showForgotPassword) ImeAction.Done else ImeAction.Next
                ),
                keyboardActions = KeyboardActions(
                    onNext = { focusManager.moveFocus(FocusDirection.Down) },
                    onDone = {
                        if (showForgotPassword && email.isNotBlank()) {
                            onForgotPassword(email)
                        }
                    }
                ),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedBorderColor = colors.snake,
                    unfocusedBorderColor = colors.border,
                    focusedLabelColor = colors.snake,
                    unfocusedLabelColor = colors.textTertiary,
                    cursorColor = colors.snake,
                    focusedTextColor = colors.textPrimary,
                    unfocusedTextColor = colors.textPrimary
                ),
                modifier = Modifier
                    .fillMaxWidth()
                    .semantics { contentType = ContentType.Username + ContentType.EmailAddress }
            )

            // Password field (not shown for forgot password)
            if (!showForgotPassword) {
                OutlinedTextField(
                    value = password,
                    onValueChange = { password = it },
                    label = { Text(stringResource("password")) },
                    singleLine = true,
                    visualTransformation = PasswordVisualTransformation(),
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Password,
                        imeAction = ImeAction.Done
                    ),
                    keyboardActions = KeyboardActions(
                        onDone = {
                            if (email.isNotBlank() && password.isNotBlank()) {
                                if (isCreateMode) {
                                    onCreateAccount(email, password)
                                } else {
                                    onSignIn(email, password)
                                }
                            }
                        }
                    ),
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = colors.snake,
                        unfocusedBorderColor = colors.border,
                        focusedLabelColor = colors.snake,
                        unfocusedLabelColor = colors.textTertiary,
                        cursorColor = colors.snake,
                        focusedTextColor = colors.textPrimary,
                        unfocusedTextColor = colors.textPrimary
                    ),
                    modifier = Modifier
                        .fillMaxWidth()
                        .semantics {
                            contentType = if (isCreateMode) ContentType.NewPassword else ContentType.Password
                        }
                )
            }

            // Primary button
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(Shapes.medium)
                    .background(colors.snake)
                    .clickable(enabled = !isLoading) {
                        when {
                            showForgotPassword -> {
                                if (email.isNotBlank()) {
                                    onForgotPassword(email)
                                    showForgotPassword = false
                                }
                            }
                            isCreateMode -> {
                                if (email.isNotBlank() && password.isNotBlank()) {
                                    onCreateAccount(email, password)
                                }
                            }
                            else -> {
                                if (email.isNotBlank() && password.isNotBlank()) {
                                    onSignIn(email, password)
                                }
                            }
                        }
                    }
                    .padding(vertical = 14.dp),
                contentAlignment = Alignment.Center
            ) {
                if (isLoading) {
                    CircularProgressIndicator(
                        color = Color.White,
                        modifier = Modifier.size(20.dp),
                        strokeWidth = 2.dp
                    )
                } else {
                    Text(
                        text = when {
                            showForgotPassword -> stringResource("send_reset_link")
                            isCreateMode -> stringResource("create_account")
                            else -> stringResource("sign_in")
                        },
                        style = AppTheme.typography.titleMedium,
                        color = Color.White
                    )
                }
            }

            // Toggle mode / Forgot password
            if (!showForgotPassword) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Text(
                        text = if (isCreateMode) {
                            stringResource("already_have_account")
                        } else {
                            stringResource("no_account")
                        },
                        style = AppTheme.typography.bodySmall,
                        color = colors.snake,
                        modifier = Modifier.clickable {
                            isCreateMode = !isCreateMode
                            password = ""
                        }
                    )

                    if (!isCreateMode) {
                        Text(
                            text = stringResource("forgot_password"),
                            style = AppTheme.typography.bodySmall,
                            color = colors.textTertiary,
                            modifier = Modifier.clickable {
                                showForgotPassword = true
                            }
                        )
                    }
                }
            } else {
                Text(
                    text = stringResource("back_to_sign_in"),
                    style = AppTheme.typography.bodySmall,
                    color = colors.snake,
                    modifier = Modifier.clickable {
                        showForgotPassword = false
                    }
                )
            }

            }
        }
    }
}
