package app.serpwidgets.snakemeasurer.util

import androidx.compose.runtime.Composable
import androidx.compose.ui.graphics.ImageBitmap

/**
 * Source for image picking
 */
enum class ImageSource {
    GALLERY,
    CAMERA
}

/**
 * Platform-specific image picker
 * Returns a composable that triggers image selection when invoked
 */
@Composable
expect fun rememberImagePicker(
    onImageSelected: (ImageBitmap, String) -> Unit
): () -> Unit

/**
 * Platform-specific image picker with source selection (gallery or camera)
 * Returns a function that takes ImageSource and triggers the appropriate picker
 */
@Composable
expect fun rememberImagePickerWithSource(
    onImageSelected: (ImageBitmap, String) -> Unit
): (ImageSource) -> Unit

/**
 * Check if camera is available on current platform
 */
expect fun isCameraAvailable(): Boolean
