package app.serpwidgets.snakemeasurer.ui.screens.measurement

import androidx.compose.animation.*
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import app.serpwidgets.snakemeasurer.model.MeasurementMode
import app.serpwidgets.snakemeasurer.model.TutorialStep
import app.serpwidgets.snakemeasurer.ui.stringResource
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.ui.theme.ButtonDimens
import app.serpwidgets.snakemeasurer.ui.theme.Shapes
import app.serpwidgets.snakemeasurer.ui.theme.Spacing
import app.serpwidgets.snakemeasurer.ui.tutorial.TutorialTargetBox

/**
 * State needed for BottomModeBar
 */
data class BottomModeBarState(
    val mode: MeasurementMode,
    val hasReferencePoints: Boolean,
    val hasSnakePoints: Boolean,
    val hasReferenceSizeSet: Boolean,
    val isViewingHistory: Boolean
)

/**
 * Bottom mode bar for switching between Reference and Snake modes.
 * Shown in portrait phone layout.
 */
@Composable
fun BottomModeBar(
    state: BottomModeBarState,
    onAction: (MeasurementAction) -> Unit
) {
    val colors = AppTheme.colors

    val hasPoints = when (state.mode) {
        MeasurementMode.REFERENCE -> state.hasReferencePoints
        MeasurementMode.SNAKE -> state.hasSnakePoints
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(colors.bgTertiary)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(72.dp)
                .padding(horizontal = Spacing.md),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
        ) {
            // Reference button
            ModeButton(
                text = stringResource("reference"),
                isActive = state.mode == MeasurementMode.REFERENCE,
                activeColor = colors.reference,
                onClick = { onAction(MeasurementAction.SetMode(MeasurementMode.REFERENCE)) },
                modifier = Modifier.weight(1f)
            )

            // Snake button
            TutorialTargetBox(
                step = TutorialStep.SWITCH_TO_SNAKE,
                modifier = Modifier.weight(1f)
            ) {
                ModeButton(
                    text = stringResource("snake"),
                    isActive = state.mode == MeasurementMode.SNAKE,
                    activeColor = colors.snake,
                    enabled = state.hasReferenceSizeSet,
                    onClick = { onAction(MeasurementAction.SetMode(MeasurementMode.SNAKE)) },
                    modifier = Modifier.fillMaxWidth()
                )
            }

            // Clear button (hidden in view mode)
            AnimatedVisibility(
                visible = hasPoints && !state.isViewingHistory,
                enter = fadeIn() + expandHorizontally(),
                exit = fadeOut() + shrinkHorizontally()
            ) {
                Box(
                    modifier = Modifier
                        .clip(Shapes.large)
                        .background(colors.danger)
                        .clickable { onAction(MeasurementAction.ClearCurrentMode) }
                        .padding(horizontal = ButtonDimens.paddingHorizontalLarge, vertical = ButtonDimens.paddingVerticalMedium)
                ) {
                    Text(
                        text = stringResource("clear"),
                        color = Color.White,
                        style = AppTheme.typography.titleSmall
                    )
                }
            }
        }
        // Bottom safe area for navigation bar / home indicator
        Spacer(modifier = Modifier.navigationBarsPadding())
    }
}
