package app.serpwidgets.snakemeasurer.model

import kotlin.math.pow
import app.serpwidgets.snakemeasurer.util.formatFloat

/**
 * Supported languages in the application
 */
enum class Language(
    val code: String,
    val displayName: String,
    val nativeName: String,
    val flagEmoji: String,
    val decimalSeparator: Char
) {
    ENGLISH("en", "English", "English", "🇬🇧", '.'),
    RUSSIAN("ru", "Russian", "Русский", "🇷🇺", ','),
    SPANISH("es", "Spanish", "Español", "🇪🇸", ','),
    FRENCH("fr", "French", "Français", "🇫🇷", ','),
    GERMAN("de", "German", "Deutsch", "🇩🇪", ','),
    PORTUGUESE("pt", "Portuguese", "Português", "🇵🇹", ','),
    ITALIAN("it", "Italian", "Italiano", "🇮🇹", ','),
    UKRAINIAN("uk", "Ukrainian", "Українська", "🇺🇦", ','),
    DUTCH("nl", "Dutch", "Nederlands", "🇳🇱", ','),
    POLISH("pl", "Polish", "Polski", "🇵🇱", ','),
    ARABIC("ar", "Arabic", "العربية", "🇸🇦", ','),
    JAPANESE("ja", "Japanese", "日本語", "🇯🇵", '.'),
    KOREAN("ko", "Korean", "한국어", "🇰🇷", '.');

    /**
     * Format a number with locale-aware decimal separator
     */
    fun formatNumber(value: Float, decimals: Int = 1): String {
        val factor = 10.0.pow(decimals)
        val rounded = (value * factor).toLong() / factor
        val formatted = if (decimals == 0) {
            rounded.toLong().toString()
        } else {
            formatFloat(rounded, decimals)
        }
        return if (decimalSeparator == ',') {
            formatted.replace('.', ',')
        } else {
            formatted
        }
    }

    companion object {
        fun fromCode(code: String): Language {
            return entries.find { it.code == code } ?: ENGLISH
        }
    }
}
