@Composable
fun CookieConsentBanner(
    onAcceptAll: () -> Unit,
    onRejectNonEssential: () -> Unit,
    onManagePreferences: () -> Unit,
    modifier: Modifier = Modifier
) {
    val colors = AppTheme.colors

    Box(
        modifier = modifier
            .widthIn(max = 500.dp)
            .clip(Shapes.large)
            .background(colors.bgPrimary)
            .border(2.dp, colors.border, Shapes.large)
            .padding(Spacing.md)
    ) {
        Column(
            verticalArrangement = Arrangement.spacedBy(Spacing.sm)
        ) {
            // Title
            Text(
                text = stringResource("cookie_preferences"),
                color = colors.textPrimary,
                style = AppTheme.typography.headlineSmall
            )

            // Description
            Text(
                text = stringResource("cookie_description"),
                color = colors.textSecondary,
                style = AppTheme.typography.bodySmall
            )

            // Buttons
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
            ) {
                CookieButton(
                    text = stringResource("reject"),
                    onClick = onRejectNonEssential,
                    backgroundColor = colors.bgSecondary,
                    textColor = colors.textPrimary,
                    modifier = Modifier.weight(1f)
                )
                CookieButton(
                    text = stringResource("manage"),
                    onClick = onManagePreferences,
                    backgroundColor = colors.accent.copy(alpha = 0.2f),
                    textColor = colors.accent,
                    modifier = Modifier.weight(1f)
                )
                CookieButton(
                    text = stringResource("accept_all"),
                    onClick = onAcceptAll,
                    backgroundColor = colors.accent,
                    textColor = Color.White,
                    modifier = Modifier.weight(1f)
                )
            }
        }
    }
}

@Composable
fun CookiePreferencesDialog(
    currentConsent: CookieConsent,
    onSave: (CookieConsent) -> Unit,
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors
    var analytics by remember { mutableStateOf(currentConsent.analytics) }
    var marketing by remember { mutableStateOf(currentConsent.marketing) }

    Dialog(onDismissRequest = onDismiss) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .clip(Shapes.modal)
                .background(colors.bgPrimary)
                .border(2.dp, colors.border, Shapes.modal)
                .padding(Spacing.xl)
        ) {
            Column(
                verticalArrangement = Arrangement.spacedBy(Spacing.md)
            ) {
                // Title
                Text(
                    text = stringResource("cookie_preferences"),
                    color = colors.accent,
                    style = AppTheme.typography.displaySmall
                )

                // Essential cookies (always enabled)
                CookieOption(
                    title = stringResource("essential_cookies"),
                    description = stringResource("essential_cookies_desc"),
                    enabled = false,
                    isEnabled = true,
                    onToggle = {}
                )

                // Analytics cookies
                CookieOption(
                    title = stringResource("analytics_cookies"),
                    description = stringResource("analytics_cookies_desc"),
                    enabled = true,
                    isEnabled = analytics,
                    onToggle = { analytics = !analytics }
                )

                // Marketing cookies (for future use)
                CookieOption(
                    title = stringResource("marketing_cookies"),
                    description = stringResource("marketing_cookies_desc"),
                    enabled = true,
                    isEnabled = marketing,
                    onToggle = { marketing = !marketing }
                )

                // Buttons
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                ) {
                    CookieButton(
                        text = stringResource("cancel"),
                        onClick = onDismiss,
                        backgroundColor = colors.bgSecondary,
                        textColor = colors.textPrimary,
                        modifier = Modifier.weight(1f)
                    )
                    CookieButton(
                        text = stringResource("save_preferences"),
                        onClick = {
                            val newConsent = CookieConsent(
                                essential = true,
                                analytics = analytics,
                                marketing = marketing,
                                timestamp = PlatformInfo.currentTimeMillis(),
                                hasResponded = true
                            )
                            onSave(newConsent)
                        },
                        backgroundColor = colors.accent,
                        textColor = Color.White,
                        modifier = Modifier.weight(1f)
                    )
                }
            }
        }
    }
}

@Composable
private fun CookieOption(
    title: String,
    description: String,
    enabled: Boolean,
    isEnabled: Boolean,
    onToggle: () -> Unit
) {
    val colors = AppTheme.colors

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .clip(Shapes.small)
            .background(colors.bgSecondary)
            .padding(Spacing.sm),
        verticalArrangement = Arrangement.spacedBy(Spacing.xxs)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = title,
                color = colors.textPrimary,
                style = AppTheme.typography.titleMedium,
                modifier = Modifier.weight(1f)
            )

            // Toggle switch
            ToggleSwitch(
                checked = isEnabled,
                onCheckedChange = { if (enabled) onToggle() },
                enabled = enabled
            )
        }

        Text(
            text = description,
            color = colors.textSecondary,
            style = AppTheme.typography.caption
        )
    }
}

@Composable
private fun ToggleSwitch(
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    enabled: Boolean = true
) {
    val colors = AppTheme.colors
    val thumbOffset by animateFloatAsState(
        targetValue = if (checked) 1f else 0f,
        label = "thumb_offset"
    )

    val trackColor = when {
        !enabled -> colors.bgTertiary
        checked -> colors.accent
        else -> colors.bgTertiary
    }

    val thumbColor = when {
        !enabled -> colors.textTertiary
        checked -> Color.White
        else -> colors.textSecondary
    }

    Box(
        modifier = Modifier
            .width(48.dp)
            .height(28.dp)
            .clip(RoundedCornerShape(Spacing.sm + 2.dp))
            .background(trackColor)
            .then(
                if (enabled) Modifier.clickable { onCheckedChange(!checked) }
                else Modifier
            )
            .padding(2.dp)
    ) {
        Box(
            modifier = Modifier
                .size(24.dp)
                .offset(x = (20.dp * thumbOffset))
                .clip(CircleShape)
                .background(thumbColor)
        )
    }
}

@Composable
private fun CookieButton(
    text: String,
    onClick: () -> Unit,
    backgroundColor: Color,
    textColor: Color,
    modifier: Modifier = Modifier
) {
    Box(
        modifier = modifier
            .clip(Shapes.small)
            .background(backgroundColor)
            .clickable(onClick = onClick)
            .padding(horizontal = Spacing.sm, vertical = Spacing.xs),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = text,
            color = textColor,
            style = AppTheme.typography.labelMedium
        )
    }
}
