package app.serpwidgets.snakemeasurer.util

import app.serpwidgets.snakemeasurer.model.Language
import app.serpwidgets.snakemeasurer.resources.StringsRepository

/**
 * Maps raw Firebase Auth error messages to localized, human-readable strings.
 * Firebase JS SDK errors contain codes like "auth/wrong-password" in the message.
 */
object AuthErrorMapper {

    private val codeToStringKey = mapOf(
        "auth/invalid-email" to "auth_error_invalid_email",
        "auth/wrong-password" to "auth_error_wrong_password",
        "auth/user-not-found" to "auth_error_user_not_found",
        "auth/email-already-in-use" to "auth_error_email_in_use",
        "auth/email-already-exists" to "auth_error_email_in_use",
        "auth/weak-password" to "auth_error_weak_password",
        "auth/user-disabled" to "auth_error_user_disabled",
        "auth/too-many-requests" to "auth_error_too_many_requests",
        "auth/quota-exceeded" to "auth_error_too_many_requests",
        "auth/network-request-failed" to "auth_error_network",
        "auth/invalid-credential" to "auth_error_invalid_credential",
        "auth/invalid-password" to "auth_error_wrong_password",
        "auth/requires-recent-login" to "auth_error_requires_recent_login",
    )

    /**
     * Extracts a Firebase error code from a raw error message and returns
     * a localized user-friendly string. Falls back to generic error.
     */
    fun mapError(rawMessage: String, language: Language): String {
        for ((code, stringKey) in codeToStringKey) {
            if (rawMessage.contains(code, ignoreCase = true)) {
                return StringsRepository.getString(stringKey, language)
            }
        }
        return StringsRepository.getString("auth_error_generic", language)
    }
}
