package app.serpwidgets.snakemeasurer.model

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.ImageBitmap
import app.serpwidgets.snakemeasurer.ui.theme.ThemeMode

/**
 * Represents the current state of measurement
 */
data class MeasurementState(
    // Image
    val imageBitmap: ImageBitmap? = null,
    val imageUri: String? = null,

    // Points
    val referencePoints: List<MeasurementPoint> = emptyList(),
    val snakePoints: List<MeasurementPoint> = emptyList(),
    val selectedPointId: String? = null,

    // Measurement
    val referenceLengthCm: Float = 0f,
    val calculatedSnakeLengthCm: Float = 0f,
    val selectedUnit: MeasurementUnit = MeasurementUnit.CENTIMETERS,

    // Mode
    val mode: MeasurementMode = MeasurementMode.REFERENCE,

    // Zoom & Pan
    val zoomLevel: Float = 1f,
    val panOffset: Offset = Offset.Zero,
    val minZoom: Float = 0.5f,
    val maxZoom: Float = 5.0f,

    // UI State
    val themeMode: ThemeMode = ThemeMode.SYSTEM,
    val showSizeModal: Boolean = false,
    val showHistoryModal: Boolean = false,
    val showSettingsModal: Boolean = false,
    val showPaywallModal: Boolean = false,
    val showFaqModal: Boolean = false,
    val showUnsavedWarningModal: Boolean = false, // Warning when losing unsaved data
    val showSaveSuccessModal: Boolean = false, // Success message after save
    val showBottomSheet: Boolean = false, // Main menu bottom sheet
    val isFullscreen: Boolean = false,
    val isViewingHistory: Boolean = false, // Read-only mode when viewing saved measurement
    val lastSavedLengthCm: Float = 0f, // For showing in success modal

    // Data
    val measurementHistory: MeasurementHistory = MeasurementHistory(),
    val currentLanguage: Language = Language.ENGLISH,

    // Cookie consent (web only)
    val cookieConsent: CookieConsent? = null,
    val showCookieBanner: Boolean = false,

    // Premium / Subscription
    val subscriptionState: SubscriptionState = SubscriptionState(),
    val usageTracker: UsageTracker = UsageTracker(),

    // Help / Tutorial (state is in helpState)
    val helpState: HelpState = HelpState(),

    // Undo stack
    val undoStack: List<UndoAction> = emptyList(),

    // Auth
    val authState: AuthState = AuthState(),
    val showEmailAuthModal: Boolean = false,
    val showAccountModal: Boolean = false
) {
    // Auth helpers
    val isLoggedIn: Boolean
        get() = authState.isLoggedIn

    val currentUser: AuthUser?
        get() = authState.user
    val canUndo: Boolean
        get() = undoStack.isNotEmpty()
    val hasReferenceComplete: Boolean
        get() = referencePoints.size == 2

    val hasReferenceSizeSet: Boolean
        get() = hasReferenceComplete && referenceLengthCm > 0

    val hasResult: Boolean
        get() = hasReferenceSizeSet && snakePoints.size >= 2 && calculatedSnakeLengthCm > 0

    val canAddSnakePoints: Boolean
        get() = hasReferenceSizeSet

    // Premium helpers
    val isPremium: Boolean
        get() = subscriptionState.isPremium

    val canMeasure: Boolean
        get() = isPremium || usageTracker.canMeasure()

    val remainingMeasurements: Int
        get() = if (isPremium) Int.MAX_VALUE else usageTracker.remainingMeasurements()

    val historyLimit: Int
        get() = if (isPremium) PremiumFeatures.PREMIUM_HISTORY_UNLIMITED else PremiumFeatures.FREE_HISTORY_LIMIT

    // Check if there are unsaved changes worth warning about
    val hasUnsavedChanges: Boolean
        get() = hasResult && !isViewingHistory
}

enum class MeasurementMode {
    REFERENCE,
    SNAKE
}
