package app.serpwidgets.snakemeasurer.ui.screens.measurement

import app.serpwidgets.snakemeasurer.model.MeasurementMode
import app.serpwidgets.snakemeasurer.model.MeasurementUnit
import app.serpwidgets.snakemeasurer.model.Language
import app.serpwidgets.snakemeasurer.ui.theme.ThemeMode

/**
 * All user actions that can be performed on the measurement screen.
 * Used to decouple UI components from ViewModel.
 */
sealed class MeasurementAction {
    // ========== Mode Actions ==========
    data class SetMode(val mode: MeasurementMode) : MeasurementAction()
    object ClearCurrentMode : MeasurementAction()
    object UndoLastPoint : MeasurementAction()

    // ========== Measurement Actions ==========
    object SaveMeasurement : MeasurementAction()
    object StartNewMeasurement : MeasurementAction()
    object StartNewMeasurementWithNewImage : MeasurementAction()

    // ========== Reference Size ==========
    object ShowSizeModal : MeasurementAction()
    data class SetReferenceLength(val lengthCm: Float) : MeasurementAction()

    // ========== Zoom/Fullscreen ==========
    object ZoomIn : MeasurementAction()
    object ZoomOut : MeasurementAction()
    object ToggleFullscreen : MeasurementAction()

    // ========== History ==========
    object ShowHistoryModal : MeasurementAction()
    object HideHistoryModal : MeasurementAction()
    data class LoadMeasurement(val recordId: String) : MeasurementAction()
    data class DeleteHistoryRecord(val recordId: String) : MeasurementAction()

    // ========== Settings ==========
    object ShowSettingsModal : MeasurementAction()
    object HideSettingsModal : MeasurementAction()
    data class SetLanguage(val language: Language) : MeasurementAction()
    data class SetThemeMode(val mode: ThemeMode) : MeasurementAction()
    data class SetUnit(val unit: MeasurementUnit) : MeasurementAction()
    object CycleTheme : MeasurementAction()
    object ClearAll : MeasurementAction()
    object RestartTutorial : MeasurementAction()

    // ========== FAQ ==========
    object ShowFaqModal : MeasurementAction()
    object HideFaqModal : MeasurementAction()

    // ========== Paywall ==========
    object ShowPaywallModal : MeasurementAction()
    object HidePaywallModal : MeasurementAction()
    data class OnPurchaseSuccess(val productId: String) : MeasurementAction()

    // ========== Save Success Modal ==========
    object ShowSaveSuccessModal : MeasurementAction()
    object HideSaveSuccessModal : MeasurementAction()

    // ========== Unsaved Warning Modal ==========
    object ShowUnsavedWarningModal : MeasurementAction()
    object HideUnsavedWarningModal : MeasurementAction()

    // ========== Bottom Sheet ==========
    object ShowBottomSheet : MeasurementAction()
    object HideBottomSheet : MeasurementAction()

    // ========== Auth ==========
    object ShowAuthProvidersModal : MeasurementAction()
    object HideAuthProvidersModal : MeasurementAction()
    object ShowEmailAuthModal : MeasurementAction()
    object HideEmailAuthModal : MeasurementAction()
    object ShowAccountModal : MeasurementAction()
    object HideAccountModal : MeasurementAction()
    object SignInWithGoogle : MeasurementAction()
    object SignInWithApple : MeasurementAction()
    object SignInWithFacebook : MeasurementAction()
    data class SignInWithEmail(val email: String, val password: String) : MeasurementAction()
    data class CreateAccountWithEmail(val email: String, val password: String) : MeasurementAction()
    data class SendPasswordResetEmail(val email: String) : MeasurementAction()
    object SignOut : MeasurementAction()
    object DeleteAccount : MeasurementAction()
    object ClearAuthError : MeasurementAction()

    // ========== Tutorial ==========
    object StartTutorial : MeasurementAction()
    object SkipTutorial : MeasurementAction()
    object AdvanceTutorialStep : MeasurementAction()
    object DismissTutorialCompleted : MeasurementAction()
}
