package app.serpwidgets.snakemeasurer.ui.components.modals

import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.Text
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.ColorFilter
import androidx.compose.ui.unit.dp
import app.serpwidgets.snakemeasurer.model.AuthProvider
import app.serpwidgets.snakemeasurer.model.AuthUser
import app.serpwidgets.snakemeasurer.ui.stringResource
import app.serpwidgets.snakemeasurer.ui.theme.AppTheme
import app.serpwidgets.snakemeasurer.ui.theme.IconButtonDimens
import app.serpwidgets.snakemeasurer.ui.theme.Shapes
import app.serpwidgets.snakemeasurer.ui.theme.Spacing
import org.jetbrains.compose.resources.painterResource
import snakemeasurer.composeapp.generated.resources.Res
import snakemeasurer.composeapp.generated.resources.ic_close

@Composable
fun AccountModal(
    user: AuthUser,
    isLoading: Boolean = false,
    error: String? = null,
    onSignOut: () -> Unit,
    onDeleteAccount: () -> Unit,
    onClearError: () -> Unit = {},
    onDismiss: () -> Unit
) {
    val colors = AppTheme.colors
    var showDeleteConfirm by remember { mutableStateOf(false) }

    // Clear error when toggling delete confirm
    LaunchedEffect(showDeleteConfirm) {
        onClearError()
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black.copy(alpha = 0.5f))
            .clickable(onClick = onDismiss),
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .widthIn(max = 400.dp)
                .fillMaxWidth(0.9f)
                .heightIn(max = 500.dp)
                .fillMaxHeight(0.9f)
                .clip(Shapes.modal)
                .background(colors.bgTertiary)
                .clickable(enabled = false) {}
                .verticalScroll(rememberScrollState()),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(Spacing.lg),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = stringResource("account"),
                    style = AppTheme.typography.headlineMedium,
                    color = colors.textPrimary
                )
                Box(
                    modifier = Modifier
                        .size(IconButtonDimens.size)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(onClick = onDismiss),
                    contentAlignment = Alignment.Center
                ) {
                    Image(
                        painter = painterResource(Res.drawable.ic_close),
                        contentDescription = stringResource("close"),
                        modifier = Modifier.size(IconButtonDimens.iconSize),
                        colorFilter = ColorFilter.tint(colors.textPrimary)
                    )
                }
            }

            // Avatar
            Box(
                modifier = Modifier
                    .size(72.dp)
                    .clip(CircleShape)
                    .background(colors.snake),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = (user.displayName ?: user.email ?: "?").take(1).uppercase(),
                    color = Color.White,
                    style = AppTheme.typography.displayLarge
                )
            }

            Spacer(modifier = Modifier.height(Spacing.md))

            // Display name
            if (user.displayName != null) {
                Text(
                    text = user.displayName,
                    style = AppTheme.typography.headlineSmall,
                    color = colors.textPrimary
                )
                Spacer(modifier = Modifier.height(Spacing.xxs))
            }

            // Email
            if (user.email != null) {
                Text(
                    text = user.email,
                    style = AppTheme.typography.bodyMedium,
                    color = colors.textSecondary
                )
            }

            // Provider badge
            val providerLabel = when (user.provider) {
                AuthProvider.GOOGLE -> "Google"
                AuthProvider.APPLE -> "Apple"
                AuthProvider.FACEBOOK -> "Facebook"
                else -> "Email"
            }
            Spacer(modifier = Modifier.height(Spacing.xs))
            Box(
                modifier = Modifier
                    .clip(Shapes.small)
                    .background(colors.bgSecondary)
                    .padding(horizontal = Spacing.sm, vertical = Spacing.xxs)
            ) {
                Text(
                    text = providerLabel,
                    style = AppTheme.typography.labelMedium,
                    color = colors.textTertiary
                )
            }

            Spacer(modifier = Modifier.height(Spacing.xl))

            // Sign Out button
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = Spacing.lg)
                    .clip(Shapes.medium)
                    .background(colors.snake)
                    .clickable(enabled = !isLoading) {
                        onSignOut()
                        onDismiss()
                    }
                    .padding(vertical = Spacing.md),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = stringResource("sign_out"),
                    style = AppTheme.typography.titleMedium,
                    color = Color.White
                )
            }

            Spacer(modifier = Modifier.height(Spacing.sm))

            // Delete account
            if (!showDeleteConfirm) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = Spacing.lg)
                        .clip(Shapes.medium)
                        .background(colors.bgSecondary)
                        .clickable(enabled = !isLoading) { showDeleteConfirm = true }
                        .padding(vertical = Spacing.md),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = stringResource("delete_account"),
                        style = AppTheme.typography.titleMedium,
                        color = colors.danger
                    )
                }
            } else {
                // Error message
                if (error != null) {
                    Text(
                        text = error,
                        style = AppTheme.typography.bodySmall,
                        color = colors.danger,
                        modifier = Modifier.padding(horizontal = Spacing.lg)
                    )
                    Spacer(modifier = Modifier.height(Spacing.xs))
                }

                // Confirmation
                Text(
                    text = stringResource("delete_account_confirm"),
                    style = AppTheme.typography.bodySmall,
                    color = colors.textSecondary,
                    modifier = Modifier.padding(horizontal = Spacing.lg)
                )
                Spacer(modifier = Modifier.height(Spacing.sm))
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = Spacing.lg),
                    horizontalArrangement = Arrangement.spacedBy(Spacing.sm)
                ) {
                    // Cancel
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .height(48.dp)
                            .clip(Shapes.medium)
                            .background(colors.bgSecondary)
                            .clickable(enabled = !isLoading) { showDeleteConfirm = false },
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = stringResource("cancel"),
                            style = AppTheme.typography.titleMedium,
                            color = colors.textPrimary
                        )
                    }
                    // Confirm delete
                    Box(
                        modifier = Modifier
                            .weight(1f)
                            .height(48.dp)
                            .clip(Shapes.medium)
                            .background(colors.danger)
                            .clickable(enabled = !isLoading) {
                                onDeleteAccount()
                            },
                        contentAlignment = Alignment.Center
                    ) {
                        if (isLoading) {
                            CircularProgressIndicator(
                                color = Color.White,
                                modifier = Modifier.size(20.dp),
                                strokeWidth = 2.dp
                            )
                        } else {
                            Text(
                                text = stringResource("delete_account"),
                                style = AppTheme.typography.titleMedium,
                                color = Color.White
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(Spacing.xl))
        }
    }
}
