package app.serpwidgets.snakemeasurer.model

import kotlinx.serialization.Serializable
import app.serpwidgets.snakemeasurer.util.formatFloat

/**
 * Represents different measurement units supported by the application
 */
@Serializable
enum class MeasurementUnit(
    val abbreviation: String,
    val displayName: String,
    val cmMultiplier: Float // How many cm in one unit
) {
    CENTIMETERS("cm", "Centimeters", 1f),
    MILLIMETERS("mm", "Millimeters", 0.1f),
    METERS("m", "Meters", 100f),
    INCHES("in", "Inches", 2.54f),
    FEET("ft", "Feet", 30.48f);

    /**
     * Get localized abbreviation based on language
     */
    fun getLocalizedAbbreviation(language: Language?): String {
        if (language == null || language == Language.ENGLISH) return abbreviation
        return when (this) {
            CENTIMETERS -> when (language) {
                Language.RUSSIAN -> "см"
                Language.GERMAN -> "cm"
                else -> "cm"
            }
            MILLIMETERS -> when (language) {
                Language.RUSSIAN -> "мм"
                Language.GERMAN -> "mm"
                else -> "mm"
            }
            METERS -> when (language) {
                Language.RUSSIAN -> "м"
                Language.GERMAN -> "m"
                else -> "m"
            }
            INCHES -> when (language) {
                Language.RUSSIAN -> "дюйм"
                Language.SPANISH -> "pulg"
                Language.FRENCH -> "po"
                Language.GERMAN -> "Zoll"
                Language.PORTUGUESE -> "pol"
                Language.ITALIAN -> "poll"
                else -> "in"
            }
            FEET -> when (language) {
                Language.RUSSIAN -> "фут"
                Language.SPANISH -> "pie"
                Language.FRENCH -> "pi"
                Language.GERMAN -> "Fuß"
                Language.PORTUGUESE -> "pé"
                Language.ITALIAN -> "piede"
                else -> "ft"
            }
        }
    }

    /**
     * Convert from this unit to centimeters
     */
    fun toCentimeters(value: Float): Float {
        return value * cmMultiplier
    }

    /**
     * Convert from centimeters to this unit
     */
    fun fromCentimeters(valueCm: Float): Float {
        return valueCm / cmMultiplier
    }

    /**
     * Format a value in this unit for display
     */
    fun format(value: Float, decimals: Int = 2): String {
        return formatFloat(value, decimals)
    }

    /**
     * Format a value with unit abbreviation
     */
    fun formatWithUnit(value: Float, decimals: Int = 2): String {
        return "${format(value, decimals)} $abbreviation"
    }

    /**
     * Format a value with localized unit abbreviation
     */
    fun formatWithUnit(value: Float, language: Language?, decimals: Int = 2): String {
        return "${format(value, decimals)} ${getLocalizedAbbreviation(language)}"
    }

    /**
     * Format a value compactly - auto-convert to larger units if needed
     * e.g., 1500 m -> "1.5 km", 2500 mm -> "2.5 m"
     */
    fun formatCompact(value: Float, language: Language? = null): String {
        // Get localized unit abbreviations
        val cm = CENTIMETERS.getLocalizedAbbreviation(language)
        val mm = MILLIMETERS.getLocalizedAbbreviation(language)
        val m = METERS.getLocalizedAbbreviation(language)
        val inches = INCHES.getLocalizedAbbreviation(language)
        val ft = FEET.getLocalizedAbbreviation(language)
        // km and mi stay the same across languages
        val km = if (language == Language.RUSSIAN) "км" else "km"
        val mi = if (language == Language.RUSSIAN) "миля" else "mi"

        val num = { v: Float, unit: String ->
            val formatted = formatFloat(v, 1)
            val localized = if (language?.decimalSeparator == ',') formatted.replace('.', ',') else formatted
            "$localized $unit"
        }
        val numInt = { v: Float, unit: String ->
            val formatted = formatFloat(v, 0)
            "$formatted $unit"
        }

        return when (this) {
            METERS -> when {
                value >= 1_000_000 -> num(value / 1_000_000, "Mm")
                value >= 1_000 -> num(value / 1_000, km)
                value >= 1 -> num(value, m)
                else -> numInt(value * 100, cm)
            }
            CENTIMETERS -> when {
                value >= 100_000 -> num(value / 100_000, km)
                value >= 100 -> num(value / 100, m)
                else -> num(value, cm)
            }
            MILLIMETERS -> when {
                value >= 1_000_000 -> num(value / 1_000_000, km)
                value >= 1_000 -> num(value / 1_000, m)
                value >= 10 -> num(value / 10, cm)
                else -> num(value, mm)
            }
            INCHES -> when {
                value >= 63360 -> num(value / 63360, mi)
                value >= 12 -> num(value / 12, ft)
                else -> num(value, inches)
            }
            FEET -> when {
                value >= 5280 -> num(value / 5280, mi)
                value >= 1 -> num(value, ft)
                else -> num(value * 12, inches)
            }
        }
    }
}
