@Composable
fun AppBottomSheet(
    isVisible: Boolean,
    onDismiss: () -> Unit,
    // Auth
    isLoggedIn: Boolean = false,
    userName: String? = null,
    onSignIn: () -> Unit = {},
    onSignOut: () -> Unit = {},
    // Theme
    currentTheme: ThemeMode,
    onThemeChange: (ThemeMode) -> Unit,
    // Language
    currentLanguage: Language,
    onLanguageChange: (Language) -> Unit,
    // History
    historyCount: Int = 0,
    onHistoryClick: () -> Unit,
    // Actions
    hasPoints: Boolean = false,
    onClearAll: () -> Unit,
    // Help & Support
    onShowTutorial: () -> Unit = {},
    onShowFaq: () -> Unit = {},
    onOpenPrivacyPolicy: () -> Unit = {},
    onOpenTerms: () -> Unit = {}
) {
    val colors = AppTheme.colors

    // Backdrop
    AnimatedVisibility(
        visible = isVisible,
        enter = androidx.compose.animation.fadeIn(tween(200)),
        exit = androidx.compose.animation.fadeOut(tween(200))
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(Color.Black.copy(alpha = 0.5f))
                .clickable(onClick = onDismiss)
        )
    }

    // Bottom Sheet
    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = Alignment.BottomCenter
    ) {
        AnimatedVisibility(
            visible = isVisible,
            enter = slideInVertically(
                initialOffsetY = { it },
                animationSpec = tween(300)
            ),
            exit = slideOutVertically(
                targetOffsetY = { it },
                animationSpec = tween(300)
            )
        ) {
            var dragOffset by remember { mutableStateOf(0f) }

            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(topStart = Spacing.xl, topEnd = Spacing.xl))
                    .background(colors.bgSecondary)
                    .windowInsetsPadding(WindowInsets.safeDrawing)
                    .pointerInput(Unit) {
                        detectVerticalDragGestures(
                            onDragEnd = {
                                if (dragOffset > 100) {
                                    onDismiss()
                                }
                                dragOffset = 0f
                            },
                            onVerticalDrag = { _, dragAmount ->
                                if (dragAmount > 0) {
                                    dragOffset += dragAmount
                                }
                            }
                        )
                    }
                    .padding(top = Spacing.sm)
            ) {
                // Header with handle and close button
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = Spacing.md)
                ) {
                    // Handle bar (centered)
                    Box(
                        modifier = Modifier
                            .align(Alignment.Center)
                            .width(40.dp)
                            .height(Spacing.xxs)
                            .clip(RoundedCornerShape(Spacing.xxs / 2))
                            .background(colors.border)
                    )

                    // Close button (right)
                    Box(
                        modifier = Modifier
                            .align(Alignment.CenterEnd)
                            .size(IconButtonDimens.size)
                            .clip(Shapes.medium)
                            .background(colors.bgTertiary)
                            .clickable(onClick = onDismiss),
                        contentAlignment = Alignment.Center
                    ) {
                        Image(
                            painter = painterResource(Res.drawable.ic_close),
                            contentDescription = stringResource("close"),
                            modifier = Modifier.size(IconButtonDimens.iconSize),
                            colorFilter = ColorFilter.tint(colors.textPrimary)
                        )
                    }
                }

                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 450.dp) // Reduced for landscape compatibility
                        .verticalScroll(rememberScrollState())
                        .padding(Spacing.lg),
                    verticalArrangement = Arrangement.spacedBy(Spacing.md)
                ) {
                    // Auth Section - only show when logged in (login is in header)
                    if (isLoggedIn) {
                        AuthSection(
                            isLoggedIn = isLoggedIn,
                            userName = userName,
                            onSignIn = onSignIn,
                            onSignOut = onSignOut
                        )
                        Divider()
                    }

                    // Theme
                    ThemeSection(
                        currentTheme = currentTheme,
                        onThemeChange = onThemeChange
                    )

                    // Language
                    LanguageSection(
                        currentLanguage = currentLanguage,
                        onLanguageChange = onLanguageChange
                    )

                    Divider()

                    // History
                    MenuRow(
                        icon = Res.drawable.ic_history,
                        title = stringResource("history_title"),
                        subtitle = if (historyCount > 0) "$historyCount" else null,
                        onClick = {
                            onHistoryClick()
                            onDismiss()
                        }
                    )

                    Divider()

                    // Help & Support section
                    // Tutorial
                    MenuRow(
                        icon = Res.drawable.ic_help,
                        title = stringResource("show_tutorial"),
                        onClick = {
                            onShowTutorial()
                            onDismiss()
                        }
                    )

                    // FAQ
                    MenuRow(
                        icon = Res.drawable.ic_help,
                        title = stringResource("faq"),
                        onClick = {
                            onShowFaq()
                            onDismiss()
                        }
                    )

                    // Privacy Policy
                    MenuRow(
                        icon = Res.drawable.ic_chevron_right,
                        title = stringResource("privacy_policy"),
                        onClick = {
                            onOpenPrivacyPolicy()
                            onDismiss()
                        }
                    )

                    // Terms of Service
                    MenuRow(
                        icon = Res.drawable.ic_chevron_right,
                        title = stringResource("terms_of_service"),
                        onClick = {
                            onOpenTerms()
                            onDismiss()
                        }
                    )

                    // Bottom padding for content
                    Spacer(modifier = Modifier.height(Spacing.md))
                }
            }
        }
    }
}

@Composable
private fun AuthSection(
    isLoggedIn: Boolean,
    userName: String?,
    onSignIn: () -> Unit,
    onSignOut: () -> Unit
) {
    val colors = AppTheme.colors

    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(Spacing.sm)
    ) {
        // Avatar placeholder
        Box(
            modifier = Modifier
                .size(IconButtonDimens.sizeLarge)
                .clip(CircleShape)
                .background(colors.bgTertiary),
            contentAlignment = Alignment.Center
        ) {
            if (isLoggedIn && userName != null) {
                Text(
                    text = userName.take(1).uppercase(),
                    color = colors.textPrimary,
                    style = AppTheme.typography.displaySmall
                )
            } else {
                Image(
                    painter = painterResource(Res.drawable.ic_settings),
                    contentDescription = stringResource("settings"),
                    modifier = Modifier.size(IconButtonDimens.iconSizeLarge),
                    colorFilter = ColorFilter.tint(colors.textTertiary)
                )
            }
        }

        Column(modifier = Modifier.weight(1f)) {
            if (isLoggedIn && userName != null) {
                Text(
                    text = userName,
                    color = colors.textPrimary,
                    style = AppTheme.typography.headlineSmall
                )
            } else {
                Text(
                    text = stringResource("settings"),
                    color = colors.textPrimary,
                    style = AppTheme.typography.headlineSmall
                )
            }
        }

        // Sign In / Sign Out button
        Box(
            modifier = Modifier
                .clip(Shapes.small)
                .background(if (isLoggedIn) colors.bgTertiary else colors.snake)
                .clickable(onClick = if (isLoggedIn) onSignOut else onSignIn)
                .padding(horizontal = Spacing.sm, vertical = Spacing.xs)
        ) {
            Text(
                text = if (isLoggedIn) stringResource("sign_out") else stringResource("sign_in"),
                color = if (isLoggedIn) colors.textPrimary else Color.White,
                style = AppTheme.typography.labelMedium
            )
        }
    }
}

@Composable
private fun ThemeSection(
    currentTheme: ThemeMode,
    onThemeChange: (ThemeMode) -> Unit
) {
    val colors = AppTheme.colors

    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = stringResource("theme"),
            color = colors.textPrimary,
            style = AppTheme.typography.labelLarge,
            modifier = Modifier.weight(1f)
        )

        Row(
            horizontalArrangement = Arrangement.spacedBy(Spacing.xxs)
        ) {
            ThemeMode.entries.forEach { mode ->
                val isSelected = mode == currentTheme
                val icon = when (mode) {
                    ThemeMode.SYSTEM -> Res.drawable.ic_auto
                    ThemeMode.LIGHT -> Res.drawable.ic_sun
                    ThemeMode.DARK -> Res.drawable.ic_moon
                }
                val tooltipText = when (mode) {
                    ThemeMode.SYSTEM -> stringResource("system_theme")
                    ThemeMode.LIGHT -> stringResource("light_theme")
                    ThemeMode.DARK -> stringResource("dark_theme")
                }

                ThemeButton(
                    icon = icon,
                    tooltipText = tooltipText,
                    isSelected = isSelected,
                    onClick = { onThemeChange(mode) }
                )
            }
        }
    }
}

@Composable
private fun ThemeButton(
    icon: org.jetbrains.compose.resources.DrawableResource,
    tooltipText: String,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    val colors = AppTheme.colors
    var isTooltipVisible by remember { mutableStateOf(false) }

    // Auto-hide tooltip
    LaunchedEffect(isTooltipVisible) {
        if (isTooltipVisible) {
            delay(2000)
            isTooltipVisible = false
        }
    }

    Box(
        modifier = Modifier
            .size(IconButtonDimens.size)
            .clip(Shapes.medium)
            .background(if (isSelected) colors.snake else colors.bgTertiary)
            .pointerInput(Unit) {
                detectTapGestures(
                    onTap = { onClick() },
                    onLongPress = { isTooltipVisible = true }
                )
            },
        contentAlignment = Alignment.Center
    ) {
        Image(
            painter = painterResource(icon),
            contentDescription = tooltipText,
            modifier = Modifier.size(IconButtonDimens.iconSize),
            colorFilter = ColorFilter.tint(
                if (isSelected) Color.White else colors.textSecondary
            )
        )

        // Tooltip as Popup
        if (isTooltipVisible) {
            Popup(
                alignment = Alignment.TopCenter,
                offset = IntOffset(0, -60),
                onDismissRequest = { isTooltipVisible = false },
                properties = PopupProperties(focusable = false)
            ) {
                Box(
                    modifier = Modifier
                        .shadow(4.dp, Shapes.small)
                        .clip(Shapes.small)
                        .background(colors.bgElevated)
                        .padding(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Text(
                        text = tooltipText,
                        color = colors.textPrimary,
                        style = AppTheme.typography.caption
                    )
                }
            }
        }
    }
}

@Composable
private fun LanguageSection(
    currentLanguage: Language,
    onLanguageChange: (Language) -> Unit
) {
    val colors = AppTheme.colors
    var expanded by remember { mutableStateOf(false) }

    Column {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clip(Shapes.small)
                .clickable(
                    interactionSource = remember { MutableInteractionSource() },
                    indication = null // Disable ripple that can interfere with text colors on Android
                ) { expanded = !expanded }
                .padding(vertical = Spacing.xxs),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = stringResource("language"),
                color = colors.textPrimary,
                style = AppTheme.typography.labelLarge,
                modifier = Modifier.weight(1f)
            )

            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(Spacing.xxs)
            ) {
                // Language code badge
                Box(
                    modifier = Modifier
                        .clip(RoundedCornerShape(Spacing.xxs))
                        .background(colors.bgTertiary)
                        .padding(horizontal = 6.dp, vertical = 2.dp)
                ) {
                    Text(
                        text = currentLanguage.code.uppercase(),
                        color = colors.textTertiary,
                        style = AppTheme.typography.labelMedium
                    )
                }
                Text(
                    text = currentLanguage.nativeName,
                    color = colors.textSecondary,
                    style = AppTheme.typography.bodyMedium
                )
                Image(
                    painter = painterResource(if (expanded) Res.drawable.ic_arrow_up else Res.drawable.ic_arrow_down),
                    contentDescription = null,
                    modifier = Modifier.size(Spacing.sm),
                    colorFilter = ColorFilter.tint(colors.textTertiary)
                )
            }
        }

        AnimatedVisibility(visible = expanded) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = Spacing.xs),
                verticalArrangement = Arrangement.spacedBy(Spacing.xxs)
            ) {
                Language.entries.forEach { language ->
                    val isSelected = language == currentLanguage
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(Shapes.small)
                            .background(if (isSelected) colors.snake.copy(alpha = 0.1f) else Color.Transparent)
                            .clickable(
                                interactionSource = remember { MutableInteractionSource() },
                                indication = null // Disable ripple that can interfere with text colors on Android
                            ) {
                                onLanguageChange(language)
                                expanded = false
                            }
                            .padding(horizontal = Spacing.sm, vertical = Spacing.sm),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(Spacing.xs)
                    ) {
                        // Language code badge
                        Box(
                            modifier = Modifier
                                .clip(RoundedCornerShape(Spacing.xxs))
                                .background(if (isSelected) colors.snake.copy(alpha = 0.2f) else colors.bgTertiary)
                                .padding(horizontal = 6.dp, vertical = 2.dp)
                        ) {
                            Text(
                                text = language.code.uppercase(),
                                color = if (isSelected) colors.snake else colors.textTertiary,
                                style = AppTheme.typography.labelMedium
                            )
                        }
                        Text(
                            text = language.nativeName,
                            color = if (isSelected) colors.snake else colors.textPrimary,
                            style = if (isSelected) AppTheme.typography.labelLarge else AppTheme.typography.bodyMedium
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun MenuRow(
    icon: org.jetbrains.compose.resources.DrawableResource,
    title: String,
    subtitle: String? = null,
    accentColor: Color? = null,
    onClick: () -> Unit
) {
    val colors = AppTheme.colors
    val iconColor = accentColor ?: colors.textSecondary
    val titleColor = accentColor ?: colors.textPrimary

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(Shapes.small)
            .clickable(onClick = onClick)
            .padding(vertical = Spacing.xs),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(Spacing.sm)
    ) {
        Image(
            painter = painterResource(icon),
            contentDescription = null,
            modifier = Modifier.size(22.dp),
            colorFilter = ColorFilter.tint(iconColor)
        )

        Column(modifier = Modifier.weight(1f)) {
            Text(
                text = title,
                color = titleColor,
                style = AppTheme.typography.labelLarge
            )
            if (subtitle != null) {
                Text(
                    text = subtitle,
                    color = colors.textTertiary,
                    style = AppTheme.typography.caption
                )
            }
        }

        Image(
            painter = painterResource(Res.drawable.ic_chevron_right),
            contentDescription = null,
            modifier = Modifier.size(16.dp),
            colorFilter = ColorFilter.tint(colors.textTertiary)
        )
    }
}

@Composable
private fun Divider() {
    val colors = AppTheme.colors
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(1.dp)
            .background(colors.border)
    )
}
